import subprocess, time, os, sys, shlex
SESSION="xtest"
def tmux(*args):
    return subprocess.run(["tmux"]+list(args), capture_output=True, text=True)
def run_cmd(cmd, width=80, height=24, cwd="/tmp/testdir", wait=1.5, keys=None):
    tmux("kill-session","-t",SESSION); tmux("kill-server"); time.sleep(0.3)
    args=["new-session","-d","-s",SESSION,"-x",str(width),"-y",str(height),"-e","HOME=/tmp/fakehome","-e","TERM=xterm-256color","bash"]
    tmux(*args)
    tmux("send-keys","-t",SESSION,f"cd {shlex.quote(cwd)} && {cmd}","Enter")
    time.sleep(wait)
    if keys:
        for k in keys:
            if isinstance(k,(list,tuple)):
                tmux("send-keys","-t",SESSION,*k)
            else:
                tmux("send-keys","-t",SESSION,k)
            time.sleep(0.2)
        time.sleep(0.8)
    out=tmux("capture-pane","-t",SESSION,"-p","-S","-2000").stdout
    out_e=tmux("capture-pane","-t",SESSION,"-p","-e").stdout
    tmux("kill-session","-t",SESSION)
    return out, out_e
if __name__=="__main__":
    cmd=sys.argv[1]
    keys=sys.argv[2:]
    out,oute=run_cmd(cmd, keys=keys if keys else None, width=int(os.environ.get("W","80")), height=int(os.environ.get("H","24")), cwd=os.environ.get("CWD","/tmp/testdir"))
    print(out)
    if os.environ.get("E"): print("===ESC===\n"+oute)
