{"command":"cat > /tmp/extract.py << 'PY'
def extract_file(path):
    lines=open(path).read().splitlines()
    # find top-level keys
    res={}
    for i,l in enumerate(lines):
        if l.startswith("directory_buffer:"):
            # nodes relative paths
            rel=[]
            for k in range(i, len(lines)):
                if lines[k].startswith("  total:"):
                    res['total']=lines[k].strip()
                    res['focus']=lines[k+1].strip() if k+1<len(lines) else ""
                    break
                if lines[k].strip().startswith("relative_path:"):
                    rel.append(lines[k].strip().split(":",1)[1].strip())
            res['nodes']=rel
        if l.startswith("pwd:"): res['pwd']=l
        if l.startswith("selection:"):
            sel=[]
            for k in range(i+1,len(lines)):
                if lines[k] and not lines[k].startswith((" ","-")): break
                if "relative_path:" in lines[k]: sel.append(lines[k].strip())
            res['selection']=sel
        if l.startswith("mode:"):
            res['mode']=lines[i+1].strip() if i+1<len(lines) else ""
        if l.startswith("input:"):
            res['input']="\n".join(lines[i:i+3])
        if l=="history:":
            hist=[]
            for k in range(i, min(i+20,len(lines))):
                hist.append(lines[k])
                if lines[k].startswith("last_modes"): break
            res['history']="\n".join(hist)
        if l.startswith("explorer_config:"):
            res['explorer']="\n".join(lines[i:i+15])
        if l.startswith("logs:") and lines[i].strip()=="logs:" or l.startswith("logs:"):
            # top-level logs at near end; distinguish indent
            if not l.startswith(" "):
                res['logs']="\n".join(lines[i:i+15])
    for k,v in res.items(): print(k,":",v)
