"""Small YAML parser/emitter used for xplr messages and app state.

It intentionally implements the subset of YAML that is observable through
xplr (serde_yaml style input/output), including marked values so validation
errors can point at line/column positions.
"""
import re

class YamlSyntaxError(Exception):
    def __init__(self, message, line=None, col=None, context=None, context_line=None, context_col=None):
        super().__init__(message)
        self.message = message
        self.line = line
        self.col = col
        self.context = context
        self.context_line = context_line
        self.context_col = context_col
    def display(self, prefix=""):
        # serde_yaml style message without the outer "error:" prefix
        msg = self.message
        if self.line is not None:
            msg += f" at line {self.line} column {self.col}"
        if self.context:
            msg += f", while {self.context}"
            if self.context_line is not None:
                msg += f" at line {self.context_line} column {self.context_col}"
        return prefix + msg

class Marked:
    __slots__ = ("value", "line", "col", "end_line", "end_col", "kind", "raw")
    def __init__(self, value, line=1, col=1, kind="scalar", raw=None):
        self.value = value
        self.line = line
        self.col = col
        self.end_line = line
        self.end_col = col
        self.kind = kind  # scalar/map/seq/null/bool/int/float/str
        if kind in ("str",):
            self.kind = "str"
        self.raw = raw
    def __repr__(self):
        return f"Marked({self.value!r}@{self.line}:{self.col} {self.kind})"

class YMap:
    """ordered list of (key_marked, value_marked)"""
    def __init__(self, pairs=None):
        self.pairs = pairs or []
    def get(self, key, default=None):
        for k, v in self.pairs:
            if k.value == key:
                return v
        return default
    def keys(self):
        return [k.value for k, v in self.pairs]
    def __contains__(self, key):
        return any(k.value == key for k, v in self.pairs)
    def to_python(self):
        return {k.value: node_to_python(v) for k, v in self.pairs}

def node_to_python(node):
    if isinstance(node, Marked):
        v = node.value
        if isinstance(v, YMap):
            return v.to_python()
        if isinstance(v, list):
            return [node_to_python(x) for x in v]
        return v
    return node

_INT_RE = re.compile(r'^[-+]?[0-9][0-9_]*$')
_HEX_RE = re.compile(r'^0x[0-9a-fA-F_]+$')
_OCT_RE = re.compile(r'^0o[0-7_]+$')
_BIN_RE = re.compile(r'^0b[01_]+$')
_FLOAT_RE = re.compile(r'^[-+]?(\.[0-9]+|[0-9][0-9_]*(\.[0-9_]*)?)([eE][-+]?[0-9]+)?$')

def resolve_plain(raw):
    if raw == "" or raw == "~" or raw in ("null", "Null", "NULL"):
        return None, "null"
    if raw in ("true", "True", "TRUE"):
        return True, "bool"
    if raw in ("false", "False", "FALSE"):
        return False, "bool"
    if _HEX_RE.match(raw):
        try: return int(raw.replace("_", ""), 16), "int"
        except Exception: pass
    if _OCT_RE.match(raw):
        try: return int(raw.replace("_", "")[2:], 8), "int"
        except Exception: pass
    if _BIN_RE.match(raw):
        try: return int(raw.replace("_", "")[2:], 2), "int"
        except Exception: pass
    if _INT_RE.match(raw):
        try:
            # YAML may have leading zeroes; treat as decimal
            return int(raw.replace("_", ""), 10), "int"
        except Exception:
            pass
    low = raw.lower()
    if low in (".inf", "+.inf"):
        return float("inf"), "float"
    if low == "-.inf":
        return float("-inf"), "float"
    if low == ".nan":
        return float("nan"), "float"
    if _FLOAT_RE.match(raw) and ("." in raw or "e" in low):
        try: return float(raw.replace("_", "")), "float"
        except Exception: pass
    return raw, "str"

class Parser:
    def __init__(self, text):
        if isinstance(text, bytes):
            text = text.decode("utf-8", "surrogateescape")
        self.text = text
        self.n = len(text)
        self.pos = 0
        self.anchors = {}
        # line index for col computations
        self.line_starts = [0]
        for i, ch in enumerate(text):
            if ch == "\n":
                self.line_starts.append(i + 1)
        self._line_start_cache = self.line_starts

    def line_col(self, pos=None):
        if pos is None: pos = self.pos
        # binary search
        import bisect
        line_idx = bisect.bisect_right(self.line_starts, pos) - 1
        line = line_idx + 1
        col = pos - self.line_starts[line_idx] + 1
        return line, col

    def err(self, message, pos=None, context=None, ctx_pos=None):
        line, col = self.line_col(pos)
        cline = ccol = None
        if ctx_pos is not None:
            cline, ccol = self.line_col(ctx_pos)
        raise YamlSyntaxError(message, line, col, context, cline, ccol)

    def peek(self):
        return self.text[self.pos] if self.pos < self.n else ""

    def eof(self):
        return self.pos >= self.n

    # --- skipping helpers ---
    def skip_spaces_inline(self):
        while self.pos < self.n and self.text[self.pos] in " \t":
            self.pos += 1

    def skip_blank_lines_and_comments(self, min_indent=0):
        # Skips empty lines / comment-only lines.
        while True:
            # At start of a line (or after pos)
            save = self.pos
            i = self.pos
            while i < self.n and self.text[i] in " \t":
                i += 1
            if i < self.n and self.text[i] == "#":
                # comment to eol
                while i < self.n and self.text[i] != "\n":
                    i += 1
                self.pos = i
                if self.pos < self.n and self.text[self.pos] == "\n":
                    self.pos += 1
                continue
            if i < self.n and self.text[i] == "\n":
                self.pos = i + 1
                continue
            if i >= self.n:
                self.pos = i
                return
            self.pos = save
            return

    def current_line_indent(self):
        # Assumes pos at line start content or can compute
        line_start = self.text.rfind("\n", 0, self.pos) + 1
        i = line_start
        while i < self.n and self.text[i] == " ":
            i += 1
        return i - line_start, i

    def at_line_start_content(self):
        line_start = self.text.rfind("\n", 0, self.pos) + 1
        i = line_start
        while i < self.n and self.text[i] in " \t":
            i += 1
        return i

    # --- document ---
    def parse(self):
        self.skip_doc_preamble()
        if self.eof():
            line, col = self.line_col(self.pos)
            node = Marked(None, line, col, "null", "")
            return node
        # document start '---'
        if self.text.startswith("---", self.pos) and (self.pos + 3 >= self.n or self.text[self.pos+3] in " \t\r\n"):
            self.pos += 3
            self.skip_spaces_inline()
            if self.peek() == "\n":
                self.pos += 1
        node = self.parse_block(0)
        # trailing
        self.skip_blank_lines_and_comments()
        self.skip_spaces_inline()
        if not self.eof():
            # another document?
            if self.text.startswith("---", self.pos):
                raise YamlSyntaxError("deserializing from YAML containing more than one document is not supported")
            if self.text.startswith("...", self.pos):
                # document end marker; after it anything else is another doc
                self.pos += 3
                self.skip_blank_lines_and_comments()
                if not self.eof():
                    raise YamlSyntaxError("deserializing from YAML containing more than one document is not supported")
            # leftover content should have been consumed by block parser; if here, syntax problem
            # let caller treat it as error depending on context; produce generic message
            line, col = self.line_col(self.pos)
            # Try to mimic serde for stray content
            raise YamlSyntaxError("did not find expected <document start>", line, col)
        return node

    def skip_doc_preamble(self):
        # BOM
        if self.text.startswith("\ufeff"):
            self.pos += 1
        while True:
            self.skip_blank_lines_and_comments()
            if self.peek() == "%":
                # directive line
                line, col = self.line_col(self.pos)
                # '%YAML' etc: scan name
                j = self.pos + 1
                if j >= self.n or not (self.text[j].isalpha()):
                    raise YamlSyntaxError("could not find expected directive name", line, 2, "scanning a directive")
                while self.pos < self.n and self.text[self.pos] != "\n":
                    self.pos += 1
                if self.pos < self.n:
                    self.pos += 1
                continue
            break

    # --- block parsing ---
    def parse_block(self, min_indent):
        self.skip_blank_lines_and_comments()
        if self.eof():
            line, col = self.line_col(self.pos)
            return Marked(None, line, col, "null", "")
        indent, content_pos = self.current_line_indent_from(self.pos)
        if indent < min_indent:
            line, col = self.line_col(self.pos)
            return Marked(None, line, col, "null", "")
        self.pos = content_pos
        # sequence?
        if self.peek() == "-" and (self.pos + 1 >= self.n or self.text[self.pos+1] in " \t\r\n"):
            return self.parse_block_sequence(indent)
        # mapping?
        if self.lookahead_is_mapping(indent):
            return self.parse_block_mapping(indent)
        # scalar / flow
        return self.parse_node_inline_or_block(indent)

    def current_line_indent_from(self, pos):
        line_start = self.text.rfind("\n", 0, pos) + 1
        i = line_start
        while i < self.n and self.text[i] == " ":
            i += 1
        return i - line_start, i

    def lookahead_is_mapping(self, indent):
        # Determine if current line at self.pos has a key separator
        save = self.pos
        try:
            # quoted key
            if self.peek() in "\"'":
                self.parse_quoted()
                self.skip_spaces_inline()
                if self.peek() == ":" and (self.pos + 1 >= self.n or self.text[self.pos+1] in " \t\r\n"):
                    return True
                return False
            if self.peek() in "[{":
                # flow as key is uncommon; treat as not block mapping
                return False
            # scan line for ': ' or trailing ':'
            i = self.pos
            while i < self.n and self.text[i] != "\n":
                if self.text[i] == ":" and (i + 1 >= self.n or self.text[i+1] in " \t\r\n"):
                    # also ensure key isn't empty and no flow indicators in key (rough)
                    key_text = self.text[self.pos:i]
                    if key_text.strip() != "":
                        return True
                    return False
                if self.text[i] == "#" and i > self.pos and self.text[i-1] in " \t":
                    break
                i += 1
            return False
        finally:
            self.pos = save

    def parse_block_sequence(self, indent):
        start_pos = self.pos
        line, col = self.line_col(start_pos)
        items = []
        while True:
            self.skip_blank_lines_and_comments()
            if self.eof(): break
            ind, cpos = self.current_line_indent_from(self.pos)
            if ind != indent: break
            self.pos = cpos
            if not (self.peek() == "-" and (self.pos + 1 >= self.n or self.text[self.pos+1] in " \t\r\n")):
                break
            dash_pos = self.pos
            self.pos += 1
            # value may be on same line
            if self.peek() in " \t":
                self.skip_spaces_inline()
                if self.peek() == "\n" or self.eof():
                    # nested block
                    if self.peek() == "\n": self.pos += 1
                    val = self.parse_block(indent + 1)
                    items.append(val)
                    continue
                # inline content on same line: may be mapping whose first key is here
                # Treat content column as indent for mapping
                content_col_line, content_col = self.line_col(self.pos)
                content_indent = self.pos - (self.text.rfind("\n", 0, self.pos) + 1)
                if self.lookahead_is_mapping(content_indent):
                    val = self.parse_block_mapping(content_indent, first_line_pos=self.pos)
                else:
                    val = self.parse_node_inline_or_block(indent + 1)
                items.append(val)
            elif self.peek() == "\n":
                self.pos += 1
                val = self.parse_block(indent + 1)
                items.append(val)
            else:
                val = self.parse_node_inline_or_block(indent + 1)
                items.append(val)
        node = Marked(items, line, col, "seq")
        node.end_line, node.end_col = self.line_col(self.pos)
        return node

    def parse_block_mapping(self, indent, first_line_pos=None):
        start_pos = first_line_pos if first_line_pos is not None else self.pos
        line, col = self.line_col(start_pos)
        pairs = []
        seen = set()
        while True:
            if first_line_pos is None:
                self.skip_blank_lines_and_comments()
                if self.eof(): break
                ind, cpos = self.current_line_indent_from(self.pos)
                if ind != indent: break
                self.pos = cpos
            # else first line already positioned
            first_line_pos = None
            # must be mapping line
            if not self.lookahead_is_mapping(indent):
                break
            key_node = self.parse_key()
            # duplicate detection (plain string keys)
            key_repr = key_node.value if isinstance(key_node.value, (str, int, bool)) or key_node.value is None else str(key_node.value)
            if key_repr in seen:
                raise YamlSyntaxError(f'duplicate entry with key "{key_repr}"')
            seen.add(key_repr)
            self.skip_spaces_inline()
            # colon
            if self.peek() != ":":
                line2, col2 = self.line_col(self.pos)
                raise YamlSyntaxError("did not find expected ':'", line2, col2, "while parsing a block mapping")
            self.pos += 1
            # value
            # check same-line value
            val_start = self.pos
            self.skip_spaces_inline()
            if self.peek() == "\n" or self.eof():
                if self.peek() == "\n": self.pos += 1
                # nested block or null
                save = self.pos
                self.skip_blank_lines_and_comments()
                if self.eof():
                    l2, c2 = self.line_col(val_start)
                    val = Marked(None, l2, c2, "null", "")
                else:
                    nind, _ = self.current_line_indent_from(self.pos)
                    if nind > indent:
                        self.pos = save
                        # parse_block will skip blanks; but need rewind to just after newline
                        # Our parse_block expects pos somewhere; set to after newline position
                        # We already have save at line beginnings; use it
                        val = self.parse_block(indent + 1)
                    else:
                        self.pos = save
                        l2, c2 = self.line_col(val_start)
                        val = Marked(None, l2, c2, "null", "")
                pairs.append((key_node, val))
                continue
            else:
                # same line value
                # could be a block scalar indicator
                if self.peek() in "|>":
                    val = self.parse_block_scalar(indent)
                else:
                    # inline node; but if rest of lines are indented more and are not map/seq, plain scalar multiline? handled in parse_node
                    val = self.parse_node_inline_or_block(indent)
                pairs.append((key_node, val))
                # after a same-line value, continue loop; if trailing junk on line, parse_node should have errored or consumed
                # If we're not at line end, there may be an issue e.g. "a: b c: d" -> parse_node plain would consume whole? plain scanner stops at ': ' error
                # ensure we are at eol/comment/eof
                self.skip_spaces_inline()
                if self.peek() not in ("", "\n", "#"):
                    # Unexpected content after value on same line (e.g. 'a' 'b')
                    l2, c2 = self.line_col(self.pos)
                    raise YamlSyntaxError("did not find expected key", l2, c2, "while parsing a block mapping")
                if self.peek() == "#":
                    while self.pos < self.n and self.text[self.pos] != "\n": self.pos += 1
                if self.peek() == "\n":
                    self.pos += 1
                continue
        node = Marked(YMap(pairs), line, col, "map")
        node.end_line, node.end_col = self.line_col(self.pos)
        return node

    def parse_key(self):
        self.skip_spaces_inline()
        if self.peek() in "\"'":
            return self.parse_quoted()
        start = self.pos
        line, col = self.line_col(start)
        i = self.pos
        while i < self.n:
            c = self.text[i]
            if c == ":" and (i + 1 >= self.n or self.text[i+1] in " \t\r\n"):
                break
            if c == "\n":
                break
            i += 1
        raw = self.text[self.pos:i].strip()
        self.pos = i
        val, kind = resolve_plain(raw)
        node = Marked(val, line, col, kind, raw)
        node.end_line, node.end_col = self.line_col(i)
        return node

    def parse_node_inline_or_block(self, parent_indent):
        # handles anchors/tags then flow/scalar
        self.skip_spaces_inline()
        start = self.pos
        line, col = self.line_col(start)
        # anchor / tag
        anchor_name = None
        while True:
            if self.peek() == "&":
                self.pos += 1
                s = self.pos
                while self.pos < self.n and self.text[self.pos] not in " \t\r\n[]{},":
                    self.pos += 1
                anchor_name = self.text[s:self.pos]
                self.skip_spaces_inline()
                if self.peek() == "\n":
                    # anchor alone on line -> value is following block
                    self.pos += 1
                    val = self.parse_block(parent_indent)
                    if anchor_name: self.anchors[anchor_name] = val
                    return val
                continue
            if self.peek() == "!":
                # tag: skip until whitespace
                while self.pos < self.n and self.text[self.pos] not in " \t\r\n":
                    self.pos += 1
                self.skip_spaces_inline()
                continue
            break
        ch = self.peek()
        if ch == "*":
            self.pos += 1
            s = self.pos
            while self.pos < self.n and self.text[self.pos] not in " \t\r\n[]{},":
                self.pos += 1
            name = self.text[s:self.pos]
            if name not in self.anchors:
                l2, c2 = self.line_col(start)
                raise YamlSyntaxError("unknown anchor", l2, c2)
            return self.anchors[name]
        if ch == "[":
            val = self.parse_flow_sequence()
        elif ch == "{":
            val = self.parse_flow_mapping()
        elif ch in "\"'":
            val = self.parse_quoted()
            # check for block plain continuation? quoted scalar single line is done
        elif ch in "|>":
            # at node position (not after key) treat as block scalar with parent indent suggestion
            val = self.parse_block_scalar(parent_indent - 1 if parent_indent > 0 else 0)
        elif ch == "":
            val = Marked(None, line, col, "null", "")
        else:
            if ch in "%@`":
                self.err("found character that cannot start any token", start, "while scanning for the next token")
            val = self.parse_plain_scalar_block(parent_indent)
        if anchor_name:
            self.anchors[anchor_name] = val
        return val

    def parse_plain_scalar_block(self, parent_indent):
        start = self.pos
        line, col = self.line_col(start)
        # Consume until end of line (stopping at ' #')
        i = self.pos
        while i < self.n and self.text[i] != "\n":
            if self.text[i] == "#" and i > start and self.text[i-1] in " \t":
                break
            if self.text[i] == ":" and i + 1 < self.n and self.text[i+1] in " \t":
                # mapping value inside a plain scalar context
                # If we're at top/block scalar context, this is an error
                self.err("mapping values are not allowed in this context", i)
            i += 1
        raw = self.text[self.pos:i].rstrip(" \t\r")
        endpos = i
        # multiline plain scalars: following lines more indented and not a new mapping/sequence
        # Note: This is relevant mainly for a scalar value on its own line. To keep it simple,
        # only fold if next line indent > parent_indent and line isn't map/seq and raw != ""
        extra_parts = []
        save = i
        pos_after = i
        while True:
            p = pos_after
            if p < self.n and self.text[p] == "\n":
                p += 1
            else:
                break
            # peek next line
            q = p
            while q < self.n and self.text[q] == " ":
                q += 1
            if q >= self.n or self.text[q] == "\n" or self.text[q] == "#":
                break
            nind = q - p
            if nind <= parent_indent:
                break
            # if it's a mapping/sequence at that deeper indent, it belongs to a parent structure, not this scalar
            # Heuristic: stop
            break
        self.pos = endpos
        if self.pos < self.n and self.text[self.pos] == "#":
            pass
        val, kind = resolve_plain(raw)
        node = Marked(val, line, col, kind, raw)
        node.end_line, node.end_col = self.line_col(endpos)
        return node

    def parse_quoted(self):
        start = self.pos
        line, col = self.line_col(start)
        quote = self.text[self.pos]
        self.pos += 1
        out = []
        if quote == "'":
            while True:
                if self.eof():
                    self.err("found unexpected end of stream", self.pos, "while scanning a quoted scalar", start)
                c = self.text[self.pos]
                if c == "'":
