                        hexs = self.text[self.pos+1:self.pos+5]
                        try: out.append(chr(int(hexs, 16)))
                        except Exception: out.append("u")
                        self.pos += 5; continue
                    if e == "U":
                        hexs = self.text[self.pos+1:self.pos+9]
                        try: out.append(chr(int(hexs, 16)))
                        except Exception: out.append("U")
                        self.pos += 9; continue
                    out.append(escapes.get(e, e)); self.pos += 1; continue
                out.append(c); self.pos += 1
            s = "".join(out)
        node = Marked(s, line, col, "str", s)
        node.end_line, node.end_col = self.line_col(self.pos)
        return node

    def skip_flow_separators(self):
        while self.pos < self.n:
            c = self.text[self.pos]
            if c in " \t\r\n":
                self.pos += 1; continue
            if c == "#":
                while self.pos < self.n and self.text[self.pos] != "\n": self.pos += 1
                continue
            break

    def parse_flow_sequence(self):
        start = self.pos
        line, col = self.line_col(start)
        self.pos += 1 # [
        items = []
        while True:
            self.skip_flow_separators()
            if self.eof():
                self.err("did not find expected ',' or ']'", self.pos, "while parsing a flow sequence", start)
            if self.peek() == "]":
                self.pos += 1; break
            if self.peek() == ",":
                # trailing comma allowed
                self.pos += 1; continue
            item = self.parse_flow_node()
            items.append(item)
            self.skip_flow_separators()
            if self.peek() == ",":
                self.pos += 1; continue
            if self.peek() == "]":
                self.pos += 1; break
            if self.eof():
                self.err("did not find expected ',' or ']'", self.pos, "while parsing a flow sequence", start)
            # else loop will report
        node = Marked(items, line, col, "seq")
        node.end_line, node.end_col = self.line_col(self.pos)
        return node

    def parse_flow_mapping(self):
        start = self.pos
        line, col = self.line_col(start)
        self.pos += 1 # {
        pairs = []
        seen = set()
        while True:
            self.skip_flow_separators()
            if self.eof():
                self.err("did not find expected ',' or '}'", self.pos, "while parsing a flow mapping", start)
            if self.peek() == "}":
                self.pos += 1; break
            if self.peek() == ",":
                self.pos += 1; continue
            # key
            key_node = self.parse_flow_node(in_key=True)
            self.skip_flow_separators()
            if self.peek() != ":":
                self.err("did not find expected ',' or '}'", self.pos, "while parsing a flow mapping", start)
            self.pos += 1
            self.skip_flow_separators()
            if self.peek() in ",}":
                l2, c2 = self.line_col(self.pos)
                val = Marked(None, l2, c2, "null", "")
            else:
                val = self.parse_flow_node()
            key_repr = key_node.value if isinstance(key_node.value, (str, int, bool)) or key_node.value is None else str(key_node.value)
            if key_repr in seen:
                raise YamlSyntaxError(f'duplicate entry with key "{key_repr}"')
            seen.add(key_repr)
            pairs.append((key_node, val))
            self.skip_flow_separators()
            if self.peek() == ",":
                self.pos += 1; continue
            if self.peek() == "}":
                self.pos += 1; break
            if self.eof():
                self.err("did not find expected ',' or '}'", self.pos, "while parsing a flow mapping", start)
        node = Marked(YMap(pairs), line, col, "map")
        node.end_line, node.end_col = self.line_col(self.pos)
        return node

    def parse_flow_node(self, in_key=False):
        self.skip_flow_separators()
        start = self.pos
        line, col = self.line_col(start)
        # anchor/tag
        anchor_name = None
        while True:
            if self.peek() == "&":
                self.pos += 1; s = self.pos
                while self.pos < self.n and self.text[self.pos] not in " \t\r\n[]{},": self.pos += 1
                anchor_name = self.text[s:self.pos]; self.skip_flow_separators(); continue
            if self.peek() == "!":
                while self.pos < self.n and self.text[self.pos] not in " \t\r\n": self.pos += 1
                self.skip_flow_separators(); continue
            break
        ch = self.peek()
        if ch == "*":
            self.pos += 1; s = self.pos
            while self.pos < self.n and self.text[self.pos] not in " \t\r\n[]{},": self.pos += 1
            name = self.text[s:self.pos]
            if name not in self.anchors:
                raise YamlSyntaxError("unknown anchor", line, col)
            return self.anchors[name]
        if ch == "[":
            return self.parse_flow_sequence()
        if ch == "{":
            return self.parse_flow_mapping()
        if ch in "\"'":
            return self.parse_quoted()
        if ch == "" :
            self.err("did not find expected node content", self.pos, "while parsing a flow node", start)
        # plain flow scalar: until , ] } or : (when looking for key separator)
        i = self.pos
        depth = 0
        while i < self.n:
            c = self.text[i]
            if c in ",]}" :
                break
            if c == ":" and (i + 1 >= self.n or self.text[i+1] in " \t\r\n,]}"):
                # in value context, a colon followed by space inside flow scalar is a problem:
                # e.g. {a: b: c} serde errors; treat colon as terminator for key, else keep scanning and let mapping parser handle
                break
            if c == "#" and i > start and self.text[i-1] in " \t":
                break
            if c == "\n" and in_key:
                # flow can span lines, continue
                pass
            i += 1
        raw = self.text[self.pos:i].strip()
        # If the terminator is ':' and we're parsing a value (not key), serde would complain
        # about mapping values; but flow mapping parser handles key itself. If caller was parse_flow_node for a plain value
        # in a sequence like [a: b], YAML treats it as a single-pair map. We approximate by returning scalar.
        self.pos = i
        val, kind = resolve_plain(raw)
        node = Marked(val, line, col, kind, raw)
        node.end_line, node.end_col = self.line_col(i)
        if anchor_name: self.anchors[anchor_name] = node
        return node

    def parse_block_scalar(self, parent_indent):
        start = self.pos
        line, col = self.line_col(start)
        style = self.text[self.pos]; self.pos += 1
        chomp = None; indent_indicator = None
        while self.peek() in "+-123456789":
            c = self.peek()
            if c in "+-": chomp = c
            else: indent_indicator = int(c)
            self.pos += 1
        self.skip_spaces_inline()
        if self.peek() == "#":
            while self.pos < self.n and self.text[self.pos] != "\n": self.pos += 1
        if self.peek() == "\n": self.pos += 1
        # collect lines
        lines = []
        block_indent = None
        while self.pos < self.n:
            line_start = self.pos
            # find eol
            eol = self.text.find("\n", self.pos)
            if eol == -1: eol = self.n
            raw_line = self.text[line_start:eol]
            stripped = raw_line.lstrip(" ")
            ind = len(raw_line) - len(stripped)
            if stripped == "":
                lines.append("")
                self.pos = eol + 1 if eol < self.n else eol
                continue
            if block_indent is None:
                block_indent = ind if indent_indicator is None else parent_indent + indent_indicator
                if ind <= parent_indent:
                    break
            if ind < block_indent:
                break
            lines.append(raw_line[block_indent:] if len(raw_line) >= block_indent else "")
            self.pos = eol + 1 if eol < self.n else eol
        if block_indent is None: block_indent = parent_indent + 1
        # Remove trailing blank lines for processing, remember
        if style == "|":
            body = "\n".join(lines)
            if lines: body += "\n"
        else: # folded >
            # fold single newlines to spaces, keep blank lines
            out = []
            prev_blank = False
            for idx, l in enumerate(lines):
                if l == "":
                    out.append("\n"); prev_blank = True
                else:
                    if idx > 0 and not prev_blank:
                        out.append(" ")
                    out.append(l); prev_blank = False
            body = "".join(out)
            if lines: body += "\n"
        if chomp == "-":
            body = body.rstrip("\n")
            # keep no trailing newline
            body = body.rstrip("\n") if False else body
            # literal strip: remove all trailing newlines
            while body.endswith("\n"): body = body[:-1]
        elif chomp == "+":
            pass
        else:
            # clip: single trailing newline
            body = body.rstrip("\n") + ("\n" if body else "")
        node = Marked(body, line, col, "str", body)
        node.end_line, node.end_col = self.line_col(self.pos)
        return node

def parse_yaml(text):
    return Parser(text).parse()

def to_python(node):
    return node_to_python(node)

# ---------------- YAML emitter (serde_yaml-like) ----------------

def _is_plain_safe(s):
    if s == "":
        return False
    # resolve would change type?
    val, kind = resolve_plain(s)
    if kind != "str":
        return False
    if s != s.strip():
        return False
    # indicator starting chars
    if s[0] in "-?:,[]{}#&*!|>'\"%@`":
        # '-' is allowed if second char not space; but to be safe quote those cases like serde does for '?' etc
        if s[0] in "?:{}[],&*#|>@`\"'!%":
            return False
        if s[0] == "-" and (len(s) == 1 or s[1] == " "):
            return False
    if ": " in s or ":\t" in s or s.endswith(":"):
        return False
    if " #" in s:
        return False
    if any(ord(c) < 0x20 and c not in ("\n",) for c in s):
        return False
    if "\n" in s:
        return False
    # colon without space is okay (URLs) etc
    return True

def _quote_single(s):
    return "'" + s.replace("'", "''") + "'"

def _quote_double(s):
    out = []
    for ch in s:
        if ch == '"': out.append('\\"')
        elif ch == "\\": out.append('\\\\')
        elif ch == "\n": out.append('\\n')
        elif ch == "\r": out.append('\\r')
        elif ch == "\t": out.append('\\t')
        elif ch == "\0": out.append('\\0')
        elif ord(ch) < 0x20 or ord(ch) == 0x7f:
            out.append(f'\\x{ord(ch):02x}')
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'

def format_scalar(v):
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        if v != v:
            return ".nan"
        if v == float("inf"):
            return ".inf"
        if v == float("-inf"):
            return "-.inf"
        # serde_yaml prints minimal, keeping .0 for integral floats
        if v == int(v) and abs(v) < 1e15:
            return f"{v:.1f}"
        return repr(v)
    if isinstance(v, str):
        if v == "":
            return "''"
        if any((ord(c) < 0x20 and c != "\n") or c == "\n" for c in v):
            return _quote_double(v)
        if _is_plain_safe(v):
            return v
        # serde tends to use single quotes for strings needing quoting
        return _quote_single(v)
    return str(v)

def _emit(value, indent):
    lines = []
    prefix = " " * indent
    if isinstance(value, dict):
        if not value:
            lines.append(prefix + "{}")
            return lines
        for k, v in value.items():
            ks = format_scalar(str(k) if not isinstance(k, str) else k)
            if isinstance(v, dict):
                if not v:
                    lines.append(f"{prefix}{ks}: {{}}")
                else:
                    lines.append(f"{prefix}{ks}:")
                    lines.extend(_emit(v, indent + 2))
            elif isinstance(v, (list, tuple)):
                if not v:
                    lines.append(f"{prefix}{ks}: []")
                else:
                    lines.append(f"{prefix}{ks}:")
                    # serde_yaml: sequences under mapping are not extra-indented
                    lines.extend(_emit_seq(v, indent))
            else:
                lines.append(f"{prefix}{ks}: {format_scalar(v)}")
        return lines
    if isinstance(value, (list, tuple)):
        return _emit_seq(value, indent)
    lines.append(prefix + format_scalar(value))
    return lines

def _emit_seq(seq, indent):
    lines = []
    prefix = " " * indent
    for item in seq:
        if isinstance(item, dict):
            if not item:
                lines.append(f"{prefix}- {{}}")
            else:
                first = True
                for k, v in item.items():
                    ks = format_scalar(str(k) if not isinstance(k, str) else k)
                    head = f"{prefix}- " if first else f"{prefix}  "
                    first = False
                    if isinstance(v, dict):
                        if not v:
                            lines.append(f"{head}{ks}: {{}}")
                        else:
                            lines.append(f"{head}{ks}:")
                            lines.extend(_emit(v, indent + 4))
                    elif isinstance(v, (list, tuple)):
                        if not v:
                            lines.append(f"{head}{ks}: []")
                        else:
                            lines.append(f"{head}{ks}:")
                            lines.extend(_emit_seq(v, indent + 2))
                    else:
                        lines.append(f"{head}{ks}: {format_scalar(v)}")
        elif isinstance(item, (list, tuple)):
            if not item:
                lines.append(f"{prefix}- []")
            else:
                sub = _emit_seq(item, indent + 2)
                # merge first line
                if sub:
                    lines.append(f"{prefix}- " + sub[0][indent+2:])
                    lines.extend(sub[1:])
                else:
                    lines.append(f"{prefix}- []")
        else:
            lines.append(f"{prefix}- {format_scalar(item)}")
    return lines

def dump_yaml(value):
    if isinstance(value, dict) or isinstance(value, (list, tuple)):
        lines = _emit(value, 0)
    else:
        lines = [format_scalar(value)]
    return "\n".join(lines) + "\n"
