import re

class YamlSyntaxError(Exception):
    def __init__(self, message, line=None, col=None, context=None, context_line=None, context_col=None):
        super().__init__(message)
        self.message = message
        self.line = line
        self.col = col
        self.context = context
        self.context_line = context_line
        self.context_col = context_col
    def display(self, prefix=""):
        # serde_yaml style message without the outer "error:" prefix
        msg = self.message
        if self.line is not None:
            msg += f" at line {self.line} column {self.col}"
        if self.context:
            msg += f", while {self.context}"
            if self.context_line is not None:
                msg += f" at line {self.context_line} column {self.context_col}"
        return prefix + msg

class Marked:
    __slots__ = ("value", "line", "col", "end_line", "end_col", "kind", "raw")
    def __init__(self, value, line=1, col=1, kind="scalar", raw=None):
        self.value = value
        self.line = line
        self.col = col
        self.end_line = line
        self.end_col = col
        self.kind = kind  # scalar/map/seq/null/bool/int/float/str
        if kind in ("str",):
            self.kind = "str"
        self.raw = raw
    def __repr__(self):
        return f"Marked({self.value!r}@{self.line}:{self.col} {self.kind})"

class YMap:
    """ordered list of (key_marked, value_marked)"""
    def __init__(self, pairs=None):
        self.pairs = pairs or []
    def get(self, key, default=None):
        for k, v in self.pairs:
            if k.value == key:
                return v
        return default
    def keys(self):
        return [k.value for k, v in self.pairs]
    def __contains__(self, key):
        return any(k.value == key for k, v in self.pairs)
    def to_python(self):
        return {k.value: node_to_python(v) for k, v in self.pairs}

def node_to_python(node):
    if isinstance(node, Marked):
        v = node.value
        if isinstance(v, YMap):
            return v.to_python()
        if isinstance(v, list):
            return [node_to_python(x) for x in v]
        return v
    return node

_INT_RE = re.compile(r'^[-+]?[0-9][0-9_]*$')
_HEX_RE = re.compile(r'^0x[0-9a-fA-F_]+$')
_OCT_RE = re.compile(r'^0o[0-7_]+$')
_BIN_RE = re.compile(r'^0b[01_]+$')
_FLOAT_RE = re.compile(r'^[-+]?(\.[0-9]+|[0-9][0-9_]*(\.[0-9_]*)?)([eE][-+]?[0-9]+)?$')

def resolve_plain(raw):
    if raw == "" or raw == "~" or raw in ("null", "Null", "NULL"):
        return None, "null"
    if raw in ("true", "True", "TRUE"):
        return True, "bool"
    if raw in ("false", "False", "FALSE"):
        return False, "bool"
    if _HEX_RE.match(raw):
        try: return int(raw.replace("_", ""), 16), "int"
        except Exception: pass
    if _OCT_RE.match(raw):
        try: return int(raw.replace("_", "")[2:], 8), "int"
        except Exception: pass
    if _BIN_RE.match(raw):
        try: return int(raw.replace("_", "")[2:], 2), "int"
        except Exception: pass
    if _INT_RE.match(raw):
        try:
            # YAML may have leading zeroes; treat as decimal
            return int(raw.replace("_", ""), 10), "int"
        except Exception:
            pass
    low = raw.lower()
    if low in (".inf", "+.inf"):
        return float("inf"), "float"
    if low == "-.inf":
        return float("-inf"), "float"
    if low == ".nan":
        return float("nan"), "float"
    if _FLOAT_RE.match(raw) and ("." in raw or "e" in low):
        try: return float(raw.replace("_", "")), "float"
        except Exception: pass
    return raw, "str"

