"""A small Lua 5.1 interpreter (enough for xplr configuration/plugins).

Written from scratch from the Lua language behaviour.  Values map to Python
as: nil->None, boolean->bool, number->int/float, string->str,
table->LuaTable, function->LuaFunction/native callables.
"""
import math, re, sys, os

# ---------------------------------------------------------------- values
class MultiReturn:
    __slots__ = ("values",)
    def __init__(self, values): self.values = tuple(values)

class LuaReturn(Exception):
    def __init__(self, values): self.values = tuple(values)
class LuaBreak(Exception):
    pass

class LuaError(Exception):
    def __init__(self, value, state=None, no_trace=False):
        self.value = value
        self.no_trace = no_trace
        if isinstance(value, str):
            self.message = value
        else:
            self.message = None  # filled when stringified
        # snapshot frames (list of description strings generated by caller)
        self.trace = None
        super().__init__(self.message if self.message is not None else value)

class LuaSyntaxError(Exception):
    def __init__(self, msg, line, chunk_display, near=None):
        self.msg = msg
        self.line = line
        self.chunk_display = chunk_display
        self.near = near
        text = f"{chunk_display}:{line}: {msg}"
        if near is not None:
            text += f" near '{near}'"
        super().__init__(text)
        self.text = text

class Cell:
    __slots__ = ("value",)
    def __init__(self, value=None): self.value = value

class Scope:
    __slots__ = ("vars", "parent")
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent
    def find(self, name):
        s = self
        while s is not None:
            if name in s.vars: return s.vars[name]
            s = s.parent
        return None

def _norm_key(v):
    if isinstance(v, bool):
        return ("b", v)
    if isinstance(v, (int, float)):
        if isinstance(v, float):
            if math.isnan(v): return ("nan",)
            if v == int(v) and abs(v) < 9e18: return ("n", int(v))
        return ("n", v)
    if isinstance(v, str):
        return ("s", v)
    return ("o", id(v))

class LuaTable:
    def __init__(self):
        self._data = {}  # normkey -> [origkey, value]
        self.metatable = None
    def rawget(self, key, default=None):
        if key is None: return default
        e = self._data.get(_norm_key(key))
        return e[1] if e else default
    def has(self, key):
        return key is not None and _norm_key(key) in self._data
    def rawset(self, key, value):
        if key is None: raise ValueError("table index is nil")
        nk = _norm_key(key)
        if value is None:
            self._data.pop(nk, None)
        elif nk in self._data:
            self._data[nk][1] = value
        else:
            self._data[nk] = [key, value]
    def items(self):
        return [(e[0], e[1]) for e in self._data.values()]
    def keys(self):
        return [e[0] for e in self._data.values()]
    def array_len(self):
        n = 0
        while (n + 1) in [k for k in self.keys() if isinstance(k, int)]:
            # (kept simple; used only for border checks on small tables)
            n += 1
            if n > 1000000: break
        # faster contiguous count
        n = 0
        d = self._data
        while _norm_key(n + 1) in d:
            n += 1
        return n
    def is_array_like(self):
        if not self._data: return False
        ks = self.keys()
        if all(isinstance(k, int) for k in ks):
            return sorted(ks) == list(range(1, len(ks) + 1))
        return False
    def __repr__(self):
        return f"table: 0x{id(self):x}"

class LuaFunction:
    def __init__(self, params, is_vararg, body, closure_scope, state, chunk_display, line_defined, name_hint=None):
        self.params = params
        self.is_vararg = is_vararg
        self.body = body
        self.closure_scope = closure_scope
        self.state = state
        self.chunk_display = chunk_display
        self.line_defined = line_defined
        self.name_hint = name_hint
    def __repr__(self): return f"function: 0x{id(self):x}"

class NativeFunction:
    def __init__(self, func, name=""):
        self.func = func
        self.name = name
    def __repr__(self): return f"function: 0x{id(self):x}"

class LuaUserdata:
    """Wrapper for host objects (file handles etc)."""
    def __init__(self, obj, typename="userdata", fields=None, methods=None):
        self.obj = obj
        self.typename = typename
        self.fields = fields or {}
        self.methods = methods or {}
        self.metatable = None
    def __repr__(self): return f"{self.typename}: 0x{id(self):x}"

def lua_type(v):
    if v is None: return "nil"
    if isinstance(v, bool): return "boolean"
    if isinstance(v, (int, float)): return "number"
    if isinstance(v, str): return "string"
    if isinstance(v, LuaTable): return "table"
    if isinstance(v, (LuaFunction, NativeFunction)): return "function"
    if isinstance(v, LuaUserdata): return "userdata"
    return "userdata"

def lua_tostring_num(v):
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, float):
        if math.isnan(v): return "nan"
        if math.isinf(v): return "inf" if v > 0 else "-inf"
        s = format(v, ".14g")
        return s
    return str(v)

def lua_tostring(state, v):
    if v is None: return "nil"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, (int, float)): return lua_tostring_num(v)
    if isinstance(v, str): return v
    # metamethod
    mt = get_metatable(v)
    if mt is not None:
        f = mt.rawget("__tostring") if isinstance(mt, LuaTable) else None
        if f is not None:
            r = state.call(f, [v])
            return lua_tostring(state, r)
    if isinstance(v, LuaTable): return f"table: 0x{id(v):x}"
    if isinstance(v, (LuaFunction, NativeFunction)): return f"function: 0x{id(v):x}"
    if isinstance(v, LuaUserdata): return f"{v.typename}: 0x{id(v):x}"
    return str(v)

def get_metatable(v):
    if isinstance(v, (LuaTable, LuaUserdata)):
        return v.metatable
    return None

def lua_tonumber(v):
    if isinstance(v, bool): return None
    if isinstance(v, (int, float)): return v
    if isinstance(v, str):
        s = v.strip()
        if not s: return None
        try:
            if re.match(r'^0[xX][0-9a-fA-F]+$', s): return int(s, 16)
            if re.match(r'^[-+]?[0-9]+$', s): return int(s)
            return float(s)
        except Exception:
            return None
    return None

def lua_truthy(v):
    return not (v is None or v is False)

# ---------------------------------------------------------------- lexer
KEYWORDS = {"and","break","do","else","elseif","end","false","for","function","goto","if","in","local","nil","not","or","repeat","return","then","true","until","while"}

class Token:
    __slots__ = ("kind", "value", "line", "text")
    def __init__(self, kind, value, line, text=None):
        self.kind = kind; self.value = value; self.line = line; self.text = text if text is not None else value
    def __repr__(self): return f"Tok({self.kind},{self.value!r}@{self.line})"

class Lexer:
    def __init__(self, code, chunk_display):
        self.code = code
        self.chunk = chunk_display
        self.pos = 0
        self.line = 1
        self.n = len(code)
    def error(self, msg, near=None, line=None):
        raise LuaSyntaxError(msg, line or self.line, self.chunk, near)
    def tokens(self):
        out = []
        while True:
            t = self.next_token()
            out.append(t)
            if t.kind == "eof": break
        return out
    def skip_ws_comments(self):
        while self.pos < self.n:
            c = self.code[self.pos]
            if c in " \t\r\f\v":
                self.pos += 1; continue
            if c == "\n":
                self.pos += 1; self.line += 1; continue
            if self.code.startswith("--", self.pos):
                # long comment?
                j = self.pos + 2
                level, long_start = self._long_bracket(j)
                if long_start is not None:
                    end = self._long_end(long_start, level)
                    segment = self.code[self.pos:end]
                    self.line += segment.count("\n")
                    self.pos = end
                else:
                    while self.pos < self.n and self.code[self.pos] != "\n": self.pos += 1
                continue
            break
    def _long_bracket(self, j):
        if j < self.n and self.code[j] == "[":
            k = j + 1
            level = 0
            while k < self.n and self.code[k] == "=":
                level += 1; k += 1
            if k < self.n and self.code[k] == "[":
                return level, k + 1
        return 0, None
    def _long_end(self, start, level):
        close = "]" + "=" * level + "]"
        idx = self.code.find(close, start)
        if idx < 0:
            self.error("unfinished long string/comment")
        return idx + len(close)
    def next_token(self):
        self.skip_ws_comments()
        if self.pos >= self.n:
            return Token("eof", "<eof>", self.line, "<eof>")
        c = self.code[self.pos]
        line = self.line
        # name / keyword
        if c.isalpha() or c == "_" or ord(c) >= 128:
            s = self.pos
            while self.pos < self.n and (self.code[self.pos].isalnum() or self.code[self.pos] == "_" or ord(self.code[self.pos]) >= 128):
                self.pos += 1
            word = self.code[s:self.pos]
            if word in KEYWORDS:
                return Token(word, word, line)
            return Token("name", word, line)
        # number
        if c.isdigit() or (c == "." and self.pos + 1 < self.n and self.code[self.pos+1].isdigit()):
            s = self.pos
            if self.code.startswith(("0x", "0X"), self.pos):
                self.pos += 2
                while self.pos < self.n and (self.code[self.pos] in "0123456789abcdefABCDEF"): self.pos += 1
                text = self.code[s:self.pos]
                try: val = int(text, 16)
                except Exception: val = 0
                return Token("number", val, line, text)
            while self.pos < self.n and (self.code[self.pos].isdigit() or self.code[self.pos] == "."):
                if self.code[self.pos] == "." and self.pos + 1 < self.n and self.code[self.pos+1] == ".":
                    break
                self.pos += 1
            if self.pos < self.n and self.code[self.pos] in "eE":
                self.pos += 1
                if self.pos < self.n and self.code[self.pos] in "+-": self.pos += 1
                while self.pos < self.n and self.code[self.pos].isdigit(): self.pos += 1
            text = self.code[s:self.pos]
            try:
                val = float(text) if ("." in text or "e" in text or "E" in text) else int(text)
            except Exception:
                val = 0
            return Token("number", val, line, text)
        # string
        if c in "\"'":
            return self._short_string()
        if c == "[":
            level, start = self._long_bracket(self.pos)
            if start is not None:
                end = self._long_end(start, level)
                content_start = start
                if content_start < self.n and self.code[content_start] == "\n": content_start += 1
                # end position excludes closing bracket
                close_len = level + 2
                content = self.code[content_start:end - close_len]
                segment = self.code[self.pos:end]
                self.line += segment.count("\n")
                self.pos = end
                return Token("string", content, line, content)
            self.pos += 1
            return Token("[", "[", line)
        # vararg / concat etc
        three = self.code[self.pos:self.pos+3]
        two = self.code[self.pos:self.pos+2]
        if three == "...":
            self.pos += 3; return Token("...", "...", line)
        if two in ("..", "==", "~=", "<=", ">="):
            self.pos += 2; return Token(two, two, line)
        if c in "+-*/%^#(){}[];:,.=<>":
            self.pos += 1; return Token(c, c, line)
        # invalid char
        self.pos += 1
        return Token("invalid", c, line, c)
    def _short_string(self):
        quote = self.code[self.pos]
        line = self.line
        self.pos += 1
        out = []
        escapes = {"a":"\a","b":"\b","f":"\f","n":"\n","r":"\r","t":"\t","v":"\v","\\":"\\",'"':'"',"'":"'"}
        while self.pos < self.n:
            c = self.code[self.pos]
            if c == quote:
                self.pos += 1
                return Token("string", "".join(out), line)
            if c == "\n":
                self.error("unfinished string", near=quote, line=line)
            if c == "\\":
                self.pos += 1
                if self.pos >= self.n: break
                e = self.code[self.pos]
                if e == "\n":
                    out.append("\n"); self.pos += 1; self.line += 1; continue
                if e.isdigit():
                    s = ""
                    for _ in range(3):
                        if self.pos < self.n and self.code[self.pos].isdigit():
                            s += self.code[self.pos]; self.pos += 1
                        else: break
                    out.append(chr(int(s) & 0xff)); continue
                if e == "x" and self.pos + 2 < self.n + 1:
                    hexs = self.code[self.pos+1:self.pos+3]
                    try:
                        out.append(chr(int(hexs, 16))); self.pos += 3; continue
                    except Exception: pass
                out.append(escapes.get(e, e)); self.pos += 1; continue
            out.append(c); self.pos += 1
        self.error("unfinished string", near=quote, line=line)

# ---------------------------------------------------------------- parser
# AST nodes are tuples whose first element is a tag.
class Parser:
    def __init__(self, code, chunk_display):
        self.lexer = Lexer(code, chunk_display)
        self.toks = self.lexer.tokens()
        self.i = 0
        self.chunk = chunk_display
    def tok(self): return self.toks[self.i]
    def peek_kind(self, k=0):
        j = min(self.i + k, len(self.toks) - 1)
        return self.toks[j].kind
    def next(self):
        t = self.toks[self.i]; self.i += 1; return t
    def accept(self, kind):
        if self.tok().kind == kind:
            return self.next()
        return None
    def expect(self, kind, display=None):
        if self.tok().kind == kind:
            return self.next()
        t = self.tok()
        near = t.text if t.kind != "eof" else "<eof>"
        disp = display if display is not None else kind
        raise LuaSyntaxError(f"'{disp}' expected", t.line, self.chunk, near)
    def expect_expr_error(self):
        t = self.tok()
        near = t.text if t.kind != "eof" else "<eof>"
        if t.kind == "invalid":
            raise LuaSyntaxError("unexpected symbol", t.line, self.chunk, near)
        raise LuaSyntaxError("unexpected symbol", t.line, self.chunk, near)

    def parse_chunk(self):
        body = self.parse_block(top=True)
        if self.tok().kind != "eof":
            t = self.tok()
            raise LuaSyntaxError("'<eof>' expected", t.line, self.chunk, t.text)
        return body

    def parse_block(self, top=False):
        stmts = []
        while self.tok().kind not in ("eof", "end", "else", "elseif", "until"):
            if self.accept(";"):
                continue
            # return must be last
            if self.tok().kind == "return":
                stmts.append(self.parse_return())
                self.accept(";")
                break
            stmts.append(self.parse_statement())
        return ("block", stmts)

    def parse_return(self):
        line = self.next().line  # return
        exprs = []
        if self.tok().kind not in ("eof", "end", "else", "elseif", "until", ";"):
            exprs = self.parse_exprlist()
        return ("return", exprs, line)

    def parse_statement(self):
        t = self.tok()
        if t.kind == "do":
            self.next(); body = self.parse_block(); self.expect("end")
            return ("do", body, t.line)
        if t.kind == "while":
            self.next(); cond = self.parse_expr(); self.expect("do"); body = self.parse_block(); self.expect("end")
            return ("while", cond, body, t.line)
        if t.kind == "repeat":
            self.next(); body = self.parse_block(); self.expect("until"); cond = self.parse_expr()
            return ("repeat", body, cond, t.line)
        if t.kind == "if":
            return self.parse_if()
        if t.kind == "for":
            return self.parse_for()
        if t.kind == "local":
            return self.parse_local()
        if t.kind == "function":
            return self.parse_function_statement()
        if t.kind == "break":
            self.next(); return ("break", t.line)
        if t.kind == "goto":
            # LuaJIT goto: skip (unsupported label semantics)
            self.next()
            name = self.expect("name")
            return ("do", ("block", []), t.line)
        if t.kind == ";":
            self.next(); return ("do", ("block", []), t.line)
        # label ::name:: (LuaJIT)
        if t.kind == ":":
            # handled as suffix? labels use '::'
            self.next(); self.expect(":"); self.expect("name"); self.expect(":"); self.expect(":")
            return ("do", ("block", []), t.line)
        # assignment or call statement
        expr = self.parse_suffixed_expr()
        if self.tok().kind in ("=", ","):
            targets = [expr]
            while self.accept(","):
                targets.append(self.parse_suffixed_expr())
            self.expect("=")
            values = self.parse_exprlist()
            for tg in targets:
                if tg[0] not in ("var", "index"):
                    raise LuaSyntaxError("'=' expected", t.line, self.chunk, self.tok().text)
            return ("assign", targets, values, t.line)
        if expr[0] in ("call", "methodcall"):
            return ("callstmt", expr, t.line)
        # e.g. bare name followed by something else
        nt = self.tok()
        near = nt.text if nt.kind != "eof" else "<eof>"
        raise LuaSyntaxError("'=' expected", nt.line, self.chunk, near)

    def parse_if(self):
        line = self.next().line
        cases = []
        cond = self.parse_expr(); self.expect("then"); body = self.parse_block(); cases.append((cond, body))
        else_body = None
        while self.tok().kind == "elseif":
            self.next(); c = self.parse_expr(); self.expect("then"); b = self.parse_block(); cases.append((c, b))
        if self.tok().kind == "else":
            self.next(); else_body = self.parse_block()
        self.expect("end")
        return ("if", cases, else_body, line)

    def parse_for(self):
        line = self.next().line
        first = self.expect("name")
        if self.accept("="):
            start = self.parse_expr(); self.expect(","); stop = self.parse_expr()
            step = None
            if self.accept(","): step = self.parse_expr()
            self.expect("do"); body = self.parse_block(); self.expect("end")
            return ("fornum", first.value, start, stop, step, body, line)
        names = [first.value]
        while self.accept(","):
            names.append(self.expect("name").value)
        self.expect("in")
        exprs = self.parse_exprlist()
        self.expect("do"); body = self.parse_block(); self.expect("end")
        return ("forin", names, exprs, body, line)

    def parse_local(self):
        line = self.next().line
        if self.tok().kind == "function":
            self.next(); name_tok = self.expect("name")
            func = self.parse_function_body(line, is_method=False)
            return ("localfunc", name_tok.value, func, line)
        names = [self.expect("name").value]
        while self.accept(","):
            names.append(self.expect("name").value)
        values = []
        if self.accept("="):
            values = self.parse_exprlist()
        return ("local", names, values, line)

    def parse_function_statement(self):
        line = self.next().line  # function
        # name chain
        base_tok = self.expect("name")
        expr = ("var", base_tok.value, base_tok.line)
        is_method = False
        while self.accept("."):
            nt = self.expect("name")
            expr = ("index", expr, ("str", nt.value, nt.line), nt.line)
        if self.accept(":"):
            nt = self.expect("name")
            expr = ("index", expr, ("str", nt.value, nt.line), nt.line)
            is_method = True
        func = self.parse_function_body(line, is_method=is_method)
        return ("assign", [expr], [func], line)

    def parse_function_body(self, line, is_method=False):
        self.expect("(")
        params = []
        is_vararg = False
        if self.tok().kind != ")":
            while True:
                if self.tok().kind == "...":
                    self.next(); is_vararg = True; break
                params.append(self.expect("name").value)
                if not self.accept(","): break
        self.expect(")")
        if is_method:
            params = ["self"] + params
        body = self.parse_block()
        self.expect("end")
        return ("function", params, is_vararg, body, line)

    def parse_exprlist(self):
        exprs = [self.parse_expr()]
        while self.accept(","):
            exprs.append(self.parse_expr())
        return exprs

    # expressions, lowest to highest
    def parse_expr(self): return self.parse_or()
    def parse_or(self):
        left = self.parse_and()
        while self.tok().kind == "or":
            op = self.next(); right = self.parse_and(); left = ("binop", "or", left, right, op.line)
        return left
    def parse_and(self):
        left = self.parse_compare()
        while self.tok().kind == "and":
            op = self.next(); right = self.parse_compare(); left = ("binop", "and", left, right, op.line)
        return left
    def parse_compare(self):
        left = self.parse_concat()
        while self.tok().kind in ("<", ">", "<=", ">=", "~=", "=="):
            op = self.next(); right = self.parse_concat(); left = ("binop", op.kind, left, right, op.line)
        return left
    def parse_concat(self):
        left = self.parse_add()
        if self.tok().kind == "..":
            op = self.next(); right = self.parse_concat(); return ("binop", "..", left, right, op.line)
        return left
    def parse_add(self):
        left = self.parse_mul()
        while self.tok().kind in ("+", "-"):
            op = self.next(); right = self.parse_mul(); left = ("binop", op.kind, left, right, op.line)
        return left
    def parse_mul(self):
        left = self.parse_unary()
        while self.tok().kind in ("*", "/", "%"):
            op = self.next(); right = self.parse_unary(); left = ("binop", op.kind, left, right, op.line)
        return left
    def parse_unary(self):
        t = self.tok()
        if t.kind in ("not", "-", "#"):
            self.next(); operand = self.parse_unary(); return ("unop", t.kind, operand, t.line)
        return self.parse_pow()
    def parse_pow(self):
        left = self.parse_suffixed_expr()
        if self.tok().kind == "^":
            op = self.next(); right = self.parse_unary(); return ("binop", "^", left, right, op.line)
        return left

    def parse_suffixed_expr(self):
        expr = self.parse_primary()
        while True:
            t = self.tok()
            if t.kind == ".":
                self.next(); nt = self.expect("name")
                expr = ("index", expr, ("str", nt.value, nt.line), nt.line)
                continue
            if t.kind == "[":
                self.next(); key = self.parse_expr(); self.expect("]")
                expr = ("index", expr, key, t.line)
                continue
            if t.kind == ":":
                self.next(); nt = self.expect("name")
                args = self.parse_call_args()
                expr = ("methodcall", expr, nt.value, args, nt.line)
                continue
            if t.kind == "(" or t.kind == "string" or t.kind == "{":
                args = self.parse_call_args()
                expr = ("call", expr, args, t.line)
                continue
            break
        return expr

    def parse_call_args(self):
        t = self.tok()
        if t.kind == "(":
            self.next()
            args = []
            if self.tok().kind != ")":
                args = self.parse_exprlist()
            self.expect(")")
            return args
        if t.kind == "string":
            self.next(); return [("str", t.value, t.line)]
        if t.kind == "{":
            return [self.parse_table()]
        self.expect_expr_error()

    def parse_primary(self):
        t = self.tok()
        if t.kind == "number": self.next(); return ("num", t.value, t.line)
        if t.kind == "string": self.next(); return ("str", t.value, t.line)
        if t.kind == "true": self.next(); return ("bool", True, t.line)
        if t.kind == "false": self.next(); return ("bool", False, t.line)
        if t.kind == "nil": self.next(); return ("nil", t.line)
        if t.kind == "...": self.next(); return ("vararg", t.line)
        if t.kind == "name": self.next(); return ("var", t.value, t.line)
        if t.kind == "function":
            self.next(); return self.parse_function_body(t.line)
        if t.kind == "{":
            return self.parse_table()
        if t.kind == "(":
            self.next(); e = self.parse_expr(); self.expect(")")
            return ("paren", e, t.line)
        self.expect_expr_error()

    def parse_table(self):
        line = self.expect("{").line
        fields = []
        while self.tok().kind != "}":
            if self.tok().kind == "[":
                self.next(); key = self.parse_expr(); self.expect("]"); self.expect("=")
                val = self.parse_expr(); fields.append(("key", key, val))
            elif self.tok().kind == "name" and self.peek_kind(1) == "=":
                nt = self.next(); self.next()  # name, =
                val = self.parse_expr(); fields.append(("named", nt.value, val))
            else:
                val = self.parse_expr(); fields.append(("pos", val))
            if self.tok().kind in (",", ";"):
                self.next()
                if self.tok().kind == "}": break
                continue
            break
        self.expect("}")
        return ("table", fields, line)

