# ---------------------------------------------------------------- evaluator
class Frame:
    __slots__ = ("chunk", "line_defined", "current_line", "is_main", "name")
    def __init__(self, chunk, line_defined, is_main=False, name=None):
        self.chunk = chunk; self.line_defined = line_defined; self.current_line = line_defined
        self.is_main = is_main; self.name = name

class LuaState:
    def __init__(self):
        self.globals = LuaTable()
        self.frames = []
        self.app_ref = None
        self.package_loaded = None
        _install_stdlib(self)
        self.globals.rawset("_G", self.globals)
        self.globals.rawset("_VERSION", "Lua 5.1")

    # ------------- errors -------------
    def make_trace(self, via_error=False, c_label=None):
        lines = ["stack traceback:"]
        if c_label:
            lines.append(f"\t[C]: in metamethod '{c_label}'")
        else:
            lines.append("\t[C]: in ?")
        if via_error:
            lines.append("\t[C]: in function 'error'")
        for fr in reversed(self.frames):
            if fr.is_main:
                lines.append(f"\t{fr.chunk}:{fr.current_line}: in main chunk")
            else:
                lines.append(f"\t{fr.chunk}:{fr.current_line}: in function <{fr.chunk}:{fr.line_defined}>")
        return "\n".join(lines)

    def runtime_error(self, message, via_error=False, c_label=None):
        err = LuaError(message, self)
        err.trace = self.make_trace(via_error=via_error, c_label=c_label)
        err.via_error = via_error
        raise err

    # ------------- calls -------------
    def call_multi(self, fn, args, name_hint=None):
        args = list(args)
        if isinstance(fn, NativeFunction):
            try:
                r = fn.func(self, args)
            except LuaError:
                raise
            except SystemExit:
                raise
            except Exception as e:
                err = LuaError(str(e), self)
                err.trace = self.make_trace()
                raise err
