        _op_error(state, "perform arithmetic on", bexpr, scope, bad)
    try:
        if op == "+": return ln + rn
        if op == "-": return ln - rn
        if op == "*": return ln * rn
        if op == "/": return ln / rn if rn != 0 else (float("inf") if ln > 0 else float("-inf") if ln < 0 else float("nan"))
        if op == "%":
            if rn == 0: return float("nan") if isinstance(ln, float) else 0
