def lua_equals(state, a, b):
    if isinstance(a, (int, float)) and not isinstance(a, bool) and isinstance(b, (int, float)) and not isinstance(b, bool):
        return a == b
    if type(a) != type(b) and not (a is None and b is None):
        # Lua tables/functions compare by reference unless __eq
        if isinstance(a, (LuaTable, LuaUserdata)) and isinstance(b, (LuaTable, LuaUserdata)):
            pass
        else:
            return False
    if isinstance(a, (LuaTable, LuaUserdata)) or isinstance(b, (LuaTable, LuaUserdata)):
        if a is b: return True
        ma, mb = get_metatable(a), get_metatable(b)
        if ma is not None and ma is mb and isinstance(ma, LuaTable):
