    if op == ">": return x > y
    if op == "<=": return x <= y
    return x >= y

def load_lua_chunk(state, code, chunk_display, args=()):
    parser = Parser(code, chunk_display)
    body = parser.parse_chunk()
    scope = Scope(None)
    scope.vars["..."] = Cell(MultiReturn(args))
    frame = Frame(chunk_display, 1, True)
    state.frames.append(frame)
    try:
        exec_block(state, body, scope, frame)
        result = ()
    except LuaReturn as ret:
        result = ret.values
    finally:
        state.frames.pop()
    return result

