                        'w': 'A-Za-z0-9', 'x': '0-9A-Fa-f',
                    }
                    if nx in cls: parts.append(cls[nx]); j += 2; continue
                    if nx.isupper() and nx.lower() in ('a','d','s','u','l','w','x'):
                        # negated class inside a set: approximate by excluding common; fallback to literal
                        parts.append(re.escape(nx)); j += 2; continue
                    parts.append(re.escape(nx)); j += 2; continue
                if pat[j] in "\\]":
                    parts.append("\\" + pat[j]); j += 1; continue
                parts.append(pat[j]); j += 1
            out.append("[" + ("^" if neg else "") + "".join(parts) + "]")
            i = j + 1 if j < n else j
            continue
        if c == "(":
            groups += 1; out.append("("); i += 1; continue
        if c == ")":
            out.append(")"); i += 1; continue
        if c == ".":
            out.append("."); i += 1; continue
        if c in "*+?":
            out.append(c); i += 1; continue
        if c == "-":
            out.append("*?"); i += 1; continue
        if c == "^" and i == 0:
            out.append(r'\A'); i += 1; continue
        if c == "$" and i == n - 1:
            out.append(r'\Z'); i += 1; continue
        out.append(re.escape(c)); i += 1
    return "".join(out), groups

def _compile_lua_pattern(pat):
    anchored = pat.startswith("^")
    rx, groups = _lua_pattern_to_regex(pat)
    try:
        cre = re.compile(rx, re.DOTALL)
    except Exception:
        cre = re.compile(re.escape(pat), re.DOTALL)
    return cre, groups, anchored

def _match_captures(m):
    if m.re.groups == 0:
        return [m.group(0)]
    return [g for g in m.groups()]

def _str_arg(state, v):
    if isinstance(v, str): return v
    if isinstance(v, (int, float)) and not isinstance(v, bool): return lua_tostring(state, v)
    return v

def _install_string(state):
    lib = LuaTable()
    def f(name):
        def deco(fn):
            lib.rawset(name, NativeFunction(fn, "string." + name)); return fn
        return deco
    @f("len")
    def _len(st, a): return len(_str_arg(st, _arg(a, 0, "")))
    @f("sub")
    def _sub(st, a):
        s = _str_arg(st, _arg(a, 0, "")); L = len(s)
        i = _toint(_arg(a, 1, 1)) or 1; j = _toint(_arg(a, 2, -1))
        if j is None: j = -1
        if i < 0: i = L + i + 1
        if j < 0: j = L + j + 1
        i = max(1, i); j = min(L, j)
        if i > j: return ""
        return s[i-1:j]
    @f("upper")
    def _upper(st, a): return _str_arg(st, _arg(a, 0, "")).upper()
    @f("lower")
    def _lower(st, a): return _str_arg(st, _arg(a, 0, "")).lower()
    @f("rep")
    def _rep(st, a):
        s = _str_arg(st, _arg(a, 0, "")); n = _toint(_arg(a, 1, 0)) or 0
        sep = _str_arg(st, _arg(a, 2, "")) or ""
        return sep.join([s] * max(0, n))
    @f("reverse")
    def _rev(st, a): return _str_arg(st, _arg(a, 0, ""))[::-1]
    @f("byte")
    def _byte(st, a):
        s = _str_arg(st, _arg(a, 0, "")); L = len(s)
        i = _toint(_arg(a, 1, 1)) or 1; j = _toint(_arg(a, 2, i)); 
        if j is None: j = i
        if i < 0: i = L + i + 1
        if j < 0: j = L + j + 1
        vals = [ord(s[k-1]) for k in range(max(1,i), min(L,j)+1)]
        return MultiReturn(vals)
    @f("char")
    def _char(st, a):
        return "".join(chr(int(lua_tonumber(x) or 0)) for x in a)
    @f("find")
    def _find(st, a):
        s = _str_arg(st, _arg(a, 0, "")); pat = _str_arg(st, _arg(a, 1, ""))
        init = _toint(_arg(a, 2, 1)) or 1; plain = lua_truthy(_arg(a, 3, False))
        if init < 0: init = len(s) + init + 1
        init = max(1, init); start = init - 1
        if plain:
            idx = s.find(pat, start)
            if idx < 0: return None
            return MultiReturn((idx + 1, idx + len(pat)))
        cre, groups, anchored = _compile_lua_pattern(pat)
        m = cre.match(s, start) if anchored else cre.search(s, start)
        if not m: return None
        caps = _match_captures(m) if groups else []
        return MultiReturn(tuple([m.start() + 1, m.end()] + (caps if groups else [])))
    @f("match")
    def _match(st, a):
        s = _str_arg(st, _arg(a, 0, "")); pat = _str_arg(st, _arg(a, 1, ""))
        init = _toint(_arg(a, 2, 1)) or 1
        if init < 0: init = len(s) + init + 1
        start = max(0, init - 1)
        cre, groups, anchored = _compile_lua_pattern(pat)
        m = cre.match(s, start) if anchored else cre.search(s, start)
        if not m: return None
        if groups: return MultiReturn(tuple(_match_captures(m)))
        return m.group(0)
    @f("gmatch")
    def _gmatch(st, a):
        s = _str_arg(st, _arg(a, 0, "")); pat = _str_arg(st, _arg(a, 1, ""))
        cre, groups, anchored = _compile_lua_pattern(pat)
        pos = [0]
        def iterator(st2, inner):
            if pos[0] > len(s): return None
            m = cre.search(s, pos[0])
            if not m: pos[0] = len(s) + 1; return None
            pos[0] = m.end() if m.end() > m.start() else m.end() + 1
            if groups: return MultiReturn(tuple(_match_captures(m)))
            return m.group(0)
        return NativeFunction(iterator, "gmatch iterator")
    @f("gsub")
    def _gsub(st, a):
        s = _str_arg(st, _arg(a, 0, "")); pat = _str_arg(st, _arg(a, 1, ""))
        repl = _arg(a, 2, ""); maxn = _toint(_arg(a, 3, 0))
        limit = maxn if maxn else 0
        cre, groups, anchored = _compile_lua_pattern(pat)
        count = [0]
        def do_repl(m):
            if limit and count[0] >= limit:
                return m.group(0)
            count[0] += 1
            if isinstance(repl, str):
                def rep_ref(mm):
                    g = mm.group(1)
                    if g == "%": return "%"
                    idx = int(g)
                    if idx == 0: return m.group(0)
                    try: return m.group(idx) or ""
                    except Exception: return ""
                return re.sub(r'%([%0-9])', rep_ref, repl)
            if isinstance(repl, LuaTable):
                key = m.group(1) if groups and m.re.groups >= 1 else m.group(0)
                v = repl.rawget(key)
                if isinstance(v, (str, int, float)): return lua_tostring(st, v)
                return m.group(0)
            if _is_callable(repl):
                vals = _match_captures(m) if groups else [m.group(0)]
                r = st.call(repl, vals)
                if isinstance(r, (str, int, float)) and not isinstance(r, bool): return lua_tostring(st, r)
                if r is None or r is False: return m.group(0)
                return lua_tostring(st, r)
            return lua_tostring(st, repl)
        if anchored:
            # re.sub with anchored pattern only matches at start anyway via \A
            pass
        new_s, made = cre.subn(do_repl, s, count=0)
        # subn counts all; our do_repl limit logic still counted limited subs correctly enough
        return MultiReturn((new_s, made if not limit else count[0]))
    @f("format")
    def _format(st, a):
        if not a: return ""
        fmt = _str_arg(st, a[0]); rest = list(a[1:])
        return _lua_format(st, fmt, rest)
    lib.rawset("dump", NativeFunction(lambda st, a: "", "string.dump"))
    return lib

def _lua_format(state, fmt, args):
    out = []
    ai = 0
    i = 0
    while i < len(fmt):
        c = fmt[i]
        if c != "%":
            out.append(c); i += 1; continue
        if i + 1 < len(fmt) and fmt[i+1] == "%":
            out.append("%"); i += 2; continue
        j = i + 1
        flags = ""
        while j < len(fmt) and fmt[j] in "-+ #0": flags += fmt[j]; j += 1
        width = ""
        if j < len(fmt) and fmt[j] == "*":
            width_val = int(lua_tonumber(args[ai]) or 0); ai += 1; width = str(width_val); j += 1
        else:
            while j < len(fmt) and fmt[j].isdigit(): width += fmt[j]; j += 1
        prec = None
        if j < len(fmt) and fmt[j] == ".":
            j += 1
            if j < len(fmt) and fmt[j] == "*":
                prec = int(lua_tonumber(args[ai]) or 0); ai += 1; j += 1
            else:
                p = ""
                while j < len(fmt) and fmt[j].isdigit(): p += fmt[j]; j += 1
                prec = int(p) if p else 0
        if j < len(fmt) and fmt[j] in "hlL": j += 1
        if j >= len(fmt): out.append("%"); break
        spec = fmt[j]; j += 1
        val = args[ai] if ai < len(args) else None; ai += 1
        if spec == "q":
            s = val if isinstance(val, str) else lua_tostring(state, val)
            out.append(_lua_quote(s))
        elif spec == "s":
            s = lua_tostring(state, val)
            if prec is not None: s = s[:prec]
            out.append(_pad(s, flags, width))
        elif spec == "c":
            if isinstance(val, (int, float)): s = chr(int(val))
            elif isinstance(val, str): s = val[:1]
            else: s = ""
            out.append(_pad(s, flags, width))
        elif spec in "diu":
            num = lua_tonumber(val) or 0
            iv = int(num)
            if spec == "u" and iv < 0: iv = iv & 0xffffffffffffffff
            s = str(iv)
            out.append(_pad_num(s, flags, width, prec))
        elif spec in "oxX":
            iv = int(lua_tonumber(val) or 0)
            s = format(iv & 0xffffffffffffffff if iv < 0 else iv, spec)
            if "#" in flags and spec == "x": s = "0x" + s
            if "#" in flags and spec == "X": s = "0X" + s
            if "#" in flags and spec == "o": s = "0" + s
            out.append(_pad_num(s, flags, width, prec))
        elif spec in "eEfgG":
            fv = float(lua_tonumber(val) or 0)
            pyfmt = "%" + ("#" if "#" in flags else "") + ("." + str(prec) if prec is not None else "") + spec
            try: s = pyfmt % fv
            except Exception: s = str(fv)
            out.append(_pad_num(s, flags, width, None))
        else:
            out.append("%" + spec)
        i = j
    return "".join(out)

def _lua_quote(s):
    out = ['"']
    for ch in s:
        if ch == '"': out.append('\\"')
        elif ch == "\\": out.append('\\\\')
        elif ch == "\n": out.append('\\\n')
        elif ch == "\r": out.append('\\r')
        elif ord(ch) < 32 or ord(ch) == 127:
            out.append('\\%03d' % ord(ch))
        else: out.append(ch)
    out.append('"')
    return "".join(out)

def _pad(s, flags, width):
    if not width: return s
    w = int(width)
    if len(s) >= w: return s
    if "-" in flags: return s + " " * (w - len(s))
    return " " * (w - len(s)) + s

def _pad_num(s, flags, width, prec):
    if prec is not None and s.lstrip("-").isdigit():
        sign = "-" if s.startswith("-") else ""
        digits = s[1:] if sign else s
        digits = digits.rjust(prec, "0")
        s = sign + digits
    if not width: return s
    w = int(width)
    if len(s) >= w: return s
    if "-" in flags: return s + " " * (w - len(s))
    if "0" in flags and prec is None:
        if s[:1] in "+- ":
            return s[0] + s[1:].rjust(w - 1, "0")
        return s.rjust(w, "0")
    return s.rjust(w)

def _install_stdlib(state):
    g = state.globals
    # ---- basic ----
    def nf(name, fn): g.rawset(name, NativeFunction(fn, name))
    nf("tostring", lambda st, a: lua_tostring(st, _arg(a, 0)))
    nf("type", lambda st, a: lua_type(_arg(a, 0)))
    nf("select", _fn_select)
    nf("pairs", _fn_pairs)
    nf("ipairs", _fn_ipairs)
    nf("next", _fn_next)
    nf("tonumber", _fn_tonumber)
    nf("error", _fn_error)
    nf("assert", _fn_assert)
    nf("pcall", _fn_pcall)
    nf("xpcall", _fn_xpcall)
    nf("print", _fn_print)
    nf("rawget", lambda st, a: _arg(a, 0).rawget(_arg(a, 1)) if isinstance(_arg(a, 0), LuaTable) else None)
    nf("rawset", _fn_rawset)
    nf("rawequal", lambda st, a: lua_equals(st, _arg(a, 0), _arg(a, 1)))
    nf("rawlen", lambda st, a: len(_arg(a, 0)) if isinstance(_arg(a, 0), str) else (_arg(a, 0).array_len() if isinstance(_arg(a, 0), LuaTable) else 0))
    nf("setmetatable", _fn_setmt)
    nf("getmetatable", _fn_getmt)
    nf("unpack", _fn_unpack)
    nf("require", _fn_require)
    nf("loadstring", _fn_loadstring)
    nf("load", _fn_loadstring)
    nf("loadfile", _fn_loadfile)
    nf("dofile", _fn_dofile)
    nf("collectgarbage", lambda st, a: 0)
    nf("gcinfo", lambda st, a: 0)
    # string
    g.rawset("string", _install_string(state))
    # table
    g.rawset("table", _install_table(state))
    # math
    g.rawset("math", _install_math())
    # os / io / package
    g.rawset("os", _install_os(state))
    g.rawset("io", _install_io(state))
    pkg = LuaTable()
    pkg.rawset("path", os.environ.get("LUA_PATH", "./?.lua;/usr/local/share/lua/5.1/?.lua;/usr/local/share/lua/5.1/?/init.lua;/usr/local/lib/lua/5.1/?.lua;/usr/local/lib/lua/5.1/?/init.lua;/usr/share/lua/5.1/?.lua;/usr/share/lua/5.1/?/init.lua"))
    pkg.rawset("cpath", os.environ.get("LUA_CPATH", ""))
    loaded = LuaTable(); pkg.rawset("loaded", loaded)
    state.package_loaded = loaded
    pkg.rawset("preload", LuaTable())
    g.rawset("package", pkg)
    # coroutine (minimal)
    co = LuaTable(); co.rawset("status", NativeFunction(lambda st, a: "dead", "coroutine.status"))
    g.rawset("coroutine", co)
    dbg = LuaTable(); dbg.rawset("traceback", NativeFunction(lambda st, a: (lua_tostring(st, _arg(a, 0)) if _arg(a, 0) is not None else "") + "\n" + st.make_trace(), "debug.traceback"))
    g.rawset("debug", dbg)

def _fn_select(st, a):
    if not a: return 0
    idx = a[0]
    if idx == "#": return len(a) - 1
    n = int(lua_tonumber(idx) or 0)
    if n > 0: return MultiReturn(a[n:]) if n < len(a) else MultiReturn(())
    return MultiReturn(a[len(a) + n:]) if len(a) + n >= 1 else MultiReturn(())

def _next_impl(table, key):
    if not isinstance(table, LuaTable): return MultiReturn(())
    items = table.items()
    if key is None:
        if not items: return MultiReturn(())
        return MultiReturn((items[0][0], items[0][1]))
    for i, (k, v) in enumerate(items):
        if lua_equals(None, k, key):
            if i + 1 >= len(items): return MultiReturn(())
            return MultiReturn((items[i+1][0], items[i+1][1]))
    return MultiReturn(())

def _fn_next(st, a):
    return _next_impl(_arg(a, 0), _arg(a, 1))

def _fn_pairs(st, a):
    t = _arg(a, 0)
    return MultiReturn((NativeFunction(lambda st2, inner: _next_impl(inner[0], inner[1] if len(inner) > 1 else None), "next"), t, None))

def _fn_ipairs(st, a):
    t = _arg(a, 0)
    def iterf(st2, inner):
        tbl, i = inner[0], int(lua_tonumber(inner[1]) or 0)
        if not isinstance(tbl, LuaTable): return None
        v = tbl.rawget(i + 1)
        if v is None: return None
        return MultiReturn((i + 1, v))
    return MultiReturn((NativeFunction(iterf, "ipairs iterator"), t, 0))

def _fn_tonumber(st, a):
    v = _arg(a, 0); base = _arg(a, 1)
    if base is None: return lua_tonumber(v)
    if isinstance(v, str):
        try: return int(v.strip(), int(lua_tonumber(base) or 10))
        except Exception: return None
    return None

def _fn_error(st, a):
    val = _arg(a, 0)
    level = int(lua_tonumber(_arg(a, 1, 1)) or 1)
    if isinstance(val, str) and level > 0:
        frames = st.frames
        idx = len(frames) - level
        if 0 <= idx < len(frames):
            fr = frames[idx]
            val = f"{fr.chunk}:{fr.current_line}: " + val
    st.runtime_error(val if isinstance(val, str) else lua_tostring(st, val), via_error=True)

def _fn_assert(st, a):
    if not a or not lua_truthy(a[0]):
        msg = _arg(a, 1)
        if msg is None: msg = "assertion failed!"
        # level 2-ish: caller's location
        if isinstance(msg, str) and st.frames:
            fr = st.frames[-1]; msg = f"{fr.chunk}:{fr.current_line}: " + msg
        st.runtime_error(msg if isinstance(msg, str) else lua_tostring(st, msg), via_error=True)
    return MultiReturn(tuple(a))

def _fn_pcall(st, a):
    fn = _arg(a, 0); rest = list(a[1:])
    if fn is None:
        return MultiReturn((False, "attempt to call a nil value"))
    try:
        vals = st.call_multi(fn, rest)
        return MultiReturn(tuple([True] + list(vals)))
    except LuaError as e:
        return MultiReturn((False, e.value if isinstance(e.value, str) else lua_tostring(st, e.value) if e.value is not None else e.message))
    except SystemExit:
        raise
    except Exception as e:
        return MultiReturn((False, str(e)))

def _fn_xpcall(st, a):
    fn = _arg(a, 0); handler = _arg(a, 1); rest = list(a[2:])
    try:
        vals = st.call_multi(fn, rest)
        return MultiReturn(tuple([True] + list(vals)))
    except LuaError as e:
        errv = e.value if e.value is not None else e.message
        if handler is not None:
            try: errv = st.call(handler, [errv])
            except Exception: pass
        return MultiReturn((False, errv))

def _fn_print(st, a):
    s = "\t".join(lua_tostring(st, x) for x in a) + "\n"
    try:
        os.write(1, s.encode("utf-8", "surrogateescape"))
    except Exception:
        try: sys.stdout.write(s); sys.stdout.flush()
        except Exception: pass
    return None

def _fn_rawset(st, a):
    t = _arg(a, 0)
    if isinstance(t, LuaTable): t.rawset(_arg(a, 1), _arg(a, 2)); return t
    return None

def _fn_setmt(st, a):
    t = _arg(a, 0); mt = _arg(a, 1)
    if isinstance(t, (LuaTable, LuaUserdata)): t.metatable = mt if isinstance(mt, LuaTable) else None
    return t

def _fn_getmt(st, a):
    t = _arg(a, 0)
    mt = get_metatable(t)
    if isinstance(mt, LuaTable):
        if mt.rawget("__metatable") is not None: return mt.rawget("__metatable")
    return mt

def _fn_unpack(st, a):
    t = _arg(a, 0)
    if not isinstance(t, LuaTable): return MultiReturn(())
    i = int(lua_tonumber(_arg(a, 1, 1)) or 1); j = int(lua_tonumber(_arg(a, 2)) ) if _arg(a, 2) is not None else t.array_len()
    return MultiReturn(tuple(t.rawget(k) for k in range(i, j + 1)))

def _fn_require(st, a):
    name = _arg(a, 0)
    if not isinstance(name, str): return None
    loaded = st.package_loaded
    if loaded is not None:
        v = loaded.rawget(name)
        if v is not None and v is not False: return v
    pkg = st.globals.rawget("package")
    path_str = pkg.rawget("path") if isinstance(pkg, LuaTable) else ""
    searched = []
    for pat in (path_str or "").split(";"):
        if not pat: continue
        candidate = pat.replace("?", name.replace(".", "/"))
        searched.append(candidate)
        if os.path.isfile(candidate):
            code = open(candidate, "r", encoding="utf-8", errors="surrogateescape").read()
            chunk = f'[string "{os.path.abspath(candidate)}"]'
            vals = load_lua_chunk(st, code, chunk)
            result = vals[0] if vals else True
            if result is None: result = True
            if loaded is not None: loaded.rawset(name, result)
            return result
    fr = st.frames[-1] if st.frames else None
    pref = f"{fr.chunk}:{fr.current_line}: " if fr else ""
    st.runtime_error(pref + f"module '{name}' not found:\n" + "\n".join(f"\tno file '{p}'" for p in searched))

def _fn_loadstring(st, a):
    code = _arg(a, 0); chunkname = _arg(a, 1)
    if not isinstance(code, str): return None
    if isinstance(chunkname, str):
        display = chunkname
        if display.startswith("="): display = display[1:]
        elif display.startswith("@"): display = display[1:]
        else: display = f'[string "{display}"]'
    else:
        first = code.strip().split("\n")[0][:40]
        display = f'[string "{first}"]'
    try:
        parser = Parser(code, display)
        body = parser.parse_chunk()
    except LuaSyntaxError as e:
        return MultiReturn((None, e.text))
    def runner(st2, inner, _body=body, _display=display):
        scope = Scope(None); scope.vars["..."] = Cell(MultiReturn(inner))
        frame = Frame(_display, 1, True)
        st2.frames.append(frame)
        try:
            exec_block(st2, _body, scope, frame); return MultiReturn(())
        except LuaReturn as ret: return MultiReturn(ret.values)
        finally: st2.frames.pop()
    return NativeFunction(runner, "loadstring")

def _fn_loadfile(st, a):
    fname = _arg(a, 0)
    if not isinstance(fname, str) or not os.path.isfile(fname):
        return MultiReturn((None, f"cannot open {fname}: No such file or directory"))
    code = open(fname, encoding="utf-8", errors="surrogateescape").read()
    display = f'[string "{os.path.abspath(fname)}"]'
    try:
        parser = Parser(code, display); body = parser.parse_chunk()
    except LuaSyntaxError as e:
        return MultiReturn((None, e.text))
    def runner(st2, inner, _body=body, _display=display):
        scope = Scope(None); scope.vars["..."] = Cell(MultiReturn(inner))
        frame = Frame(_display, 1, True); st2.frames.append(frame)
        try:
            exec_block(st2, _body, scope, frame); return MultiReturn(())
        except LuaReturn as ret: return MultiReturn(ret.values)
        finally: st2.frames.pop()
    return NativeFunction(runner, "loadfile")

def _fn_dofile(st, a):
    fname = _arg(a, 0)
    code = open(fname, encoding="utf-8", errors="surrogateescape").read()
    display = f'[string "{os.path.abspath(fname)}"]'
    vals = load_lua_chunk(st, code, display)
    return MultiReturn(vals)

def _install_table(state):
    lib = LuaTable()
    def nf(name, fn): lib.rawset(name, NativeFunction(fn, "table." + name))
    def _insert(st, a):
        t = _arg(a, 0)
        if not isinstance(t, LuaTable): return None
        n = t.array_len()
        if len(a) == 2: pos, val = n + 1, a[1]
        else: pos, val = int(lua_tonumber(a[1]) or (n + 1)), a[2]
        for i in range(n, pos - 1, -1): t.rawset(i + 1, t.rawget(i))
        t.rawset(pos, val); return None
