    g.rawset("package", pkg)
    # coroutine (minimal)
    co = LuaTable(); co.rawset("status", NativeFunction(lambda st, a: "dead", "coroutine.status"))
    g.rawset("coroutine", co)
    dbg = LuaTable(); dbg.rawset("traceback", NativeFunction(lambda st, a: (lua_tostring(st, _arg(a, 0)) if _arg(a, 0) is not None else "") + "\n" + st.make_trace(), "debug.traceback"))
    g.rawset("debug", dbg)

def _fn_select(st, a):
    if not a: return 0
    idx = a[0]
    if idx == "#": return len(a) - 1
    n = int(lua_tonumber(idx) or 0)
    if n > 0: return MultiReturn(a[n:]) if n < len(a) else MultiReturn(())
    return MultiReturn(a[len(a) + n:]) if len(a) + n >= 1 else MultiReturn(())

def _next_impl(table, key):
    if not isinstance(table, LuaTable): return MultiReturn(())
    items = table.items()
    if key is None:
        if not items: return MultiReturn(())
        return MultiReturn((items[0][0], items[0][1]))
    for i, (k, v) in enumerate(items):
        if lua_equals(None, k, key):
            if i + 1 >= len(items): return MultiReturn(())
            return MultiReturn((items[i+1][0], items[i+1][1]))
    return MultiReturn(())

def _fn_next(st, a):
    return _next_impl(_arg(a, 0), _arg(a, 1))

def _fn_pairs(st, a):
    t = _arg(a, 0)
    return MultiReturn((NativeFunction(lambda st2, inner: _next_impl(inner[0], inner[1] if len(inner) > 1 else None), "next"), t, None))

def _fn_ipairs(st, a):
    t = _arg(a, 0)
    def iterf(st2, inner):
        tbl, i = inner[0], int(lua_tonumber(inner[1]) or 0)
        if not isinstance(tbl, LuaTable): return None
        v = tbl.rawget(i + 1)
        if v is None: return None
        return MultiReturn((i + 1, v))
    return MultiReturn((NativeFunction(iterf, "ipairs iterator"), t, 0))

def _fn_tonumber(st, a):
    v = _arg(a, 0); base = _arg(a, 1)
    if base is None: return lua_tonumber(v)
    if isinstance(v, str):
        try: return int(v.strip(), int(lua_tonumber(base) or 10))
        except Exception: return None
    return None

def _fn_error(st, a):
    val = _arg(a, 0)
    level = int(lua_tonumber(_arg(a, 1, 1)) or 1)
    if isinstance(val, str) and level > 0:
        frames = st.frames
        idx = len(frames) - level
        if 0 <= idx < len(frames):
            fr = frames[idx]
            val = f"{fr.chunk}:{fr.current_line}: " + val
    st.runtime_error(val if isinstance(val, str) else lua_tostring(st, val), via_error=True)

def _fn_assert(st, a):
    if not a or not lua_truthy(a[0]):
        msg = _arg(a, 1)
        if msg is None: msg = "assertion failed!"
        # level 2-ish: caller's location
        if isinstance(msg, str) and st.frames:
            fr = st.frames[-1]; msg = f"{fr.chunk}:{fr.current_line}: " + msg
        st.runtime_error(msg if isinstance(msg, str) else lua_tostring(st, msg), via_error=True)
    return MultiReturn(tuple(a))

def _fn_pcall(st, a):
    fn = _arg(a, 0); rest = list(a[1:])
    if fn is None:
        return MultiReturn((False, "attempt to call a nil value"))
    try:
        vals = st.call_multi(fn, rest)
        return MultiReturn(tuple([True] + list(vals)))
    except LuaError as e:
        return MultiReturn((False, e.value if isinstance(e.value, str) else lua_tostring(st, e.value) if e.value is not None else e.message))
    except SystemExit:
        raise
    except Exception as e:
        return MultiReturn((False, str(e)))

def _fn_xpcall(st, a):
    fn = _arg(a, 0); handler = _arg(a, 1); rest = list(a[2:])
    try:
        vals = st.call_multi(fn, rest)
        return MultiReturn(tuple([True] + list(vals)))
    except LuaError as e:
        errv = e.value if e.value is not None else e.message
        if handler is not None:
            try: errv = st.call(handler, [errv])
            except Exception: pass
        return MultiReturn((False, errv))

def _fn_print(st, a):
    s = "\t".join(lua_tostring(st, x) for x in a) + "\n"
    try:
        os.write(1, s.encode("utf-8", "surrogateescape"))
    except Exception:
        try: sys.stdout.write(s); sys.stdout.flush()
        except Exception: pass
    return None

def _fn_rawset(st, a):
    t = _arg(a, 0)
    if isinstance(t, LuaTable): t.rawset(_arg(a, 1), _arg(a, 2)); return t
    return None

def _fn_setmt(st, a):
    t = _arg(a, 0); mt = _arg(a, 1)
    if isinstance(t, (LuaTable, LuaUserdata)): t.metatable = mt if isinstance(mt, LuaTable) else None
    return t

def _fn_getmt(st, a):
    t = _arg(a, 0)
    mt = get_metatable(t)
    if isinstance(mt, LuaTable):
        if mt.rawget("__metatable") is not None: return mt.rawget("__metatable")
    return mt

def _fn_unpack(st, a):
    t = _arg(a, 0)
    if not isinstance(t, LuaTable): return MultiReturn(())
    i = int(lua_tonumber(_arg(a, 1, 1)) or 1); j = int(lua_tonumber(_arg(a, 2)) ) if _arg(a, 2) is not None else t.array_len()
    return MultiReturn(tuple(t.rawget(k) for k in range(i, j + 1)))

def _fn_require(st, a):
    name = _arg(a, 0)
    if not isinstance(name, str): return None
    loaded = st.package_loaded
    if loaded is not None:
        v = loaded.rawget(name)
        if v is not None and v is not False: return v
    pkg = st.globals.rawget("package")
    path_str = pkg.rawget("path") if isinstance(pkg, LuaTable) else ""
    searched = []
    for pat in (path_str or "").split(";"):
        if not pat: continue
        candidate = pat.replace("?", name.replace(".", "/"))
        searched.append(candidate)
        if os.path.isfile(candidate):
            code = open(candidate, "r", encoding="utf-8", errors="surrogateescape").read()
            chunk = f'[string "{os.path.abspath(candidate)}"]'
            vals = load_lua_chunk(st, code, chunk)
            result = vals[0] if vals else True
            if result is None: result = True
            if loaded is not None: loaded.rawset(name, result)
            return result
    fr = st.frames[-1] if st.frames else None
    pref = f"{fr.chunk}:{fr.current_line}: " if fr else ""
    st.runtime_error(pref + f"module '{name}' not found:\n" + "\n".join(f"\tno file '{p}'" for p in searched))

def _fn_loadstring(st, a):
    code = _arg(a, 0); chunkname = _arg(a, 1)
    if not isinstance(code, str): return None
    if isinstance(chunkname, str):
        display = chunkname
        if display.startswith("="): display = display[1:]
        elif display.startswith("@"): display = display[1:]
        else: display = f'[string "{display}"]'
    else:
        first = code.strip().split("\n")[0][:40]
        display = f'[string "{first}"]'
    try:
        parser = Parser(code, display)
        body = parser.parse_chunk()
    except LuaSyntaxError as e:
        return MultiReturn((None, e.text))
    def runner(st2, inner, _body=body, _display=display):
        scope = Scope(None); scope.vars["..."] = Cell(MultiReturn(inner))
        frame = Frame(_display, 1, True)
        st2.frames.append(frame)
        try:
            exec_block(st2, _body, scope, frame); return MultiReturn(())
        except LuaReturn as ret: return MultiReturn(ret.values)
        finally: st2.frames.pop()
    return NativeFunction(runner, "loadstring")

def _fn_loadfile(st, a):
    fname = _arg(a, 0)
    if not isinstance(fname, str) or not os.path.isfile(fname):
        return MultiReturn((None, f"cannot open {fname}: No such file or directory"))
    code = open(fname, encoding="utf-8", errors="surrogateescape").read()
    display = f'[string "{os.path.abspath(fname)}"]'
    try:
        parser = Parser(code, display); body = parser.parse_chunk()
    except LuaSyntaxError as e:
        return MultiReturn((None, e.text))
    def runner(st2, inner, _body=body, _display=display):
        scope = Scope(None); scope.vars["..."] = Cell(MultiReturn(inner))
        frame = Frame(_display, 1, True); st2.frames.append(frame)
        try:
            exec_block(st2, _body, scope, frame); return MultiReturn(())
        except LuaReturn as ret: return MultiReturn(ret.values)
        finally: st2.frames.pop()
    return NativeFunction(runner, "loadfile")

def _fn_dofile(st, a):
    fname = _arg(a, 0)
    code = open(fname, encoding="utf-8", errors="surrogateescape").read()
    display = f'[string "{os.path.abspath(fname)}"]'
    vals = load_lua_chunk(st, code, display)
    return MultiReturn(vals)

def _install_table(state):
    lib = LuaTable()
    def nf(name, fn): lib.rawset(name, NativeFunction(fn, "table." + name))
    def _insert(st, a):
        t = _arg(a, 0)
        if not isinstance(t, LuaTable): return None
        n = t.array_len()
        if len(a) == 2: pos, val = n + 1, a[1]
        else: pos, val = int(lua_tonumber(a[1]) or (n + 1)), a[2]
        for i in range(n, pos - 1, -1): t.rawset(i + 1, t.rawget(i))
        t.rawset(pos, val); return None
    nf("insert", _insert)
    def _remove(st, a):
        t = _arg(a, 0)
        if not isinstance(t, LuaTable): return None
        n = t.array_len(); pos = int(lua_tonumber(_arg(a, 1, n)) or n)
        v = t.rawget(pos)
        for i in range(pos, n): t.rawset(i, t.rawget(i + 1))
        t.rawset(n, None)
        return v
    nf("remove", _remove)
    def _concat(st, a):
        t = _arg(a, 0); sep = _str_arg(st, _arg(a, 1, "")) or ""
        if not isinstance(t, LuaTable): return ""
        i = int(lua_tonumber(_arg(a, 2, 1)) or 1); j = int(lua_tonumber(_arg(a, 3)) ) if _arg(a, 3) is not None else t.array_len()
        return sep.join(lua_tostring(st, t.rawget(k)) for k in range(i, j + 1))
    nf("concat", _concat)
    def _sort(st, a):
        t = _arg(a, 0); comp = _arg(a, 1)
        if not isinstance(t, LuaTable): return None
        n = t.array_len(); vals = [t.rawget(i) for i in range(1, n + 1)]
        if comp is not None:
            def cmp(x, y):
                r = st.call(comp, [x, y])
                return -1 if lua_truthy(r) else (1 if lua_truthy(st.call(comp, [y, x])) else 0)
            vals.sort(key=_functools.cmp_to_key(cmp))
        else:
            def key(v): return (0, v) if isinstance(v, (int, float)) else (1, str(v))
            vals.sort(key=key)
        for i, v in enumerate(vals): t.rawset(i + 1, v)
        return None
    nf("sort", _sort)
    nf("getn", lambda st, a: _arg(a, 0).array_len() if isinstance(_arg(a, 0), LuaTable) else 0)
    nf("maxn", lambda st, a: max([k for k in (_arg(a, 0).keys() if isinstance(_arg(a, 0), LuaTable) else []) if isinstance(k, (int, float))], default=0))
    nf("unpack", _fn_unpack)
    nf("pack", lambda st, a: _pack(a))
    def _foreach(st, a):
        t = _arg(a, 0); fn = _arg(a, 1)
        if isinstance(t, LuaTable):
            for k, v in t.items():
                r = st.call(fn, [k, v])
                if r is not None: return r
        return None
    nf("foreach", _foreach)
    nf("foreachi", lambda st, a: None)
    return lib

def _pack(args):
    t = LuaTable()
    for i, v in enumerate(args): t.rawset(i + 1, v)
    t.rawset("n", len(args))
    return t

def _install_math():
    lib = LuaTable()
    def nf(name, fn): lib.rawset(name, NativeFunction(fn, "math." + name))
    for name in ("abs", "floor", "ceil", "sqrt", "exp", "log", "sin", "cos", "tan", "asin", "acos", "atan", "sinh", "cosh", "tanh"):
        nf(name, (lambda n: lambda st, a: getattr(math, n)(lua_tonumber(_arg(a, 0)) or 0))(name))
    nf("atan2", lambda st, a: math.atan2(lua_tonumber(_arg(a, 0)) or 0, lua_tonumber(_arg(a, 1)) or 0))
    nf("log10", lambda st, a: math.log10(lua_tonumber(_arg(a, 0)) or 1))
    nf("deg", lambda st, a: math.degrees(lua_tonumber(_arg(a, 0)) or 0))
    nf("rad", lambda st, a: math.radians(lua_tonumber(_arg(a, 0)) or 0))
    nf("max", lambda st, a: max([lua_tonumber(x) for x in a if lua_tonumber(x) is not None], default=0))
    nf("min", lambda st, a: min([lua_tonumber(x) for x in a if lua_tonumber(x) is not None], default=0))
    nf("modf", lambda st, a: MultiReturn((math.trunc(lua_tonumber(_arg(a, 0)) or 0), math.modf(lua_tonumber(_arg(a, 0)) or 0)[0])))
    nf("fmod", lambda st, a: math.fmod(lua_tonumber(_arg(a, 0)) or 0, lua_tonumber(_arg(a, 1)) or 1))
    nf("pow", lambda st, a: (lua_tonumber(_arg(a, 0)) or 0) ** (lua_tonumber(_arg(a, 1)) or 0))
    nf("ldexp", lambda st, a: math.ldexp(lua_tonumber(_arg(a, 0)) or 0, int(lua_tonumber(_arg(a, 1)) or 0)))
    nf("frexp", lambda st, a: MultiReturn(math.frexp(lua_tonumber(_arg(a, 0)) or 0)))
    lib.rawset("pi", math.pi); lib.rawset("huge", float("inf"))
    _rng = _random.Random()
    def _rand(st, a):
        if len(a) == 0: return _rng.random()
        if len(a) == 1:
            hi = int(lua_tonumber(a[0]) or 1); return _rng.randint(1, max(1, hi))
        lo = int(lua_tonumber(a[0]) or 1); hi = int(lua_tonumber(a[1]) or lo); return _rng.randint(lo, hi)
    nf("random", _rand)
    nf("randomseed", lambda st, a: _rng.seed(int(lua_tonumber(_arg(a, 0)) or 0)))
    return lib

def _make_file_userdata(state, pyfile, name="<file>", mode="r", popen_proc=None):
    ud = LuaUserdata(pyfile, "FILE*")
    def m_read(st, o, a):
        fmt = _arg(a, 0, "*l") if a else "*l"
        f = o.obj
        if fmt in ("*a", "*all"):
            try: return f.read()
            except Exception: return ""
        if fmt in ("*n",):
            data = f.read()
            return lua_tonumber(data.strip()) if data else None
        if isinstance(fmt, (int, float)):
            return f.read(int(fmt))
        # *l / *line
        try:
            line = f.readline()
        except Exception:
            return None
        if line == "": return None
        if line.endswith("\n"): line = line[:-1]
        if line.endswith("\r"): line = line[:-1]
        return line
    def m_write(st, o, a):
        for x in a: o.obj.write(lua_tostring(st, x))
        o.obj.flush(); return o
    def m_close(st, o, a):
        try: o.obj.close()
        except Exception: pass
        if popen_proc is not None:
            try: popen_proc.wait(); return popen_proc.returncode
            except Exception: return 0
        return True
    ud.methods = {"read": m_read, "write": m_write, "close": m_close,
                  "flush": lambda st, o, a: (o.obj.flush(), o)[1],
                  "lines": lambda st, o, a: NativeFunction(lambda st2, inner: m_read(st2, o, ["*l"]), "lines")}
    return ud

def _install_os(state):
    lib = LuaTable()
    def nf(name, fn): lib.rawset(name, NativeFunction(fn, "os." + name))
    nf("getenv", lambda st, a: os.environ.get(_arg(a, 0)) if isinstance(_arg(a, 0), str) else None)
    nf("execute", lambda st, a: os.system(_arg(a, 0) if isinstance(_arg(a, 0), str) else "") if _arg(a, 0) is not None else True)
    def _exit(st, a):
        code = _arg(a, 0, 0)
        if code is True: raise SystemExit(0)
        if code is False: raise SystemExit(1)
        raise SystemExit(int(lua_tonumber(code) or 0))
    nf("exit", _exit)
    nf("time", _os_time)
    nf("date", _os_date)
    nf("clock", lambda st, a: _time.process_time())
    nf("remove", lambda st, a: _os_remove(_arg(a, 0)))
    nf("rename", lambda st, a: _os_rename(_arg(a, 0), _arg(a, 1)))
    nf("tmpname", lambda st, a: _os_tmpname())
    nf("setlocale", lambda st, a: "C")
    nf("difftime", lambda st, a: (lua_tonumber(_arg(a, 0)) or 0) - (lua_tonumber(_arg(a, 1)) or 0))
    return lib

def _os_remove(path):
    try: os.remove(path); return True
    except OSError as e: return MultiReturn((None, e.strerror, e.errno))

def _os_rename(a, b):
    try: os.rename(a, b); return True
    except OSError as e: return MultiReturn((None, e.strerror, e.errno))
    except Exception as e: return MultiReturn((None, str(e)))

def _os_tmpname():
    import tempfile
    fd, p = tempfile.mkstemp(prefix="lua_"); os.close(fd); os.remove(p)
    return p

def _os_time(st, a):
    t = _arg(a, 0)
    if t is None: return int(_time.time())
    if isinstance(t, LuaTable):
