        return {self.name: None}

def _loc_err(strict, path, msg, node):
    if strict:
        return MessageError(f"{msg} at line {node.line} column {_end_col(node)}")
    if path:
        return MessageError(f"{path}: {msg} at line {node.line} column {node.col}")
    return MessageError(msg)

def _validate_payload(name, node, strict, path):
    kind = PAYLOAD.get(name)
    if kind == "string":
        return _as_string(node, strict, path)
    if kind == "usize":
        return _as_usize(node, strict, path)
    if kind == "command":
        return _as_command(node, strict, path)
    if kind == "filter_applicable":
        return _as_filter_applicable(node, strict, path)
    if kind == "filter_enum":
        return _as_enum(node, FILTERS, strict, path, "NodeFilter")
    if kind == "sorter_applicable":
        return _as_sorter_applicable(node, strict, path)
    if kind == "sorter_enum":
        return _as_enum(node, SORTERS, strict, path, "NodeSorter")
    if kind == "input_operation":
        return _as_input_operation(node, strict, path)
