def _as_string(node, strict, path):
    if node.kind == "str":
        return node.value
    if not strict:
        if node.kind == "null": return ""
        if node.kind in ("int",): return str(node.value)
        if node.kind == "float": return _float_str(node.value)
        if node.kind == "bool": return str(node.value).lower()
    raise _loc_err(strict, path, f"invalid type: {type_desc(node)}, expected a string", node)

def _as_usize(node, strict, path):
    if node.kind == "int":
        v = node.value
        if v < 0:
            if strict: raise MessageError(f"invalid value: integer `{v}`, expected usize at line {node.line} column {_end_col(node)}")
            raise _loc_err(False, path, f"invalid type: integer `{v}`, expected usize", node)
        if v > 18446744073709551615:
            raise _loc_err(strict, path, f"invalid type: integer `{v}` as u128, expected usize", node)
