    raise _loc_err(strict, path, f"invalid type: {type_desc(node)}, expected usize", node)

def _map_pairs(node, strict, path, type_name="map"):
    if node.kind != "map":
        raise _loc_err(strict, path, f"invalid type: {type_desc(node)}, expected {type_name}", node)
