def parse_message_strict(text):
    try:
        node = parse_yaml(text)
    except YamlSyntaxError as e:
        raise
    return validate_strict(node)

def parse_message_lenient(text):
    node = parse_yaml(text)
    return validate_lenient(node)

def msg_to_json(msg):
    return json.dumps(msg.to_json_value(), ensure_ascii=False, separators=(",", ":"))

# ---------------- jf-style template formatting ----------------
class JfError(Exception): pass

def jf_format(template, args):
    args = list(args)
    used_all = False
    out = []
    i = 0
    n = len(template)
    argi = 0
    chars = template
    while i < n:
        c = chars[i]
        if c != "%":
            out.append(c); i += 1; continue
        # placeholder
        if i + 1 >= n:
            raise JfError("template ended with incomplete placeholder")
        nxt = chars[i+1]
        if nxt == "%":
            out.append("%"); i += 2; continue
        # the '-' quirk observed in the original: %- ... -spec behaves as if
        # it tries to read a (missing) value for that placeholder
        if nxt == "-":
            j = i + 1
            while j < n and chars[j] == "-": j += 1
            if j >= n:
                raise JfError("template ended with incomplete placeholder")
            spec = chars[j]
            if spec in "sq":
                raise JfError(f"placeholder missing value at column {j}")
            raise JfError(f"invalid placeholder '%{spec}' at column {j}, use one of '%s' or '%q', or escape it using '%%'")
        if nxt == "*":
            if i + 2 >= n:
                raise JfError("template ended with incomplete placeholder")
            spec = chars[i+2]
            if spec not in "sq":
                raise JfError(f"invalid placeholder '%*{spec}' at column {i+2}, use one of '%*s' or '%*q', or escape it using '%%'")
            rest = args[argi:]; argi = len(args)
            if spec == "s":
                out.append(",".join(rest))
            else:
                out.append(",".join(json.dumps(x, ensure_ascii=False) for x in rest))
            i += 3; continue
        spec = nxt
        if spec in "sq":
            if argi >= len(args):
                raise JfError(f"placeholder missing value at column {i+1}")
            val = args[argi]; argi += 1
            if spec == "s": out.append(val)
            else: out.append(json.dumps(val, ensure_ascii=False))
            i += 2; continue
        raise JfError(f"invalid placeholder '%{spec}' at column {i+1}, use one of '%s' or '%q', or escape it using '%%'")
    if argi < len(args):
        raise JfError("too many positional values, not enough positional placeholders")
    return "".join(out)

def format_message(template, args):
    """Returns the JSON representation of the rendered+parsed message.
    Raises JfError / YamlSyntaxError / MessageError."""
    rendered = jf_format(template, args)
    try:
        node = parse_yaml(rendered)
    except YamlSyntaxError as e:
        # jf stage errors carry the "yaml:" prefix
        raise JfError("yaml: " + e.display()) from None
    return validate_strict(node)

