class JfError(Exception): pass

def jf_format(template, args):
    args = list(args)
    used_all = False
    out = []
    i = 0
    n = len(template)
    argi = 0
    chars = template
    while i < n:
        c = chars[i]
        if c != "%":
            out.append(c); i += 1; continue
