            if spec == "s":
                out.append(",".join(rest))
            else:
                out.append(",".join(json.dumps(x, ensure_ascii=False) for x in rest))
            i += 3; continue
        spec = nxt
        if spec in "sq":
            if argi >= len(args):
                raise JfError(f"placeholder missing value at column {i+1}")
            val = args[argi]; argi += 1
            if spec == "s": out.append(val)
            else: out.append(json.dumps(val, ensure_ascii=False))
            i += 2; continue
        raise JfError(f"invalid placeholder '%{spec}' at column {i+1}, use one of '%s' or '%q', or escape it using '%%'")
    if argi < len(args):
        raise JfError("too many positional values, not enough positional placeholders")
    return "".join(out)

def format_message(template, args):
    """Returns the JSON representation of the rendered+parsed message.
    Raises JfError / YamlSyntaxError / MessageError."""
    rendered = jf_format(template, args)
    try:
        node = parse_yaml(rendered)
    except YamlSyntaxError as e:
        # jf stage errors carry the "yaml:" prefix
        raise JfError("yaml: " + e.display()) from None
    return validate_strict(node)

