def conv_config(xplr_config_lua):
    expect_table(xplr_config_lua)
    for k, val in xplr_config_lua.items():
        if k not in ("general", "node_types", "layouts", "modes"):
            err(f"unknown field `{k}`, expected {_expected(['general','node_types','layouts','modes'])}")
    def sec(name):
        return xplr_config_lua.rawget(name)
    general = conv_general(sec("general")) if sec("general") is not None else conv_general(LuaTable())
    # node_types
    nt = sec("node_types")
    if nt is None:
        node_types = {"directory": conv_node_type(None), "file": conv_node_type(None), "symlink": conv_node_type(None), "mime_essence": {}, "extension": {}, "special": {}}
    else:
        expect_table(nt)
        for k, val in nt.items():
            if k not in ("directory", "file", "symlink", "mime_essence", "extension", "special"):
                err(f"unknown field `{k}`, expected {_expected(['directory','file','symlink','mime_essence','extension','special'])}")
        def mime_map(x):
            if x is None: return {}
            expect_table(x); out = {}
            for major, sub in x.items():
                expect_table(sub); out[str(major)] = {str(k): conv_node_type(v) for k, v in sub.items()}
            return out
        def plain_map(x):
            if x is None: return {}
            expect_table(x); return {str(k): conv_node_type(v) for k, v in x.items()}
        node_types = {
            "directory": conv_node_type(nt.rawget("directory")), "file": conv_node_type(nt.rawget("file")), "symlink": conv_node_type(nt.rawget("symlink")),
            "mime_essence": mime_map(nt.rawget("mime_essence")), "extension": plain_map(nt.rawget("extension")), "special": plain_map(nt.rawget("special")),
        }
    lay = sec("layouts")
    if lay is None:
        layouts = {"builtin": {}, "custom": {}}
    else:
        expect_table(lay)
        for k, val in lay.items():
            if k not in ("builtin", "custom"): err(f"unknown field `{k}`, expected `builtin` or `custom`")
        b = lay.rawget("builtin"); c = lay.rawget("custom")
        builtin = {}
        if isinstance(b, LuaTable):
            for key in BUILTIN_LAYOUT_KEYS:
                if b.has(key) and b.rawget(key) is not None: builtin[key] = conv_layout(b.rawget(key))
        custom = {}
        if isinstance(c, LuaTable):
            for k, val in c.items(): custom[str(k)] = conv_layout(val)
        layouts = {"builtin": builtin, "custom": custom}
    modes_sec = sec("modes")
    if modes_sec is None:
        modes = {"builtin": {}, "custom": {}}
    else:
        expect_table(modes_sec)
        for k, val in modes_sec.items():
            if k not in ("builtin", "custom"): err(f"unknown field `{k}`, expected `builtin` or `custom`")
        b = modes_sec.rawget("builtin"); c = modes_sec.rawget("custom")
        builtin = {}
        if isinstance(b, LuaTable):
            for key in BUILTIN_MODE_KEYS:
                if b.has(key) and b.rawget(key) is not None: builtin[key] = conv_mode(b.rawget(key))
        custom = {}
        if isinstance(c, LuaTable):
            for k, val in c.items(): custom[str(k)] = conv_mode(val)
        modes = {"builtin": builtin, "custom": custom}
    return {"general": general, "node_types": node_types, "layouts": layouts, "modes": modes}

HOOK_FIELDS = ["on_load", "on_directory_change", "on_focus_change", "on_mode_switch", "on_layout_switch", "on_selection_change"]
def empty_hooks():
    return {k: [] for k in HOOK_FIELDS}

def conv_hooks(ret):
    if ret is None: return empty_hooks()
    if not isinstance(ret, LuaTable):
        err(f"invalid type: {type_desc(ret)}, expected table")
    for k, val in ret.items():
        if k not in HOOK_FIELDS:
            err(f"unknown field `{k}`, expected {_expected(HOOK_FIELDS)}")
    out = empty_hooks()
    for k in HOOK_FIELDS:
        if ret.has(k):
            out[k] = messages_from_lua_list(ret.rawget(k))
    return out
