"""Conversion of the Lua xplr.config table into typed Python structures."""
import copy
from luamod import LuaTable, LuaFunction, NativeFunction
from messages import Msg, VARIANTS, UNIT, PAYLOAD
from nodes import FILTERS, SORTERS

class ConfigError(Exception):
    pass

def _expected(fields):
    if len(fields) == 1:
        return f"`{fields[0]}`"
    if len(fields) == 2:
        return f"`{fields[0]}` or `{fields[1]}`"
    return "one of " + ", ".join(f"`{f}`" for f in fields)

def type_desc(v):
    if v is None: return "unit value"
    if isinstance(v, bool): return f"boolean `{str(v).lower()}`"
    if isinstance(v, int): return f"integer `{v}`"
    if isinstance(v, float):
        if v == int(v): return f"integer `{int(v)}`"
        return f"floating point `{v}`"
    if isinstance(v, str): return f'string "{v}"'
    if isinstance(v, LuaTable): return "map"
    if isinstance(v, (LuaFunction, NativeFunction)): return "function"
    return type(v).__name__

def err(msg):
    raise ConfigError("deserialize error: " + msg)

def expect_table(v):
    if not isinstance(v, LuaTable):
        err(f"invalid type: {type_desc(v)}, expected table")
    return v

def expect_string(v):
    if not isinstance(v, str):
        err(f"invalid type: {type_desc(v)}, expected a string")
    return v

def opt_string(v):
    if v is None: return None
    return expect_string(v)

def expect_bool(v):
    if not isinstance(v, bool):
        err(f"invalid type: {type_desc(v)}, expected a boolean")
    return v

def expect_int(v, what="u64"):
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        err(f"invalid type: {type_desc(v)}, expected {what}")
    if isinstance(v, float) and not v.is_integer():
        err(f"invalid type: {type_desc(v)}, expected {what}")
    return int(v)

def expect_list(v):
    expect_table(v)
    # ensure keys are 1..n-ish ints or empty
    for k, val in v.items():
        if not isinstance(k, int):
            err(f"invalid type: {type_desc(k)}, expected a sequence")
    out = []
    i = 1
    while v.has(i):
        out.append(v.rawget(i)); i += 1
    return out

def expect_map(v):
    expect_table(v)
    return v.items()

def conv_struct(v, fields):
    """fields: list of (name, converter, default_factory)"""
    expect_table(v)
    names = [f[0] for f in fields]
    for k, val in v.items():
        if not isinstance(k, str) or k not in names:
            err(f"unknown field `{k}`, expected {_expected(names)}")
    out = {}
    for name, conv, default in fields:
        if v.has(name):
            out[name] = conv(v.rawget(name))
        else:
            out[name] = default() if callable(default) else copy.deepcopy(default)
    return out

def empty_style():
    return {"fg": None, "bg": None, "add_modifiers": None, "sub_modifiers": None}

from coreutil import COLOR_NAMES, MODIFIERS

def conv_color(v):
    if isinstance(v, str):
        if v in COLOR_NAMES: return v
        err(f"unknown variant `{v}`, expected one of " + ", ".join(f"`{x}`" for x in COLOR_NAMES + ["Rgb", "Indexed"]))
    if isinstance(v, LuaTable):
        pairs = v.items()
        if len(pairs) != 1:
            err("invalid value: map, expected map with a single key")
        k, val = pairs[0]
        if k == "Rgb":
            lst = expect_list(val) if isinstance(val, LuaTable) else err(f"invalid type: {type_desc(val)}, expected a tuple")
            nums = [min(255, max(0, expect_int(x, "u8"))) for x in lst]
            while len(nums) < 3: nums.append(0)
            return {"Rgb": nums[:3]}
        if k == "Indexed":
            return {"Indexed": expect_int(val, "u8")}
        err(f"unknown variant `{k}`, expected one of " + ", ".join(f"`{x}`" for x in COLOR_NAMES + ["Rgb", "Indexed"]))
    err(f"invalid type: {type_desc(v)}, expected enum Color")

def conv_modifier_list(v):
    if v is None: return None
    out = []
    for x in expect_list(v):
        if not isinstance(x, str) or x not in MODIFIERS:
            err(f"unknown variant `{x}`, expected one of " + ", ".join(f"`{m}`" for m in MODIFIERS))
        out.append(x)
    return out

def conv_style(v):
    if v is None: return empty_style()
    return conv_struct(v, [
        ("fg", lambda x: None if x is None else conv_color(x), None),
        ("bg", lambda x: None if x is None else conv_color(x), None),
        ("add_modifiers", conv_modifier_list, None),
        ("sub_modifiers", conv_modifier_list, None),
    ])

def conv_ui_config(v):
    # { format, style }
    if v is None: return {"format": None, "style": empty_style()}
    return conv_struct(v, [
        ("format", opt_string, None),
        ("style", conv_style, empty_style),
    ])

def conv_title_config(v):
    return conv_ui_config(v)

BORDERS = ["Top", "Right", "Bottom", "Left"]
BORDER_TYPES = ["Plain", "Rounded", "Double", "Thick"]

def conv_panel_ui(v):
    if v is None:
        return {"title": conv_title_config(None), "style": empty_style(), "borders": None, "border_type": None, "border_style": empty_style()}
    def conv_borders(x):
        if x is None: return None
        out = []
        for b in expect_list(x):
            if b not in BORDERS: err(f"unknown variant `{b}`, expected one of " + ", ".join(f"`{z}`" for z in BORDERS))
            out.append(b)
        return out
    def conv_btype(x):
        if x is None: return None
        if x not in BORDER_TYPES: err(f"unknown variant `{x}`, expected one of " + ", ".join(f"`{z}`" for z in BORDER_TYPES))
        return x
    return conv_struct(v, [
        ("title", conv_title_config, lambda: conv_title_config(None)),
        ("style", conv_style, empty_style),
        ("borders", conv_borders, None),
        ("border_type", conv_btype, None),
        ("border_style", conv_style, empty_style),
    ])

def conv_constraint(v):
    if isinstance(v, LuaTable):
        pairs = v.items()
        if len(pairs) == 1:
            k, val = pairs[0]
            variants = ["Percentage","Ratio","Length","LengthLessThanScreenHeight","LengthLessThanScreenWidth","LengthLessThanLayoutHeight","LengthLessThanLayoutWidth","Max","MaxLessThanScreenHeight","MaxLessThanScreenWidth","MaxLessThanLayoutHeight","MaxLessThanLayoutWidth","Min","MinLessThanScreenHeight","MinLessThanScreenWidth","MinLessThanLayoutHeight","MinLessThanLayoutWidth"]
            if k not in variants:
                err(f"unknown variant `{k}`, expected one of " + ", ".join(f"`{x}`" for x in variants))
            if k == "Ratio":
                lst = expect_list(val)
                return {"Ratio": [expect_int(lst[0], "u16") if len(lst) > 0 else 0, expect_int(lst[1], "u16") if len(lst) > 1 else 0]}
            return {k: expect_int(val, "u16")}
    err(f"invalid type: {type_desc(v)}, expected enum Constraint")

def conv_layout_config(v):
    return conv_struct(v, [
        ("margin", lambda x: None if x is None else expect_int(x, "u16"), None),
        ("horizontal_margin", lambda x: None if x is None else expect_int(x, "u16"), None),
        ("vertical_margin", lambda x: None if x is None else expect_int(x, "u16"), None),
        ("constraints", lambda x: None if x is None else [conv_constraint(i) for i in expect_list(x)], None),
    ])

LAYOUT_UNITS = ["Nothing","Table","InputAndLogs","Selection","HelpMenu","SortAndFilter"]
def conv_layout(v):
    if isinstance(v, str):
        if v in LAYOUT_UNITS: return v
        err(f"unknown variant `{v}`, expected one of " + ", ".join(f"`{x}`" for x in LAYOUT_UNITS + ["Static","Dynamic","Horizontal","Vertical","CustomContent"]))
    if isinstance(v, LuaTable):
        pairs = v.items()
        if len(pairs) != 1:
            err("invalid value: map, expected map with a single key")
        k, val = pairs[0]
        if k == "Static": return {"Static": conv_custom_panel(val)}
        if k == "Dynamic": return {"Dynamic": expect_string(val)}
        if k in ("Horizontal", "Vertical"):
            # config and splits required
            expect_table(val)
            for kk, vv in val.items():
                if kk not in ("config", "splits"):
                    err(f"unknown field `{kk}`, expected `config` or `splits`")
            if not val.has("config"): err("missing field `config`")
            if not val.has("splits"): err("missing field `splits`")
            return {k: {"config": conv_layout_config(val.rawget("config")), "splits": [conv_layout(x) for x in expect_list(val.rawget("splits"))]}}
        if k == "CustomContent": return {"CustomContent": conv_custom_panel(val)}
        err(f"unknown variant `{k}`, expected one of " + ", ".join(f"`{x}`" for x in LAYOUT_UNITS + ["Static","Dynamic","Horizontal","Vertical","CustomContent"]))
    err(f"invalid type: {type_desc(v)}, expected enum Layout")

def conv_custom_panel(v):
    if isinstance(v, LuaTable):
        pairs = v.items()
        if len(pairs) != 1:
            err("invalid value: map, expected map with a single key")
        k, val = pairs[0]
        if k == "CustomParagraph":
            return {"CustomParagraph": conv_struct(val, [("ui", lambda x: None if x is None else conv_panel_ui(x), None), ("body", expect_string, None)])}
        if k == "CustomList":
            return {"CustomList": conv_struct(val, [("ui", lambda x: None if x is None else conv_panel_ui(x), None), ("body", lambda x: [expect_string(i) for i in expect_list(x)], None)])}
        if k == "CustomTable":
            return {"CustomTable": conv_struct(val, [("ui", lambda x: None if x is None else conv_panel_ui(x), None), ("widths", lambda x: None if x is None else [conv_constraint(i) for i in expect_list(x)], None), ("col_spacing", lambda x: None if x is None else expect_int(x, "u16"), None), ("body", lambda x: [[expect_string(c) for c in expect_list(r)] for r in expect_list(x)], None)])}
        if k == "CustomLayout":
            return {"CustomLayout": conv_layout(val)}
        err(f"unknown variant `{k}`, expected one of `CustomParagraph`, `CustomList`, `CustomTable`, `CustomLayout`")
    err(f"invalid type: {type_desc(v)}, expected enum CustomPanel")

# ------------- messages from Lua -------------
def message_from_lua(v):
    if isinstance(v, str):
        if v in UNIT: return Msg(v)
        if v in PAYLOAD: err("invalid type: unit variant, expected newtype variant")
        err(f"unknown variant `{v}`, expected one of " + ", ".join(f"`{x}`" for x in VARIANTS))
    if isinstance(v, LuaTable):
        pairs = [(k, val) for k, val in v.items() if isinstance(k, str)]
        # a Lua table with a single string key
        allpairs = v.items()
        if len(allpairs) != 1 or len(pairs) != 1:
            err("invalid value: map, expected map with a single key")
        name, payload = pairs[0]
        if name not in VARIANTS:
            err(f"unknown variant `{name}`, expected one of " + ", ".join(f"`{x}`" for x in VARIANTS))
        if name in UNIT:
            # payload cannot be non-nil in lua construction meaningfully
            return Msg(name)
        kind = PAYLOAD.get(name)
        return Msg(name, _lua_payload(kind, payload))
    err(f"invalid type: {type_desc(v)}, expected enum ExternalMsg")

def _lua_payload(kind, v):
    if kind == "string":
        if not isinstance(v, str): err(f"invalid type: {type_desc(v)}, expected a string")
        return v
    if kind == "usize":
        n = expect_int(v, "usize")
        if n < 0: err(f"invalid value: integer `{n}`, expected usize")
        return n
    if kind == "command":
        s = conv_struct(v, [("command", expect_string, None), ("args", lambda x: None if x is None else [expect_string(i) for i in expect_list(x)], None)])
        return {"command": s["command"], "args": s["args"]}
    if kind == "filter_applicable":
        s = conv_struct(v, [("filter", lambda x: _enum_lua(x, FILTERS), None), ("input", expect_string, None)])
        return {"filter": s["filter"], "input": s["input"]}
    if kind == "filter_enum": return _enum_lua(v, FILTERS)
    if kind == "sorter_applicable":
        s = conv_struct(v, [("sorter", lambda x: _enum_lua(x, SORTERS), None), ("reverse", lambda x: None if x is None else expect_bool(x), None)])
        return {"sorter": s["sorter"], "reverse": s["reverse"]}
    if kind == "sorter_enum": return _enum_lua(v, SORTERS)
    if kind == "input_operation":
        from messages import INPUT_OPS_UNIT
        if isinstance(v, str):
            if v in INPUT_OPS_UNIT: return v
            err(f"unknown variant `{v}`, expected one of " + ", ".join(f"`{x}`" for x in ["SetCursor","InsertCharacter"] + INPUT_OPS_UNIT))
        if isinstance(v, LuaTable):
            pairs = v.items()
            if len(pairs) != 1: err("invalid value: map, expected map with a single key")
            k, val = pairs[0]
            if k == "SetCursor": return {"SetCursor": _lua_payload("usize", val)}
            if k == "InsertCharacter":
                if not isinstance(val, str): err(f"invalid type: {type_desc(val)}, expected a character")
                if len(val) != 1: err(f"invalid value: string \"{val}\", expected a character")
                return {"InsertCharacter": val}
            err(f"unknown variant `{k}`")
    err("invalid payload")

def _enum_lua(v, items):
    if not isinstance(v, str): err(f"invalid type: {type_desc(v)}, expected a string")
    if v not in items:
        err(f"unknown variant `{v}`, expected one of " + ", ".join(f"`{x}`" for x in items))
    return v

def messages_from_lua_list(v):
    if v is None: return []
    return [message_from_lua(x) for x in expect_list(v)]

