from luamod import LuaTable, LuaFunction, NativeFunction, MultiReturn
from messages import Msg

def to_lua(state, value):
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, (LuaTable, LuaFunction, NativeFunction)):
        return value
    if isinstance(value, Msg):
        return msg_to_lua(state, value)
    if isinstance(value, dict):
        t = LuaTable()
        for k, v in value.items():
            lv = to_lua(state, v)
            if lv is None:
                continue
            t.rawset(k, lv)
        return t
    if isinstance(value, (list, tuple)):
        t = LuaTable()
        for i, v in enumerate(value):
            lv = to_lua(state, v)
            if lv is not None: t.rawset(i + 1, lv)
        return t
    # Node / Resolved objects
    if hasattr(value, "to_dict"):
        return to_lua(state, value.to_dict())
    return str(value)

def msg_to_lua(state, msg):
    if msg.value is None and msg.name in __import__("messages").UNIT:
        return msg.name
    t = LuaTable(); t.rawset(msg.name, to_lua(state, _msg_payload_for_lua(msg)))
    return t

def _msg_payload_for_lua(msg):
    from messages import PAYLOAD
    if PAYLOAD.get(msg.name) == "command":
        out = {"command": msg.value.get("command")}
        if msg.value.get("args") is not None: out["args"] = msg.value["args"]
        return out
    if PAYLOAD.get(msg.name) == "sorter_applicable":
        out = {"sorter": msg.value.get("sorter")}
        if msg.value.get("reverse") is not None: out["reverse"] = msg.value["reverse"]
        return out
    return msg.value

def from_lua(value):
    """generic Lua value -> Python (for json/yaml etc)."""
    if isinstance(value, LuaTable):
        items = value.items()
        if not items:
            return {}
        if value.is_array_like():
            return [from_lua(value.rawget(i)) for i in range(1, len(items) + 1)]
        out = {}
        for k, v in items:
            out[k] = from_lua(v)
        return out
    return value

def lua_style_to_table(style):
    """Style dict (config representation) -> Lua table with only set fields."""
    t = LuaTable()
    if not style: return t
    if style.get("fg") is not None: t.rawset("fg", to_lua(None, style["fg"]))
    if style.get("bg") is not None: t.rawset("bg", to_lua(None, style["bg"]))
    if style.get("add_modifiers") is not None:
        mt = LuaTable()
        for i, m in enumerate(style["add_modifiers"]): mt.rawset(i + 1, m)
        t.rawset("add_modifiers", mt)
    if style.get("sub_modifiers") is not None:
        mt = LuaTable()
        for i, m in enumerate(style["sub_modifiers"]): mt.rawset(i + 1, m)
        t.rawset("sub_modifiers", mt)
    return t

def style_from_lua(v):
    style = {"fg": None, "bg": None, "add_modifiers": None, "sub_modifiers": None}
    if isinstance(v, LuaTable):
        if v.has("fg"): style["fg"] = from_lua(v.rawget("fg"))
        if v.has("bg"): style["bg"] = from_lua(v.rawget("bg"))
        if v.has("add_modifiers"): style["add_modifiers"] = from_lua_list(v.rawget("add_modifiers"))
        if v.has("sub_modifiers"): style["sub_modifiers"] = from_lua_list(v.rawget("sub_modifiers"))
    return style

def from_lua_list(v):
    if isinstance(v, LuaTable):
        out = []; i = 1
        while v.has(i): out.append(from_lua(v.rawget(i))); i += 1
        return out
    if v is None: return []
    return [from_lua(v)]
