def _style_patch(base, over):
    if not over: return dict(base) if base else {"fg": None, "bg": None, "add_modifiers": None, "sub_modifiers": None}
    out = dict(base) if base else {"fg": None, "bg": None, "add_modifiers": None, "sub_modifiers": None}
    if over.get("fg") is not None: out["fg"] = over["fg"]
    if over.get("bg") is not None: out["bg"] = over["bg"]
    # modifiers: patch semantics
    add = list(out.get("add_modifiers") or [])
    sub = list(out.get("sub_modifiers") or [])
    for m in (over.get("add_modifiers") or []):
        if m not in add: add.append(m)
        if m in sub: sub.remove(m)
    for m in (over.get("sub_modifiers") or []):
        if m not in sub: sub.append(m)
        if m in add: add.remove(m)
    out["add_modifiers"] = add if (out.get("add_modifiers") is not None or over.get("add_modifiers") is not None or over.get("sub_modifiers") is not None) else None
    out["sub_modifiers"] = sub if (out.get("sub_modifiers") is not None or over.get("sub_modifiers") is not None or over.get("add_modifiers") is not None) else None
    # if original style had explicit modifier lists after patch, xplr returns patched lists
    if over.get("add_modifiers") is not None or over.get("sub_modifiers") is not None:
        if out["add_modifiers"] is None: out["add_modifiers"] = add
        if out["sub_modifiers"] is None: out["sub_modifiers"] = sub
    return out

def resolve_node_type(node, node_types):
    """node: Node or dict. Returns {'style':..., 'meta':...}"""
    def get(obj, key, default=None):
        if isinstance(obj, dict): return obj.get(key, default)
        return getattr(obj, key, default)
    style = {"fg": None, "bg": None, "add_modifiers": None, "sub_modifiers": None}
    meta = {}
    def apply(nt):
        nonlocal style
        if not nt: return
        style = _style_patch(style, nt.get("style"))
        for k, v in (nt.get("meta") or {}).items():
            if v is not None: meta[k] = v
    if not node_types:
        return {"style": style, "meta": meta}
    if get(node, "is_symlink"): apply(node_types.get("symlink"))
    elif get(node, "is_dir"): apply(node_types.get("directory"))
    else: apply(node_types.get("file"))
    mime = get(node, "mime_essence") or ""
    if mime and "/" in mime:
        major, minor = mime.split("/", 1)
        mimes = node_types.get("mime_essence") or {}
        if major in mimes:
            apply(mimes[major].get("*"))
            apply(mimes[major].get(minor))
    ext = get(node, "extension") or ""
    if ext:
        apply((node_types.get("extension") or {}).get(ext))
    rel = get(node, "relative_path") or ""
    apply((node_types.get("special") or {}).get(rel))
    return {"style": style, "meta": meta}
