        return {"fg": s.get("fg"), "bg": s.get("bg"), "add_modifiers": s.get("add_modifiers"), "sub_modifiers": s.get("sub_modifiers")}
    def fix_nt(nt):
        if nt is None: return {"style": fix_style(None), "meta": {}}
        return {"style": fix_style(nt.get("style")), "meta": nt.get("meta") or {}}
    out = {"directory": fix_nt(raw.get("directory")), "file": fix_nt(raw.get("file")), "symlink": fix_nt(raw.get("symlink")), "mime_essence": {}, "extension": {}, "special": {}}
    for major, sub in (raw.get("mime_essence") or {}).items(): out["mime_essence"][major] = {k: fix_nt(v) for k, v in sub.items()}
    for k, v in (raw.get("extension") or {}).items(): out["extension"][k] = fix_nt(v)
