    p = a[0] if a else ""
    if not isinstance(p, str): return None
    abs_p = absolutize(p, _pwd(st))
    if not os.path.isdir(abs_p):
        raise LuaError(f'could not explore "{abs_p}"')
    cfg = {"filters": [], "sorters": [], "searcher": None}
    if len(a) > 1 and isinstance(a[1], LuaTable):
        raw = from_lua(a[1])
        if isinstance(raw, dict):
            cfg["filters"] = raw.get("filters") or []
            cfg["sorters"] = raw.get("sorters") or []
            cfg["searcher"] = raw.get("searcher")
            # sorter reverse may be missing
            for s in cfg["sorters"]:
                if isinstance(s, dict) and s.get("reverse") is None: s["reverse"] = False
    nodes = explore_dir(abs_p, cfg)
