        self.directory_buffer = {"parent": self.pwd, "nodes": nodes, "total": len(nodes), "focus": 0}

    def explore_pwd(self):
        old_focus_abs = self.focused_path(); old_index = self.directory_buffer["focus"]
        nodes = explore_dir(self.pwd, self.explorer_config)
        self.directory_buffer["nodes"] = nodes
        self.directory_buffer["total"] = len(nodes)
        self.directory_buffer["parent"] = self.pwd
        if not nodes:
            self.directory_buffer["focus"] = 0
        else:
            idx = None
            if old_focus_abs:
                for i, n in enumerate(nodes):
                    if n.absolute_path == old_focus_abs: idx = i; break
            if idx is None: idx = min(old_index, len(nodes) - 1)
            self.directory_buffer["focus"] = idx
        focused = self.focused_node()
        self.last_focus[self.pwd] = focused.relative_path if focused else None
        if self.focused_path() != old_focus_abs:
            return self._hook_messages("on_focus_change")
        return []

    # ---------------- hooks/history ----------------
    def _hook_messages(self, name):
        msgs = self.hooks.get(name) or []
        return list(msgs)

    def _push_history(self, path):
        # truncate forward entries and append if different from current loc entry
        loc = self.history["loc"]
        paths = self.history["paths"]
        if 0 <= loc < len(paths) and paths[loc] == path:
            return
        del paths[loc + 1:]
        paths.append(path)
        self.history["loc"] = len(paths) - 1

    # ---------------- focus ----------------
    def _set_focus_index(self, idx, push=False):
        total = self.directory_buffer["total"]
        if total == 0: return []
        idx = max(0, min(idx, total - 1))
        old = self.focused_path()
        if idx == self.directory_buffer["focus"] and self.focused_path() == old:
            # may still be same; no change
            if idx == self.directory_buffer["focus"]: return []
        self.directory_buffer["focus"] = idx
        focused = self.focused_node()
        self.last_focus[self.pwd] = focused.relative_path if focused else None
        if self.fifo_file is not None and focused is not None:
            self._fifo_write(focused.absolute_path)
        if push and focused is not None:
            self._push_history(focused.absolute_path)
        if self.focused_path() != old:
            return self._hook_messages("on_focus_change")
        return []

    def _focus_by_absolute(self, abs_path, push=False):
        for i, n in enumerate(self.directory_buffer["nodes"]):
            if n.absolute_path == abs_path:
                return self._set_focus_index(i, push=push)
        return []

    # ---------------- directory ----------------
    def change_directory_internal(self, new_pwd, history_kind="dir", focus_name=None):
        old_pwd = self.pwd; old_focus = self.focused_path()
        self.explorer_config["searcher"] = None
        hooks = []
        try: os.chdir(new_pwd)
        except OSError as e:
            self.log_error(f'could not enter "{new_pwd}": {os.strerror(e.errno)} (os error {e.errno})')
            return []
        self.pwd = new_pwd
        # explore new dir
        nodes = explore_dir(self.pwd, self.explorer_config)
        self.directory_buffer = {"parent": self.pwd, "nodes": nodes, "total": len(nodes), "focus": 0}
        idx = None
        if focus_name:
            for i, n in enumerate(nodes):
                if n.relative_path == focus_name: idx = i; break
        if idx is None:
            lf = self.last_focus.get(self.pwd)
            if lf:
                for i, n in enumerate(nodes):
                    if n.relative_path == lf: idx = i; break
        if idx is None: idx = 0
        self.directory_buffer["focus"] = idx if nodes else 0
        focused = self.focused_node()
        self.last_focus[self.pwd] = focused.relative_path if focused else None
        if history_kind == "dir":
            self._push_history(_dir_entry(new_pwd))
        elif history_kind == "back":
            self._push_history(old_pwd)
        if new_pwd != old_pwd:
            hooks += self._hook_messages("on_directory_change")
        if self.focused_path() != old_focus:
            hooks += self._hook_messages("on_focus_change")
        if self.fifo_file is not None:
            self._fifo_write(self.focused_path() or "")
        return hooks

    # ---------------- logging ----------------
    def log(self, level, message):
        self.logs.append(Log(level, str(message)))
    def log_info(self, m): self.log("INFO", m)
    def log_success(self, m): self.log("SUCCESS", m)
    def log_warning(self, m): self.log("WARNING", m)
    def log_error(self, m): self.log("ERROR", m)

    # ---------------- lua helpers ----------------
    def lua_error_text(self, e):
        if isinstance(e, LuaSyntaxError):
            return "syntax error: " + e.text
        if isinstance(e, LuaError):
            msg = e.value if isinstance(e.value, str) else (lua_tostring(self.lua, e.value) if e.value is not None else str(e))
            trace = getattr(e, "trace", None)
            if trace: return f"runtime error: {msg}\n{trace}"
            return f"runtime error: {msg}"
        return str(e)

    def resolve_lua_function(self, path):
        if not isinstance(path, str): return None
        xplr = self.lua.globals.rawget("xplr")
        if not isinstance(xplr, LuaTable): return None
        fn_tbl = xplr.rawget("fn")
        cur = fn_tbl
        for part in path.split("."):
            if not isinstance(cur, LuaTable): return None
            cur = cur.rawget(part)
        return cur

    def call_lua_function(self, path, arg_lua):
        fn = self.resolve_lua_function(path)
        if fn is None or not isinstance(fn, (LuaFunction, NativeFunction)):
            if not _is_callable(self.lua, fn):
                return None, "Nil is not a function"
        try:
            vals = self.lua.call_multi(fn, [arg_lua])
        except (LuaError, LuaSyntaxError) as e:
            return None, self.lua_error_text(e)
        return vals, None

    def app_context_lua(self, full=True):
        ctx = {}
        ctx["version"] = VERSION
        ctx["pwd"] = self.pwd
        ctx["initial_pwd"] = self.initial_pwd
        ctx["vroot"] = self.vroot
        fn = self.focused_node()
        ctx["focused_node"] = fn.to_dict() if fn else None
        if full:
            ctx["directory_buffer"] = {"parent": self.directory_buffer["parent"], "nodes": [n.to_dict() for n in self.directory_buffer["nodes"]], "total": self.directory_buffer["total"], "focus": self.directory_buffer["focus"]}
        ctx["selection"] = [n.to_dict() for n in self.selection.values()]
        ctx["mode"] = plain_value(self.mode)
        ctx["layout"] = plain_value(self.layout)
        ctx["input_buffer"] = self.input_buffer["value"] if self.input_buffer else None
        ctx["pid"] = self.pid
        ctx["session_path"] = self.session_path
        ctx["explorer_config"] = plain_value(self.explorer_config)
        if full:
            ctx["history"] = {"loc": self.history["loc"], "paths": list(self.history["paths"])}
            ctx["last_modes"] = [plain_value(m[1]) for m in self.last_modes]
        return to_lua(self.lua, ctx)

    def node_renderer_arg(self, node, index):
        nodes = self.directory_buffer["nodes"]; focus = self.directory_buffer["focus"]; total = len(nodes)
        gen = self.config["general"]
        is_focused = index == focus
        is_selected = node.absolute_path in self.selection
        if is_focused and is_selected: ui = gen.get("focus_selection_ui") or {}
        elif is_focused: ui = gen.get("focus_ui") or {}
        elif is_selected: ui = gen.get("selection_ui") or {}
        else: ui = gen.get("default_ui") or {}
        nt = resolve_node_type(node, self.config["node_types"])
        from nodes import _style_patch
        style = _style_patch(nt["style"], ui.get("style"))
        tree_list = gen.get("table", {}).get("tree") or []
        if not tree_list: tree_str = ""
        elif index == total - 1: tree_str = (tree_list[2].get("format") or "") if len(tree_list) > 2 else (tree_list[-1].get("format") or "")
        elif index == 0: tree_str = tree_list[0].get("format") or ""
        else: tree_str = (tree_list[1].get("format") or "") if len(tree_list) > 1 else (tree_list[0].get("format") or "")
        arg = node.to_dict()
        arg.update({
            "index": index, "relative_index": index - focus,
            "is_before_focus": index < focus, "is_after_focus": index > focus,
            "tree": tree_str, "prefix": ui.get("prefix") or "", "suffix": ui.get("suffix") or "",
            "is_selected": is_selected, "is_focused": is_focused, "total": total,
            "style": style, "meta": nt["meta"],
        })
        return arg

    def call_renderer(self, format_name, arg_python):
        """Returns the rendered string (or an error string like the original)."""
        fn = self.resolve_lua_function(format_name) if isinstance(format_name, str) else None
        if fn is None or not _is_callable(self.lua, fn):
            return "Nil is not a function"
        arg_lua = _renderer_arg_to_lua(self.lua, arg_python)
        try:
            vals = self.lua.call_multi(fn, [arg_lua])
        except (LuaError, LuaSyntaxError) as e:
            return self.lua_error_text(e)
        if not vals:
            return "deserialize error: invalid type: unit value, expected a string"
        v = vals[0]
        if isinstance(v, str): return v
        return f"deserialize error: invalid type: {_lua_type_desc(v)}, expected a string"

    # ---------------- pipes ----------------
    def write_pipes(self, delimiter="\0"):
        try: os.makedirs(self.pipe_path, exist_ok=True)
        except OSError: pass
        d = delimiter
        def write(name, content):
            try:
                with open(os.path.join(self.pipe_path, name), "wb") as f:
                    f.write(content.encode("utf-8", "surrogateescape"))
            except OSError: pass
        write("msg_in", d)
        write("selection_out", "".join(p + d for p in self.selection.keys()))
        write("result_out", "".join(p + d for p in self._result_paths()))
        write("directory_nodes_out", "".join(n.absolute_path + d for n in self.directory_buffer["nodes"]))
        write("history_out", "".join(p + d for p in self.history["paths"]))
        logs_txt = "".join(self._log_pipe_entry(l) + d for l in self.logs)
        write("logs_out", logs_txt)
        write("global_help_menu_out", "".join(e + d for e in self.global_help_entries()))

    def _log_pipe_entry(self, log):
        from coreutil import format_rfc3339
        return f"[{format_rfc3339(log.dt)}] {log.level:<8}{log.message}"

    def _result_paths(self):
        if self.selection: return list(self.selection.keys())
        fp = self.focused_path()
        return [fp] if fp else []

    def global_help_entries(self):
        entries = []
        seen_current = self.mode_id
        ordered = []
        if seen_current: ordered.append(seen_current)
        for key in self.config["modes"]["builtin"]: ordered.append(("builtin", key))
        for key in self.config["modes"]["custom"]: ordered.append(("custom", key))
        for mid in ordered:
            mode = self.config["modes"][mid[0]].get(mid[1])
            if mode is None: continue
            key = mid[1]
            entries.append(f"### {key}")
            entries.append("")
            entries.append(" key             | remaps                    | action\n --------------- | ------------------------- | ------")
            for (k, remaps, help_text) in self.help_rows(mid, mode):
                entries.append(f" {k:<15} | {', '.join(remaps):<25} | {help_text}")
            entries.append("")
            entries.append("")
        return entries

    def help_rows(self, mode_id, mode):
        """Returns list of (key, [remaps], help) for the effective bindings of a mode."""
        return help_rows_for(self.config, mode)

    # ---------------- fifo ----------------
    def _fifo_write(self, path):
        if self.fifo_file is None: return
        try:
            self.fifo_file.write((path + "\n").encode("utf-8", "surrogateescape")); self.fifo_file.flush()
        except OSError:
            try: self.fifo_file.close()
            except Exception: pass
            self.fifo_file = None

    # ---------------- state ----------------
    def state_dict(self):
        from coreutil import created_at_list
        return {
            "bin": self.bin, "version": VERSION, "config": plain_value(self.config),
            "hooks": {k: [plain_value(m) for m in v] for k, v in self.hooks.items()},
            "vroot": self.vroot, "initial_vroot": self.initial_vroot,
            "pwd": self.pwd, "initial_pwd": self.initial_pwd,
            "directory_buffer": {"parent": self.directory_buffer["parent"], "nodes": [n.to_dict() for n in self.directory_buffer["nodes"]], "total": self.directory_buffer["total"], "focus": self.directory_buffer["focus"]},
            "last_focus": dict(self.last_focus),
            "selection": [n.to_dict() for n in self.selection.values()],
            "msg_out": [plain_value(m) for m in self.msg_out],
            "mode": plain_value(_mode_for_state(self.mode)),
            "layout": plain_value(self.layout),
            "input": {"buffer": ({"value": self.input_buffer["value"], "cursor": self.input_buffer["cursor"]} if self.input_buffer else None), "prompt": self.prompt},
            "pid": self.pid, "session_path": self.session_path, "pipe": dict(self.pipe),
            "explorer_config": plain_value(self.explorer_config),
            "logs": [{"level": l.level, "message": l.message, "created_at": created_at_list(l.dt)} for l in self.logs],
            "logs_hidden": self.input_buffer is not None,
            "history": {"loc": self.history["loc"], "paths": list(self.history["paths"])},
            "last_modes": [plain_value(_mode_for_state(m[1])) for m in self.last_modes],
            "hostname": socket.gethostname(),
        }

    def state_yaml(self):
        import yamlmini
        return yamlmini.dump_yaml(self.state_dict())

    # ---------------- message entry point ----------------
    def process_queue(self, queue):
        """Process msgs; injected messages go in front of the remaining queue."""
        while queue:
            msg = queue.popleft()
            injected = self.handle_message(msg)
            if injected:
                for m in reversed(injected):
                    queue.appendleft(m)

    def handle_message(self, msg):
        handler = getattr(self, "_msg_" + msg.name, None)
        if handler is None:
            return []
        return handler(msg.value) or []

    # helpers used by handlers
    def _input_value(self):
        return self.input_buffer["value"] if self.input_buffer else ""

    def _parse_input_usize(self):
        if self.input_buffer is None: return None
        s = self.input_buffer["value"]
        if re_fullmatch_usize(s): return int(s)
        return None

    # focus movement messages
    def _msg_FocusNext(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        f = self.directory_buffer["focus"]
        if f >= total - 1:
            if self.config["general"].get("enforce_bounded_index_navigation"): return []
            return self._set_focus_index(0)
        return self._set_focus_index(f + 1)

    def _msg_FocusPrevious(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        f = self.directory_buffer["focus"]
        if f <= 0:
            if self.config["general"].get("enforce_bounded_index_navigation"): return []
            return self._set_focus_index(total - 1)
        return self._set_focus_index(f - 1)

    def _msg_FocusNextByRelativeIndex(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        return self._set_focus_index(self.directory_buffer["focus"] + v, push=True)
    def _msg_FocusPreviousByRelativeIndex(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        return self._set_focus_index(self.directory_buffer["focus"] - v, push=True)
    def _msg_FocusNextByRelativeIndexFromInput(self, v):
        n = self._parse_input_usize()
        return self._msg_FocusNextByRelativeIndex(n) if n is not None else []
    def _msg_FocusPreviousByRelativeIndexFromInput(self, v):
        n = self._parse_input_usize()
        return self._msg_FocusPreviousByRelativeIndex(n) if n is not None else []
    def _msg_FocusFirst(self, v): return self._set_focus_index(0, push=True) if self.directory_buffer["total"] else []
    def _msg_FocusLast(self, v): return self._set_focus_index(self.directory_buffer["total"] - 1, push=True) if self.directory_buffer["total"] else []
    def _msg_FocusByIndex(self, v):
        if self.directory_buffer["total"] == 0: return []
        return self._set_focus_index(v, push=True)
    def _msg_FocusByIndexFromInput(self, v):
        n = self._parse_input_usize()
        return self._msg_FocusByIndex(n) if n is not None else []
    def _msg_FocusByFileName(self, v):
        for i, n in enumerate(self.directory_buffer["nodes"]):
            if n.relative_path == v:
                return self._set_focus_index(i, push=True)
        self.log_error(f'"{v}" not found in $PWD')
        return []
    def _msg_FocusByFileNameFromInput(self, v): return []
    def _msg_FocusPath(self, v):
        return self._focus_path_internal(v)
    def _msg_FocusPathFromInput(self, v):
        if self.input_buffer is None: return []
        return self._focus_path_internal(self._input_value())
    def _msg_FocusNextSelection(self, v):
        nodes = self.directory_buffer["nodes"]; total = len(nodes)
        if total == 0 or not self.selection: return []
        f = self.directory_buffer["focus"]
        for step in range(1, total + 1):
            i = (f + step) % total
            if nodes[i].absolute_path in self.selection:
                if i == f: return []
                return self._set_focus_index(i)
        return []
    def _msg_FocusPreviousSelection(self, v):
        nodes = self.directory_buffer["nodes"]; total = len(nodes)
        if total == 0 or not self.selection: return []
        f = self.directory_buffer["focus"]
        for step in range(1, total + 1):
            i = (f - step) % total
            if nodes[i].absolute_path in self.selection:
                if i == f: return []
                return self._set_focus_index(i)
        return []

    def _focus_path_internal(self, path, initial=False):
        if path == "": return []
        resolved = absolutize(path, self.pwd)
        parent = path_parent(resolved); name = path_basename(resolved)
        hooks = []
        if parent != self.pwd:
            # change directory to parent (validating like ChangeDirectory)
            if self.vroot and not _is_within(parent, self.vroot):
                self.log_error(f'"{parent}" is outside of virtual root "{self.vroot}"'); return []
            if not os.path.isdir(parent):
                import errno as _e
                eno = 2 if not os.path.exists(parent) else 20
                self.log_error(f'could not enter "{parent}": {os.strerror(eno)} (os error {eno})'); return []
            hooks += self.change_directory_internal(parent, history_kind="none")
        # now find name
        for i, n in enumerate(self.directory_buffer["nodes"]):
            if n.relative_path == name:
                hooks += self._set_focus_index(i, push=not initial or True)
                return hooks
        if not initial:
            self.log_error(f'"{name}" not found in $PWD')
        else:
            # At startup, if the target node is filtered out, original focuses by name if present;
            # mimic the not-found log as well when the file exists but is not visible? It is safer to log.
            self.log_error(f'"{name}" not found in $PWD')
        return hooks

    def _msg_ScrollUp(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        h = self.terminal_size[1]
        return self._set_focus_index(self.directory_buffer["focus"] - h, push=True)
    def _msg_ScrollDown(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        h = self.terminal_size[1]
        return self._set_focus_index(self.directory_buffer["focus"] + h, push=True)
    def _msg_ScrollUpHalf(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        h = self.terminal_size[1] // 2
        return self._set_focus_index(self.directory_buffer["focus"] - h, push=True)
    def _msg_ScrollDownHalf(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        h = self.terminal_size[1] // 2
        return self._set_focus_index(self.directory_buffer["focus"] + h, push=True)

    # exploring
    def _msg_ExplorePwd(self, v): return self.explore_pwd()
    def _msg_ExplorePwdAsync(self, v): return self.explore_pwd()
    def _msg_ExploreParentsAsync(self, v):
        self._init_last_focus(); return []
    def _msg_ClearScreen(self, v):
        if self.runner: self.runner.request_clear()
        return []
    def _msg_Refresh(self, v): return []

    # navigation / directory
    def _msg_ChangeDirectory(self, v):
        resolved = absolutize(v, self.pwd)
        if self.vroot and not _is_within(resolved, self.vroot):
            self.log_error(f'"{resolved}" is outside of virtual root "{self.vroot}"'); return []
        if not os.path.isdir(resolved):
            eno = 2 if not os.path.exists(resolved) else 20
            self.log_error(f'could not enter "{resolved}": {os.strerror(eno)} (os error {eno})'); return []
        return self.change_directory_internal(resolved, history_kind="dir")

    def _msg_Enter(self, v):
        n = self.focused_node()
        if n is None: return []
        if n.is_dir: return self.change_directory_internal(n.absolute_path, history_kind="dir")
        if n.canonical and n.canonical.is_dir: return self.change_directory_internal(n.absolute_path, history_kind="dir")
        return []

    def _msg_Back(self, v):
        if self.pwd == "/": return []
        parent = path_parent(self.pwd)
        if self.vroot and not _is_within(parent, self.vroot) and not _is_within(self.pwd, self.vroot):
            return []
        if self.vroot and parent != self.vroot and not _is_within(parent, self.vroot):
            # pwd == vroot case: parent outside; do nothing
            if self.pwd == self.vroot: return []
        if self.vroot and self.pwd == self.vroot: return []
        old = self.pwd
        return self.change_directory_internal(parent, history_kind="back", focus_name=path_basename(old))

    def _msg_LastVisitedPath(self, v):
        if self.history["loc"] <= 0: return []
        self.history["loc"] -= 1
        return self._navigate_history_entry(self.history["paths"][self.history["loc"]])
    def _msg_NextVisitedPath(self, v):
        if self.history["loc"] >= len(self.history["paths"]) - 1: return []
        self.history["loc"] += 1
        return self._navigate_history_entry(self.history["paths"][self.history["loc"]])

    def _navigate_history_entry(self, entry):
        if entry == "/" or entry.endswith("/"):
            target = entry.rstrip("/") or "/"
            if target == self.pwd:
                # re-explore, focus first
                old = self.focused_path(); self.explore_pwd(); self.directory_buffer["focus"] = 0 if self.directory_buffer["total"] else 0
                focused = self.focused_node(); self.last_focus[self.pwd] = focused.relative_path if focused else None
                return self._hook_messages("on_focus_change") if self.focused_path() != old else []
            return self.change_directory_internal(target, history_kind="none")
        # node entry
        parent = path_parent(entry); name = path_basename(entry)
        hooks = []
        if parent != self.pwd:
            hooks += self.change_directory_internal(parent, history_kind="none")
        for i, n in enumerate(self.directory_buffer["nodes"]):
            if n.relative_path == name:
                hooks += self._set_focus_index(i); break
        return hooks

    def _deep_branches(self):
        paths = self.history["paths"]
        deeps = []
        for p in paths:
            if p == "/" or p.endswith("/"):
                # deep if it is not an ancestor of another entry
                norm = p.rstrip("/") or "/"
                is_anc = False
                for q in paths:
                    if q == p: continue
                    qn = q.rstrip("/") or "/"
                    if qn != norm and (qn.startswith(norm + "/") if norm != "/" else qn != "/"):
                        is_anc = True; break
                if not is_anc and p not in deeps: deeps.append(p)
        return deeps

    def _msg_PreviousVisitedDeepBranch(self, v):
        deeps = self._deep_branches()
        cur = _dir_entry(self.pwd)
        # find previous deep before current in list order
        cands = [d for d in deeps if d != cur]
        if not cands: return []
        if cur in deeps:
            idx = deeps.index(cur); target = deeps[idx - 1] if idx > 0 else None
        else:
            # previous deep branch in history order before current position
            target = None
            loc = self.history["loc"]
            for p in reversed(self.history["paths"][:loc]):
                if p in deeps and p != cur: target = p; break
        if target is None: return []
        return self.change_directory_internal(target.rstrip("/") or "/", history_kind="dir")
    def _msg_NextVisitedDeepBranch(self, v):
        deeps = self._deep_branches()
        cur = _dir_entry(self.pwd)
        if cur in deeps:
            idx = deeps.index(cur); target = deeps[idx + 1] if idx + 1 < len(deeps) else None
        else:
            target = None
            for p in self.history["paths"][self.history["loc"] + 1:]:
                if p in deeps and p != cur: target = p; break
            if target is None and deeps:
                # wrap to next deep after current in global order
                for d in deeps:
                    if d != cur: target = d; break
        if target is None: return []
        return self.change_directory_internal(target.rstrip("/") or "/", history_kind="dir")

    def _msg_FollowSymlink(self, v):
        n = self.focused_node()
        if n is None or not n.is_symlink or n.canonical is None: return []
        return self._focus_path_internal(n.canonical.absolute_path)

