    # search
    def _new_searcher(self, pattern, algorithm=None, unordered=None):
        existing = self.explorer_config.get("searcher")
        gen_search = self.config["general"].get("search") or {}
        if existing:
            searcher = dict(existing)
            searcher["pattern"] = pattern
            if algorithm is not None: searcher["algorithm"] = algorithm
            if unordered is not None: searcher["unordered"] = unordered
        else:
            searcher = {
                "pattern": pattern,
                "recoverable_focus": self.focused_path(),
                "algorithm": algorithm if algorithm is not None else gen_search.get("algorithm", "Fuzzy"),
                "unordered": unordered if unordered is not None else bool(gen_search.get("unordered")),
                "exact_mode": bool(gen_search.get("exact_mode")),
                "rank_criteria": copy.deepcopy(gen_search.get("rank_criteria")),
            }
        self.explorer_config["searcher"] = searcher
        return []
    def _msg_Search(self, v): return self._new_searcher(v)
