    def global_help_entries(self):
        entries = []
        seen_current = self.mode_id
        ordered = []
        if seen_current: ordered.append(seen_current)
        for key in self.config["modes"]["builtin"]: ordered.append(("builtin", key))
        for key in self.config["modes"]["custom"]: ordered.append(("custom", key))
        for mid in ordered:
            mode = self.config["modes"][mid[0]].get(mid[1])
            if mode is None: continue
            key = mid[1]
            entries.append(f"### {key}")
            entries.append("")
            entries.append(" key             | remaps                    | action\n --------------- | ------------------------- | ------")
            for (k, remaps, help_text) in self.help_rows(mid, mode):
                entries.append(f" {k:<15} | {', '.join(remaps):<25} | {help_text}")
            entries.append("")
            entries.append("")
        return entries

    def help_rows(self, mode_id, mode):
        """Returns list of (key, [remaps], help) for the effective bindings of a mode."""
        return help_rows_for(self.config, mode)

    # ---------------- fifo ----------------
    def _fifo_write(self, path):
        if self.fifo_file is None: return
        try:
            self.fifo_file.write((path + "\n").encode("utf-8", "surrogateescape")); self.fifo_file.flush()
        except OSError:
            try: self.fifo_file.close()
            except Exception: pass
            self.fifo_file = None

