    # ---------------- message entry point ----------------
    def process_queue(self, queue):
        """Process msgs; injected messages go in front of the remaining queue."""
        while queue:
            msg = queue.popleft()
            injected = self.handle_message(msg)
            if injected:
                for m in reversed(injected):
                    queue.appendleft(m)

    def handle_message(self, msg):
        handler = getattr(self, "_msg_" + msg.name, None)
        if handler is None:
            return []
        return handler(msg.value) or []

    # helpers used by handlers
    def _input_value(self):
        return self.input_buffer["value"] if self.input_buffer else ""

    def _parse_input_usize(self):
        if self.input_buffer is None: return None
        s = self.input_buffer["value"]
        if re_fullmatch_usize(s): return int(s)
        return None

    # focus movement messages
    def _msg_FocusNext(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        f = self.directory_buffer["focus"]
        if f >= total - 1:
            if self.config["general"].get("enforce_bounded_index_navigation"): return []
            return self._set_focus_index(0)
        return self._set_focus_index(f + 1)

    def _msg_FocusPrevious(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        f = self.directory_buffer["focus"]
        if f <= 0:
            if self.config["general"].get("enforce_bounded_index_navigation"): return []
            return self._set_focus_index(total - 1)
        return self._set_focus_index(f - 1)

    def _msg_FocusNextByRelativeIndex(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        return self._set_focus_index(self.directory_buffer["focus"] + v, push=True)
    def _msg_FocusPreviousByRelativeIndex(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        return self._set_focus_index(self.directory_buffer["focus"] - v, push=True)
    def _msg_FocusNextByRelativeIndexFromInput(self, v):
        n = self._parse_input_usize()
        return self._msg_FocusNextByRelativeIndex(n) if n is not None else []
    def _msg_FocusPreviousByRelativeIndexFromInput(self, v):
        n = self._parse_input_usize()
        return self._msg_FocusPreviousByRelativeIndex(n) if n is not None else []
    def _msg_FocusFirst(self, v): return self._set_focus_index(0, push=True) if self.directory_buffer["total"] else []
    def _msg_FocusLast(self, v): return self._set_focus_index(self.directory_buffer["total"] - 1, push=True) if self.directory_buffer["total"] else []
    def _msg_FocusByIndex(self, v):
        if self.directory_buffer["total"] == 0: return []
        return self._set_focus_index(v, push=True)
    def _msg_FocusByIndexFromInput(self, v):
        n = self._parse_input_usize()
        return self._msg_FocusByIndex(n) if n is not None else []
    def _msg_FocusByFileName(self, v):
        for i, n in enumerate(self.directory_buffer["nodes"]):
            if n.relative_path == v:
                return self._set_focus_index(i, push=True)
        self.log_error(f'"{v}" not found in $PWD')
        return []
    def _msg_FocusByFileNameFromInput(self, v): return []
    def _msg_FocusPath(self, v):
        return self._focus_path_internal(v)
    def _msg_FocusPathFromInput(self, v):
        if self.input_buffer is None: return []
        return self._focus_path_internal(self._input_value())
    def _msg_FocusNextSelection(self, v):
        nodes = self.directory_buffer["nodes"]; total = len(nodes)
        if total == 0 or not self.selection: return []
        f = self.directory_buffer["focus"]
        for step in range(1, total + 1):
            i = (f + step) % total
            if nodes[i].absolute_path in self.selection:
                if i == f: return []
                return self._set_focus_index(i)
        return []
    def _msg_FocusPreviousSelection(self, v):
        nodes = self.directory_buffer["nodes"]; total = len(nodes)
        if total == 0 or not self.selection: return []
        f = self.directory_buffer["focus"]
        for step in range(1, total + 1):
            i = (f - step) % total
            if nodes[i].absolute_path in self.selection:
                if i == f: return []
                return self._set_focus_index(i)
        return []

    def _focus_path_internal(self, path, initial=False):
        if path == "": return []
        resolved = absolutize(path, self.pwd)
        parent = path_parent(resolved); name = path_basename(resolved)
        hooks = []
        if parent != self.pwd:
            # change directory to parent (validating like ChangeDirectory)
            if self.vroot and not _is_within(parent, self.vroot):
                self.log_error(f'"{parent}" is outside of virtual root "{self.vroot}"'); return []
            if not os.path.isdir(parent):
                import errno as _e
                eno = 2 if not os.path.exists(parent) else 20
                self.log_error(f'could not enter "{parent}": {os.strerror(eno)} (os error {eno})'); return []
            hooks += self.change_directory_internal(parent, history_kind="none")
        # now find name
        for i, n in enumerate(self.directory_buffer["nodes"]):
            if n.relative_path == name:
                hooks += self._set_focus_index(i, push=not initial or True)
                return hooks
        if not initial:
            self.log_error(f'"{name}" not found in $PWD')
        else:
            # At startup, if the target node is filtered out, original focuses by name if present;
            # mimic the not-found log as well when the file exists but is not visible? It is safer to log.
            self.log_error(f'"{name}" not found in $PWD')
        return hooks

    def _msg_ScrollUp(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        h = self.terminal_size[1]
        return self._set_focus_index(self.directory_buffer["focus"] - h, push=True)
    def _msg_ScrollDown(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        h = self.terminal_size[1]
        return self._set_focus_index(self.directory_buffer["focus"] + h, push=True)
    def _msg_ScrollUpHalf(self, v):
        total = self.directory_buffer["total"]
        if total == 0: return []
        h = self.terminal_size[1] // 2
        return self._set_focus_index(self.directory_buffer["focus"] - h, push=True)
    def _msg_ScrollDownHalf(self, v):
