    def _msg_SetVroot(self, v):
        resolved = absolutize(v, self.pwd)
        if not os.path.isdir(resolved):
            self.log_error(f'not a valid directory: "{resolved}"'); return []
        self.vroot = resolved
        if not _is_within(self.pwd, resolved):
            return self.change_directory_internal(resolved, history_kind="dir")
        return []
    def _msg_UnsetVroot(self, v): self.vroot = None; return []
    def _msg_ToggleVroot(self, v):
        if self.vroot is not None:
            self.vroot = None; return []
