    # sorters
    def _msg_AddNodeSorter(self, v):
        sorters = self.explorer_config["sorters"]
        rev = v.get("reverse") if v.get("reverse") is not None else False
        for s in sorters:
            if s["sorter"] == v["sorter"]: s["reverse"] = rev; return []
        sorters.append({"sorter": v["sorter"], "reverse": rev}); return []
    def _msg_RemoveNodeSorter(self, v):
        self.explorer_config["sorters"] = [s for s in self.explorer_config["sorters"] if s["sorter"] != v]; return []
    def _msg_ReverseNodeSorter(self, v):
        for s in self.explorer_config["sorters"]:
            if s["sorter"] == v: s["reverse"] = not s["reverse"]
        return []
    def _msg_ToggleNodeSorter(self, v):
        sorters = self.explorer_config["sorters"]
        for s in list(sorters):
            if s["sorter"] == v["sorter"]: sorters.remove(s); return []
        sorters.append({"sorter": v["sorter"], "reverse": v.get("reverse") or False}); return []
    def _msg_ReverseNodeSorters(self, v):
        for s in self.explorer_config["sorters"]: s["reverse"] = not s["reverse"]
