    # commands & lua are implemented in runner/app_ext below
    def _msg_Call(self, v): return self._exec_command(v, "\n", False)
    def _msg_Call0(self, v): return self._exec_command(v, "\0", False)
    def _msg_CallSilently(self, v): return self._exec_command(v, "\n", True)
    def _msg_CallSilently0(self, v): return self._exec_command(v, "\0", True)
    def _msg_BashExec(self, v): return self._exec_command({"command": "bash", "args": ["-c", v]}, "\n", False)
    def _msg_BashExec0(self, v): return self._exec_command({"command": "bash", "args": ["-c", v]}, "\0", False)
    def _msg_BashExecSilently(self, v): return self._exec_command({"command": "bash", "args": ["-c", v]}, "\n", True)
    def _msg_BashExecSilently0(self, v): return self._exec_command({"command": "bash", "args": ["-c", v]}, "\0", True)

    def _read_only(self):
        return bool(self.cli.get("read_only") or self.config["general"].get("read_only"))

    def _exec_command(self, cmd, delimiter, silent):
        if self._read_only():
            self.log_error("could not execute code in read-only mode."); return []
        self.write_pipes(delimiter)
        env = self._command_env()
        command = cmd.get("command"); args = cmd.get("args") or []
        runner = self.runner
        try:
            if runner is not None and not silent:
                rc, spawn_err = runner.run_interactive([command] + list(args), env)
            elif runner is not None and silent:
                rc, spawn_err = runner.run_silent([command] + list(args), env)
            else:
                if silent:
                    p = subprocess.run([command] + list(args), env=env, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                else:
                    p = subprocess.run([command] + list(args), env=env)
                rc, spawn_err = p.returncode, None
        except OSError as e:
            rc, spawn_err = None, e
        if spawn_err is not None:
            self.log_error(f"{os.strerror(spawn_err.errno)} (os error {spawn_err.errno})")
            return []
        if rc is not None and rc != 0:
            if rc < 0:
                import signal as _sig
                try: signame = _sig.Signals(-rc).name
                except Exception: signame = str(-rc)
                self.log_error(f"process exited with code signal: {-rc} ({signame})")
            else:
                self.log_error(f"process exited with code exit status: {rc}")
        return self._read_pipe_messages(delimiter)

    def _command_env(self):
        env = dict(os.environ)
        focused = self.focused_node()
        env.update({
            "XPLR": self.bin, "XPLR_APP_VERSION": VERSION,
            "XPLR_FOCUS_INDEX": str(self.directory_buffer["focus"] if self.directory_buffer["total"] else 0),
            "XPLR_FOCUS_PATH": focused.absolute_path if focused else "",
            "XPLR_INITIAL_PWD": self.initial_pwd,
            "XPLR_INPUT_BUFFER": self.input_buffer["value"] if self.input_buffer else "",
            "XPLR_MODE": self.mode.get("name", ""),
            "XPLR_PID": str(self.pid), "XPLR_SESSION_PATH": self.session_path,
            "XPLR_VROOT": self.vroot or "",
            "XPLR_PIPE_MSG_IN": self.pipe["msg_in"], "XPLR_PIPE_SELECTION_OUT": self.pipe["selection_out"],
            "XPLR_PIPE_RESULT_OUT": self.pipe["result_out"], "XPLR_PIPE_DIRECTORY_NODES_OUT": self.pipe["directory_nodes_out"],
            "XPLR_PIPE_GLOBAL_HELP_MENU_OUT": self.pipe["global_help_menu_out"], "XPLR_PIPE_LOGS_OUT": self.pipe["logs_out"],
            "XPLR_PIPE_HISTORY_OUT": self.pipe["history_out"],
            "PWD": self.pwd,
        })
        return env

    def _read_pipe_messages(self, delimiter):
        path = self.pipe["msg_in"]
        try: data = open(path, "rb").read()
        except OSError: return []
        if not data: return []
        text = data.decode("utf-8", "surrogateescape")
        parts = text.split(delimiter)
        injected = []
        for part in parts:
            if part == "": continue
            try:
                m = parse_message_lenient(part)
            except Exception as e:
                # log the error and stop processing further messages
                self.log_error(_msg_error_text(e))
                break
            injected.append(m)
        return injected

    def _msg_CallLua(self, v): return self._call_lua_msg(v, silent=False)
    def _msg_CallLuaSilently(self, v): return self._call_lua_msg(v, silent=True)
    def _msg_LuaEval(self, v): return self._lua_eval_msg(v, silent=False)
    def _msg_LuaEvalSilently(self, v): return self._lua_eval_msg(v, silent=True)

    def _call_lua_msg(self, path, silent):
        if self._read_only():
            self.log_error("could not execute code in read-only mode."); return []
        runner = self.runner
        if runner is not None and not silent: runner.suspend()
        try:
            fn = self.resolve_lua_function(path)
            if fn is None or not _is_callable(self.lua, fn):
                self.log_error("Nil is not a function"); return []
            ctx = self.app_context_lua(full=True)
            try:
                vals = self.lua.call_multi(fn, [ctx])
            except (LuaError, LuaSyntaxError) as e:
                self.log_error(self.lua_error_text(e)); return []
            return self._messages_from_lua_result(vals)
        finally:
            if runner is not None and not silent: runner.resume()

    def _lua_eval_msg(self, code, silent):
        if self._read_only():
            self.log_error("could not execute code in read-only mode."); return []
        runner = self.runner
        if runner is not None and not silent: runner.suspend()
        try:
            from luamod import Parser, LuaSyntaxError as _LSE, exec_block, Scope, Cell, Frame, MultiReturn, LuaReturn
            try:
                body = Parser(code, "src/runner.rs:660").parse_chunk()
            except LuaSyntaxError as e:
                self.log_error("syntax error: " + e.text); return []
            scope = Scope(None); scope.vars["..."] = Cell(MultiReturn(()))
            frame = Frame("src/runner.rs:660", 1, True)
            self.lua.frames.append(frame)
            vals = ()
            try:
                exec_block(self.lua, body, scope, frame)
            except LuaReturn as ret:
                vals = ret.values
            except (LuaError, LuaSyntaxError) as e:
                self.lua.frames.pop(); self.log_error(self.lua_error_text(e)); return []
            self.lua.frames.pop()
            if vals and isinstance(vals[0], (LuaFunction, NativeFunction)):
                ctx = self.app_context_lua(full=True)
                try: vals = self.lua.call_multi(vals[0], [ctx])
                except (LuaError, LuaSyntaxError) as e:
                    self.log_error(self.lua_error_text(e)); return []
            return self._messages_from_lua_result(vals, allow_no_value=True)
        finally:
            if runner is not None and not silent: runner.resume()

    def _messages_from_lua_result(self, vals, allow_no_value=False):
        if not vals: return []
        v = vals[0]
        if v is None: return []
        if isinstance(v, LuaTable):
            try:
                return configconv.messages_from_lua_list(v)
            except configconv.ConfigError as e:
                self.log_error(str(e)); return []
        self.log_error(f"deserialize error: invalid type: {_lua_type_desc(v)}, expected table")
        return []

# -------------- module-level helpers --------------
def _dir_entry(p):
    return p + "/" if p != "/" else "/"

def _is_within(path, root):
    if root is None: return True
    path = normalize_abs(path); root = normalize_abs(root)
    return path == root or path.startswith(root + "/") if root != "/" else True

def re_fullmatch_usize(s):
    import re as _re
    return _re.fullmatch(r"\+?[0-9]+", s) is not None and int(s) <= 18446744073709551615

def _is_callable(state, fn):
    from luamod import LuaFunction, NativeFunction
    if isinstance(fn, (LuaFunction, NativeFunction)): return True
    mt = fn.metatable if hasattr(fn, "metatable") else None
    return isinstance(mt, LuaTable) and mt.rawget("__call") is not None

def _lua_type_desc(v):
    from luamod import lua_type
    if v is None: return "unit value"
    if isinstance(v, bool): return f"boolean `{str(v).lower()}`"
    if isinstance(v, int): return f"integer `{v}`"
    if isinstance(v, float): return f"floating point `{v}`"
    if isinstance(v, str): return f'string "{v}"'
    if isinstance(v, LuaTable): return "map"
    return lua_type(v)

def _mode_for_state(mode):
    # on_key sorted by key name for state output
    m = copy.deepcopy(mode)
    try:
        kb = m.get("key_bindings") or {}
        on_key = kb.get("on_key") or {}
        kb["on_key"] = {k: on_key[k] for k in sorted(on_key.keys())}
        m["key_bindings"] = kb
    except Exception: pass
    return m

def _word_starts(s):
    starts = []
    for i, ch in enumerate(s):
        if ch.isalnum() and (i == 0 or not s[i-1].isalnum()): starts.append(i)
    return starts

def _prev_word_pos(s, cursor):
    starts = [w for w in _word_starts(s) if w < cursor]
    return starts[-1] if starts else 0

def _next_word_pos(s, cursor):
    starts = [w for w in _word_starts(s) if w > cursor]
    return starts[0] if starts else len(s)

def _apply_input_op(app, b, op):
    val = b["value"]; cur = b["cursor"]
    chars_len = len(val)
    cur = max(0, min(cur, chars_len))
    def setval(newval, newcur):
        b["value"] = newval; b["cursor"] = max(0, min(newcur, len(newval)))
    if isinstance(op, str):
        if op == "GoToPreviousCharacter": b["cursor"] = max(0, cur - 1)
        elif op == "GoToNextCharacter": b["cursor"] = min(chars_len, cur + 1)
        elif op == "GoToPreviousWord": b["cursor"] = _prev_word_pos(val, cur)
        elif op == "GoToNextWord": b["cursor"] = _next_word_pos(val, cur)
        elif op == "GoToStart": b["cursor"] = 0
        elif op == "GoToEnd": b["cursor"] = chars_len
        elif op == "DeletePreviousCharacter":
            if cur > 0: setval(val[:cur-1] + val[cur:], cur - 1)
        elif op == "DeleteNextCharacter":
            if cur < chars_len: setval(val[:cur] + val[cur+1:], cur)
        elif op == "DeletePreviousWord":
            t = _prev_word_pos(val, cur); setval(val[:t] + val[cur:], t)
        elif op == "DeleteNextWord":
            t = _next_word_pos(val, cur); setval(val[:cur] + val[t:], cur)
        elif op == "DeleteLine": setval("", 0)
        elif op == "DeleteTillEnd": setval(val[:cur], cur)
        return
    if isinstance(op, dict):
        if "SetCursor" in op: b["cursor"] = max(0, min(op["SetCursor"], chars_len))
        elif "InsertCharacter" in op:
            ch = op["InsertCharacter"]; setval(val[:cur] + ch + val[cur:], cur + len(ch))

def _input_op_from_key(key):
    if key is None: return None
    code = key.get("code"); ch = key.get("char"); mods = key.get("modifiers") or set()
    if code == "backspace": return "DeletePreviousCharacter"
    if code == "delete": return "DeleteNextCharacter"
    if code == "left": return "GoToPreviousWord" if "ctrl" in mods else "GoToPreviousCharacter"
    if code == "right": return "GoToNextWord" if "ctrl" in mods else "GoToNextCharacter"
    if code == "home": return "GoToStart"
    if code == "end": return "GoToEnd"
    if code == "char" and ch is not None:
        if "ctrl" in mods:
            m = {"a": "GoToStart", "b": "GoToPreviousCharacter", "e": "GoToEnd", "f": "GoToNextCharacter", "u": "DeleteLine", "w": "DeletePreviousWord", "k": "DeleteTillEnd"}
            return m.get(ch.lower())
        if "alt" in mods: return None
        return {"InsertCharacter": ch}
    return None

def _char_from_key(key):
    if key is None: return None
    # BufferInputFromKey buffers the character for character keys
    if key.get("code") == "char":
        mods = key.get("modifiers") or set()
        if "ctrl" in mods or "alt" in mods: return None
        return key.get("char")
    if key.get("code") == "space": return " "
    return None

def _try_complete_path(app):
    if app.input_buffer is None: return
    text = app.input_buffer["value"]
    if text == "": return
    pwd = app.pwd
    # trailing slash to a non-directory keeps text
    resolved = absolutize(text, pwd)
    is_dir_path = os.path.isdir(resolved)
    if text.endswith("/") and not is_dir_path and text != "/":
        return
    completion = None; completion_is_dir = False
    if os.path.exists(resolved) and not text.endswith("/"):
        completion = resolved; completion_is_dir = is_dir_path
    else:
        if text.endswith("/") and text != "/":
            dir_part = text.rstrip("/")
            dir_abs = absolutize(dir_part, pwd) if dir_part else "/"
            prefix = ""
        elif "/" in text:
            idx = text.rfind("/")
            dir_part = text[:idx] or "/"
            prefix = text[idx+1:]
            dir_abs = absolutize(dir_part, pwd)
        else:
            dir_abs = pwd; prefix = text
        if not os.path.isdir(dir_abs): return
        try: names = os.listdir(dir_abs)
        except OSError: return
        matches = [n for n in names if n.startswith(prefix)]
        if not matches: return
        if len(matches) == 1:
            completion = path_join(dir_abs, matches[0]); completion_is_dir = os.path.isdir(completion)
        else:
            import os.path as _op
            common = _op.commonprefix(matches)
            if len(common) <= len(prefix) and not (prefix == "" and text.endswith("/")):
                completion = dir_abs; completion_is_dir = True
            else:
                completion = path_join(dir_abs, common) if common else dir_abs
                completion_is_dir = os.path.isdir(completion) and common == ""
    if completion is None: return
    if completion == "/":
        result = "/"
    else:
        from xplrutil import relative_to as _rt
        # build a lua options table
        opts = LuaTable(); opts.rawset("with_prefix_dots", True); opts.rawset("without_suffix_dots", True)
        try: result = _rt(app.lua, completion, opts)
        except Exception: result = completion
        if completion_is_dir: result = result.rstrip("/") + "/"
    app.input_buffer = {"value": result, "cursor": len(result)}

def _msg_error_text(e):
    if isinstance(e, MessageError): return str(e)
    try: return e.display()
    except Exception: return str(e)

# help rows computation used by App and global help
def help_rows_for(config, mode):
    gen_kb = config["general"].get("global_key_bindings") or {}
    kb = mode.get("key_bindings") or {}
    # merged on_key: global first, mode overrides
    merged = {}
    for k, v in (gen_kb.get("on_key") or {}).items(): merged[k] = v
    for k, v in (kb.get("on_key") or {}).items(): merged[k] = v
    # group identical actions
    groups = []  # list of [primary_key, [remaps], action]
    by_sig = {}
    def sig(action):
        return (action.get("help"), tuple(_msg_sig(m) for m in (action.get("messages") or [])))
    for key in sorted(merged.keys()):
        action = merged[key]
        if action is None: continue
        help_text = action.get("help")
        if help_text is None: continue
        s = sig(action)
        if s in by_sig:
            groups[by_sig[s]][1].append(key)
        else:
            by_sig[s] = len(groups); groups.append([key, [], help_text, action])
    rows = []
    hide_remaps = config["general"].get("hide_remaps_in_help_menu")
    if mode.get("help") is not None:
        return [(mode["help"], [], "")]
    if mode.get("extra_help") is not None:
        rows.append((mode["extra_help"], [], ""))
    for primary, remaps, help_text, action in groups:
        rows.append((primary, [] if hide_remaps else remaps, help_text))
    # category handlers
    cats = [("on_alphabet", "[a-Z]"), ("on_number", "[0-9]"), ("on_alphanumeric", "[0-Z]"), ("on_special_character", "[^0-Z]"), ("on_character", "[*]"), ("on_navigation", "[nav]"), ("on_function", "[f1-f12]"), ("default", "[default]")]
    for field, label in cats:
        action = kb.get(field)
        if action is None: action = gen_kb.get(field)
        if action is not None and action.get("help") is not None:
            rows.append((label, [], action["help"]))
    return rows

def _msg_sig(m):
    v = plain_value(m)
    import json as _json
    return _json.dumps(v, sort_keys=True, ensure_ascii=False, default=str)

def _renderer_arg_to_lua(state, arg):
    # style field needs to be a lua style table (only set fields)
    from luaconvert import lua_style_to_table
    t = LuaTable()
    for k, v in arg.items():
