import os, re, sys, copy
from coreutil import StyleEff, DEFAULT_STYLE, apply_style, parse_ansi, text_width, char_width, truncate_spans, Span, spans_width
from nodes import resolve_node_type

BORDER_CHARS = {
    "Plain": ("┌", "┐", "└", "┘", "─", "│"),
    "Rounded": ("╭", "╮", "╰", "╯", "─", "│"),
    "Double": ("╔", "╗", "╚", "╝", "═", "║"),
    "Thick": ("┏", "┓", "┗", "┛", "━", "┃"),
}

class Rect:
    __slots__ = ("x", "y", "w", "h")
    def __init__(self, x, y, w, h): self.x, self.y, self.w, self.h = x, y, max(0, w), max(0, h)
    def __repr__(self): return f"Rect({self.x},{self.y},{self.w},{self.h})"

class Canvas:
    def __init__(self, w, h):
        self.w = w; self.h = h
        self.cells = [[[" ", DEFAULT_STYLE, 1] for _ in range(w)] for _ in range(h)]
    def set(self, x, y, ch, style):
        if not (0 <= x < self.w and 0 <= y < self.h): return
        wdt = char_width(ch)
        if wdt == 0:
            # attach/combining: append to previous cell if possible
            if x > 0:
                prev = self.cells[y][x-1]
                prev[0] = prev[0] + ch
            return
        self.cells[y][x] = [ch, style, wdt]
        if wdt == 2 and x + 1 < self.w:
            self.cells[y][x+1] = ["", style, 0]
        # clear a previous wide char's continuation if overwritten
    def fill(self, rect, style):
        for y in range(rect.y, min(self.h, rect.y + rect.h)):
            for x in range(rect.x, min(self.w, rect.x + rect.w)):
                self.cells[y][x] = [" ", style, 1]
    def draw_spans(self, x, y, spans, max_width):
        if max_width <= 0: return
        clipped = truncate_spans(spans, max_width)
        curx = x
        for sp in clipped:
            for ch in sp.text:
                if ch == "\t":
                    nxt = ((curx // 8) + 1) * 8
                    while curx < nxt and curx < x + max_width:
                        self.set(curx, y, " ", sp.style); curx += 1
                    continue
                if ch in ("\n", "\r"): continue
                wdt = char_width(ch)
                if wdt == 0:
                    self.set(curx - 1 if curx > x else curx, y, ch, sp.style) if False else self._combining(curx, y, ch, sp.style)
                    continue
                if curx >= x + max_width: break
                self.set(curx, y, ch, sp.style); curx += wdt
    def _combining(self, curx, y, ch, style):
        if curx > 0 and 0 <= y < self.h:
            cell = self.cells[y][curx-1]
            cell[0] = cell[0] + ch
    def draw_text(self, x, y, text, style, max_width):
        self.draw_spans(x, y, [Span(text, style)], max_width)

# ---------------- layout splitting ----------------
def _constraint_value(constraint, total, rect, screen):
    key = list(constraint.keys())[0]; val = constraint[key]
    screen_w, screen_h = screen
    if key == "Percentage": return ("pct", total * val / 100.0)
    if key == "Ratio":
        den = val[1] if len(val) > 1 and val[1] else 1
        return ("pct", total * val[0] / float(den))
    # length-ish variants
    v = float(val)
    less_refs = {
        "LessThanScreenHeight": screen_h, "LessThanScreenWidth": screen_w,
        "LessThanLayoutHeight": rect.h, "LessThanLayoutWidth": rect.w,
    }
    for suffix, ref in less_refs.items():
        if key.endswith(suffix): v = min(v, float(ref))
    if key.startswith("Length"): return ("fixed", v)
    if key.startswith("Max"): return ("max", v)
    if key.startswith("Min"): return ("min", v)
    return ("pct", v)

def split_sizes(total, rect, screen, constraints, count):
    if count <= 0: return []
    if not constraints:
        return [0] * count
    specs = []
    for i in range(count):
        if i < len(constraints): specs.append(_constraint_value(constraints[i], total, rect, screen))
        else: specs.append(("zero", 0.0))
    sizes = [v for _, v in specs]
    ssum = sum(sizes)
    if ssum < total:
        extra = total - ssum
        weights = []
        for idx, (kind, v) in enumerate(specs):
            weights.append(v if kind in ("pct", "min") and v > 0 else (1.0 if kind in ("pct", "min") else 0.0))
        wsum = sum(weights)
        if wsum > 0:
            for i in range(count):
                sizes[i] += extra * weights[i] / wsum
    elif ssum > total:
        excess = ssum - total
        # shrink pct/min/max first proportionally
        flex = [i for i, (k, v) in enumerate(specs) if k in ("pct", "min", "max")]
        fsum = sum(sizes[i] for i in flex)
        if fsum > 0:
            cut = min(excess, fsum)
            for i in flex: sizes[i] -= cut * sizes[i] / fsum
            excess -= cut
        if excess > 0:
            allsum = sum(sizes)
            if allsum > 0:
                for i in range(count): sizes[i] = max(0.0, sizes[i] - excess * sizes[i] / allsum)
    # cumulative rounding to integers
    result = []
    pos = 0.0; prev_int = 0
    for i in range(count):
        pos += sizes[i]
        cur_int = int(pos + 0.5)
        result.append(max(0, cur_int - prev_int)); prev_int = cur_int
    return result

def table_column_starts(total, constraints, spacing):
    """Column start offsets & widths using the observed table allocation:
    desired widths are % of total, the largest column absorbs the spacing."""
    if not constraints: return [], []
    desired = []
    for c in constraints:
        key = list(c.keys())[0]; val = c[key]
        if key == "Percentage": desired.append(total * val / 100.0)
        elif key == "Ratio": desired.append(total * val[0] / float(val[1] or 1))
        else:
            # Length/Min/Max: use the raw value
            desired.append(float(val))
    if desired:
        total_spacing = spacing * (len(constraints) - 1)
        # choose the largest column (first max)
        mi = max(range(len(desired)), key=lambda i: desired[i])
        desired[mi] = max(0.0, desired[mi] - total_spacing)
    starts = []
    cum = 0.0
    for i, d in enumerate(desired):
        starts.append(int(cum + i * spacing + 0.5))
        cum += d
    widths = []
    for i in range(len(desired)):
        if i + 1 < len(starts): widths.append(max(0, starts[i+1] - starts[i] - spacing))
        else: widths.append(max(0, total - starts[i]))
    return starts, widths

# ---------------- panel UI resolution ----------------
def _style_dict_patch(base, over):
    from nodes import _style_patch
    if base is None and over is None: return {"fg": None, "bg": None, "add_modifiers": None, "sub_modifiers": None}
    return _style_patch(base or {"fg": None, "bg": None, "add_modifiers": None, "sub_modifiers": None}, over or {"fg": None, "bg": None, "add_modifiers": None, "sub_modifiers": None})

def resolve_panel_ui(app, specific=None):
    panel_cfg = app.config["general"].get("panel_ui") or {}
    default = panel_cfg.get("default") or {}
    spec = specific or {}
    def get(ui, field):
        return ui.get(field) if isinstance(ui, dict) else None
    d_title = default.get("title") or {}; s_title = spec.get("title") or {}
    title_format = s_title.get("format") if s_title.get("format") is not None else d_title.get("format")
    title_style = _style_dict_patch(d_title.get("style"), s_title.get("style"))
    style = _style_dict_patch(default.get("style"), spec.get("style"))
    borders = spec.get("borders") if spec.get("borders") is not None else default.get("borders")
    border_type = spec.get("border_type") if spec.get("border_type") is not None else default.get("border_type")
    border_style = _style_dict_patch(default.get("border_style"), spec.get("border_style"))
    return {"title_format": title_format, "title_style": title_style, "style": style, "borders": borders if borders is not None else ["Top", "Right", "Bottom", "Left"], "border_type": border_type or "Rounded", "border_style": border_style}

def panel_ui_for(app, key):
    panel_cfg = app.config["general"].get("panel_ui") or {}
    return resolve_panel_ui(app, panel_cfg.get(key) if key else None)

# ---------------- rendering ----------------
class Renderer:
    def __init__(self, app, width, height):
        self.app = app; self.w = width; self.h = height
        self.canvas = Canvas(width, height)
        self.cursor = None
    def render(self):
        layout = self.app.mode.get("layout")
        if layout is None: layout = self.app.layout
        self.render_layout(layout, Rect(0, 0, self.w, self.h), depth=0)
        return self.canvas

    def render_layout(self, layout, rect, depth=0):
        if depth > 60: return
        if layout is None or rect.w <= 0 or rect.h <= 0: return
        if isinstance(layout, str):
            self.render_builtin_panel(layout, rect); return
        if isinstance(layout, dict) and len(layout) == 1:
            key = list(layout.keys())[0]; val = layout[key]
            if key in ("Horizontal", "Vertical"):
                self.render_split(key, val, rect, depth); return
            if key == "Static":
                self.render_custom_panel(val, rect); return
            if key == "Dynamic":
                self.render_dynamic(val, rect, depth); return
            if key == "CustomContent":
                self.render_custom_panel(val, rect); return
        # unknown layout: nothing

    def render_split(self, kind, val, rect, depth):
        cfg = val.get("config") or {}
        margin = cfg.get("margin"); hm = cfg.get("horizontal_margin"); vm = cfg.get("vertical_margin")
        hm = hm if hm is not None else (margin or 0); vm = vm if vm is not None else (margin or 0)
        inner = Rect(rect.x + (hm or 0), rect.y + (vm or 0), rect.w - 2 * (hm or 0), rect.h - 2 * (vm or 0))
        splits = val.get("splits") or []
        cons = cfg.get("constraints")
        if kind == "Horizontal":
            sizes = split_sizes(inner.w, inner, (self.w, self.h), cons, len(splits))
            x = inner.x
            for sub, sz in zip(splits, sizes):
                self.render_layout(sub, Rect(x, inner.y, sz, inner.h), depth + 1); x += sz
        else:
            sizes = split_sizes(inner.h, inner, (self.w, self.h), cons, len(splits))
            y = inner.y
            for sub, sz in zip(splits, sizes):
                self.render_layout(sub, Rect(inner.x, y, inner.w, sz), depth + 1); y += sz

    # ---- block ----
    def draw_block(self, rect, ui, title):
        app = self.app
        base = apply_style(DEFAULT_STYLE, ui["style"])
        self.canvas.fill(rect, base)
        borders = ui["borders"] or []
        has_top = "Top" in borders; has_bottom = "Bottom" in borders; has_left = "Left" in borders; has_right = "Right" in borders
        border_eff = apply_style(base, ui["border_style"])
        tl, tr, bl, br, hz, vt = BORDER_CHARS.get(ui["border_type"], BORDER_CHARS["Rounded"])
        C = self.canvas.set
        if has_top:
            for x in range(rect.x, rect.x + rect.w): C(x, rect.y, hz, border_eff)
            if has_left: C(rect.x, rect.y, tl, border_eff)
            if has_right and rect.w > 1: C(rect.x + rect.w - 1, rect.y, tr, border_eff)
        if has_bottom and rect.h > 1:
            y = rect.y + rect.h - 1
            for x in range(rect.x, rect.x + rect.w): C(x, y, hz, border_eff)
            if has_left: C(rect.x, y, bl, border_eff)
            if has_right and rect.w > 1: C(rect.x + rect.w - 1, y, br, border_eff)
        if has_left:
            for y in range(rect.y, rect.y + rect.h): C(rect.x, y, vt, border_eff)
        if has_right and rect.w > 1:
            for y in range(rect.y, rect.y + rect.h): C(rect.x + rect.w - 1, y, vt, border_eff)
        if title is not None and has_top:
            title_style = apply_style(base, ui["title_style"])
            maxw = rect.w - (2 if has_right else 1)
            if maxw > 0:
                self.canvas.draw_text(rect.x + 1, rect.y, title, title_style, maxw)
        ix = rect.x + (1 if has_left else 0); iy = rect.y + (1 if has_top else 0)
        iw = rect.w - (1 if has_left else 0) - (1 if has_right else 0)
        ih = rect.h - (1 if has_top else 0) - (1 if has_bottom else 0)
        return Rect(ix, iy, max(0, iw), max(0, ih)), base

    def render_builtin_panel(self, name, rect):
        app = self.app
        keymap = {"Table": "table", "Selection": "selection", "HelpMenu": "help_menu", "SortAndFilter": "sort_and_filter", "InputAndLogs": "input_and_logs"}
        ui = panel_ui_for(app, keymap.get(name))
        title = self._panel_title(name, ui)
        inner, base = self.draw_block(rect, ui, title)
        if inner.w <= 0 or inner.h <= 0: return
        if name == "Nothing": return
        if name == "Table": self.render_table(inner, base)
        elif name == "Selection": self.render_selection(inner, base)
        elif name == "HelpMenu": self.render_help(inner, base)
        elif name == "SortAndFilter": self.render_sort_filter(inner, base)
        elif name == "InputAndLogs": self.render_input_logs(inner, base, rect)

    def _panel_title(self, name, ui):
        app = self.app
        if ui["title_format"] is not None: return ui["title_format"]
        gen = app.config["general"]
        if name == "Table":
            total = app.directory_buffer["total"]
            if app.vroot:
                rel = app.pwd[len(app.vroot):] if app.pwd.startswith(app.vroot) else app.pwd
                if rel == "": rel = "/"
                elif not rel.startswith("/"): rel = "/" + rel
                body = f"vroot:{rel}"
            else:
                body = app.pwd
            return f" {body} ({total}) " if total else f" {body} "
        if name == "SortAndFilter":
            count = len(app.explorer_config["filters"]) + len(app.explorer_config["sorters"])
            return f" Sort & filter ({count}) " if count else " Sort & filter "
        if name == "Selection":
            count = len(app.selection)
            return f" Selection ({count}) " if count else " Selection "
        if name == "HelpMenu":
            return f" Help [{app.mode.get('name', '')}] "
        if name == "InputAndLogs":
            sel = f" {{{len(app.selection)} sel}}" if app.selection else ""
            if app.input_buffer is not None:
                return f" Input [{app.mode.get('name', '')}]{sel} "
            count = len(app.logs)
            return f" Logs ({count}) [{app.mode.get('name', '')}]{sel} " if count else f" Logs [{app.mode.get('name', '')}]{sel} "
        return None

    # ---- table ----
    def render_table(self, inner, base):
        app = self.app
        gen = app.config["general"]; table = gen.get("table") or {}
        header = table.get("header") or {}; row_cfg = table.get("row") or {}
        header_cols = header.get("cols") or []
        header_height = header.get("height") if header.get("height") is not None else 1
        if not header_cols: header_height = 0
        header_style = apply_style(apply_style(base, table.get("style")), header.get("style"))
        col_widths_cfg = table.get("col_widths")
        row_cols = row_cfg.get("cols") or []
        ncols = max(len(header_cols), len(row_cols))
        if col_widths_cfg:
            starts, widths = table_column_starts(inner.w, col_widths_cfg, table.get("col_spacing") or 1)
        else:
            # fallback: equal columns
            starts = [i * (inner.w // max(1, ncols)) for i in range(ncols)]; widths = [inner.w // max(1, ncols)] * ncols
        spacing = table.get("col_spacing") or 1
        if header_cols and header_height > 0:
            for ci, col in enumerate(header_cols):
                if ci >= len(starts): break
                style = apply_style(header_style, col.get("style"))
                fmt = col.get("format") or ""
                self.canvas.draw_spans(inner.x + starts[ci], inner.y, parse_ansi(fmt, style), widths[ci])
        rows_area = max(0, inner.h - header_height)
        nodes = app.directory_buffer["nodes"]; total = len(nodes)
        focus = app.directory_buffer["focus"]
        offset = self._table_offset(rows_area, total, focus)
        row_base = apply_style(base, table.get("style"))
        for vi in range(rows_area):
            idx = offset + vi
            if idx >= total: break
            node = nodes[idx]
            y = inner.y + header_height + vi
            arg = None
            for ci, col in enumerate(row_cols):
                if ci >= len(starts): break
                if arg is None: arg = app.node_renderer_arg(node, idx)
                fmt_name = col.get("format")
                style = apply_style(apply_style(row_base, row_cfg.get("style")), col.get("style"))
                text = app.call_renderer(fmt_name, arg) if fmt_name else ""
                spans = parse_ansi(text, style)
                self.canvas.draw_spans(inner.x + starts[ci], y, spans, widths[ci])

    def _table_offset(self, rows_area, total, focus):
        app = self.app
        if rows_area <= 0 or total == 0:
            app.table_scroll = 0; return 0
        gen = app.config["general"]
        if gen.get("paginated_scrolling"):
            off = (focus // rows_area) * rows_area
            app.table_scroll = off; return off
        off = app.table_scroll
        pad = gen.get("scroll_padding") or 0
        if total <= rows_area:
            off = 0
        else:
            if pad > 0:
                min_off = focus - (rows_area - pad)
                max_off = focus - (pad - 1)
                if off < min_off: off = min_off
                if off > max_off: off = max_off
            else:
                if focus < off: off = focus
                if focus >= off + rows_area: off = focus - rows_area + 1
            off = max(0, min(off, total - rows_area))
        app.table_scroll = off
        return off

    # ---- selection ----
    def render_selection(self, inner, base):
        app = self.app
        item_cfg = (app.config["general"].get("selection") or {}).get("item") or {}
        fmt_name = item_cfg.get("format")
        style = apply_style(base, item_cfg.get("style"))
        nodes = list(app.selection.values())
        if len(nodes) > inner.h:
            nodes = nodes[len(nodes) - inner.h:]
        for i, node in enumerate(nodes):
            arg = node.to_dict()
            text = app.call_renderer(fmt_name, arg) if fmt_name else node.absolute_path
            self.canvas.draw_spans(inner.x, inner.y + i, parse_ansi(text, style), inner.w)

    # ---- help ----
    def render_help(self, inner, base):
        from app import help_rows_for
        app = self.app
        rows = help_rows_for(app.config, app.mode)
        starts, widths = table_column_starts(inner.w, [{"Percentage": 20}, {"Percentage": 20}, {"Percentage": 60}], 1)
        for i, (key, remaps, help_text) in enumerate(rows):
            if i >= inner.h: break
            y = inner.y + i
            self.canvas.draw_spans(inner.x + starts[0], y, [Span(key, base)], widths[0])
            self.canvas.draw_spans(inner.x + starts[1], y, [Span(", ".join(remaps), base)], widths[1])
            self.canvas.draw_spans(inner.x + starts[2], y, [Span(help_text, base)], widths[2])

    # ---- sort & filter ----
    def render_sort_filter(self, inner, base):
        app = self.app
        sf = app.config["general"].get("sort_and_filter_ui") or {}
        spans = []
        items = []
        for f in app.explorer_config["filters"]:
