            x += 1
        if cur_text: runs.append((cur_text, cur_style))
        row_out = []
        for text, style in runs:
            codes = style_to_sgr(style) if style else []
            row_out.append("\x1b[0m" + ("\x1b[" + ";".join(codes) + "m" if codes else "") + text)
        out.append("".join(row_out))
