    "Rounded": ("╭", "╮", "╰", "╯", "─", "│"),
    "Double": ("╔", "╗", "╚", "╝", "═", "║"),
    "Thick": ("┏", "┓", "┗", "┛", "━", "┃"),
}

class Rect:
    __slots__ = ("x", "y", "w", "h")
    def __init__(self, x, y, w, h): self.x, self.y, self.w, self.h = x, y, max(0, w), max(0, h)
    def __repr__(self): return f"Rect({self.x},{self.y},{self.w},{self.h})"

class Canvas:
    def __init__(self, w, h):
        self.w = w; self.h = h
        self.cells = [[[" ", DEFAULT_STYLE, 1] for _ in range(w)] for _ in range(h)]
    def set(self, x, y, ch, style):
        if not (0 <= x < self.w and 0 <= y < self.h): return
        wdt = char_width(ch)
        if wdt == 0:
            # attach/combining: append to previous cell if possible
            if x > 0:
                prev = self.cells[y][x-1]
                prev[0] = prev[0] + ch
            return
        self.cells[y][x] = [ch, style, wdt]
        if wdt == 2 and x + 1 < self.w:
            self.cells[y][x+1] = ["", style, 0]
        # clear a previous wide char's continuation if overwritten
    def fill(self, rect, style):
        for y in range(rect.y, min(self.h, rect.y + rect.h)):
            for x in range(rect.x, min(self.w, rect.x + rect.w)):
                self.cells[y][x] = [" ", style, 1]
    def draw_spans(self, x, y, spans, max_width):
        if max_width <= 0: return
        clipped = truncate_spans(spans, max_width)
        curx = x
        for sp in clipped:
            for ch in sp.text:
                if ch == "\t":
                    nxt = ((curx // 8) + 1) * 8
                    while curx < nxt and curx < x + max_width:
                        self.set(curx, y, " ", sp.style); curx += 1
                    continue
                if ch in ("\n", "\r"): continue
                wdt = char_width(ch)
                if wdt == 0:
                    self.set(curx - 1 if curx > x else curx, y, ch, sp.style) if False else self._combining(curx, y, ch, sp.style)
                    continue
                if curx >= x + max_width: break
                self.set(curx, y, ch, sp.style); curx += wdt
    def _combining(self, curx, y, ch, style):
        if curx > 0 and 0 <= y < self.h:
            cell = self.cells[y][curx-1]
            cell[0] = cell[0] + ch
    def draw_text(self, x, y, text, style, max_width):
