                    ev = self._csi_event(params_str, final)
                    if ev is not None: events.append(ev)
                    i = j + 1; continue
                if nb == ord('O'):
                    if i + 2 >= len(buf): incomplete = True; break
                    c = chr(buf[i+2])
                    mp = {"P": "f1", "Q": "f2", "R": "f3", "S": "f4", "A": "up", "B": "down", "C": "right", "D": "left", "H": "home", "F": "end"}
                    if c in mp: events.append(make_key_event(mp[c]))
                    i += 3; continue
                # Alt + char (decode one utf8 char)
                ch, consumed = _decode_one(buf[i+1:])
                if ch is None:
                    incomplete = True; break
                if ch == "\x1b":
                    events.append(make_key_event("esc")); i += 1; continue
                events.append(make_key_event("char", ch, {"alt"}))
                i += 1 + consumed; continue
            if b in (13, 10):
                events.append(make_key_event("enter"))
                # consume \r\n pair as one
                if b == 13 and i + 1 < len(buf) and buf[i+1] == 10: i += 1
                i += 1; continue
            if b == 9:
                events.append(make_key_event("tab")); i += 1; continue
            if b in (127, 8):
                events.append(make_key_event("backspace")); i += 1; continue
            if b == 0:
                events.append(make_key_event("char", " ", {"ctrl"}, "ctrl-space")); i += 1; continue
            if 1 <= b <= 26:
                ch = chr(ord('a') + b - 1)
                events.append(make_key_event("char", ch, {"ctrl"})); i += 1; continue
            if 28 <= b <= 31:
                ch = {28: "\\", 29: "]", 30: "^", 31: "_"}[b]
                events.append(make_key_event("char", ch, {"ctrl"})); i += 1; continue
            if b == 27:
                events.append(make_key_event("esc")); i += 1; continue
            ch, consumed = _decode_one(buf[i:])
            if ch is None:
                incomplete = True; break
            if ch == " ":
                events.append(make_key_event("char", " ", set(), "space"))
            else:
                mods = {"shift"} if ch.isupper() else set()
                events.append(make_key_event("char", ch, mods))
            i += consumed
        rest = buf[i:] if incomplete else (buf[i:] if i < len(buf) else b"")
        # If we stopped due incomplete at position i, keep remainder
        if incomplete:
            rest = buf[i:]
        else:
            rest = buf[i:]
        return events, rest

    def _csi_event(self, params_str, final):
        # mouse SGR
        if params_str.startswith("<"):
            parts = params_str[1:].split(";")
            try:
                bval = int(parts[0]); x = int(parts[1]); y = int(parts[2])
            except Exception: return None
            pressed = final == "M"
            return {"code": "mouse", "name": "mouse", "char": None, "modifiers": set(), "mouse": {"button": bval, "x": x, "y": y, "pressed": pressed}}
        parts = [p for p in params_str.split(";") if p != ""]
        def pint(idx, default=1):
            try: return int(parts[idx])
            except Exception: return default
        mod_param = pint(1, 1) if len(parts) > 1 else 1
        # kitty protocol char: code;mod u
        if final == "u" and parts:
            try: cp = int(parts[0])
            except Exception: return None
            m = pint(1, 1)
            mods = set()
            bits = m - 1
            if bits & 4: mods.add("ctrl")
            if bits & 2: mods.add("alt")
            if bits & 1: mods.add("shift")
            ch = chr(cp) if 0 <= cp < 0x110000 else ""
            return make_key_event("char", ch, mods)
        mods = MOD_BY_PARAM.get(mod_param, set())
        if final in "ABCD":
            code = {"A": "up", "B": "down", "C": "right", "D": "left"}[final]
            return make_key_event(code, None, mods)
        if final == "H": return make_key_event("home", None, mods)
        if final == "F": return make_key_event("end", None, mods)
        if final == "Z": return make_key_event("back-tab")
        if final in "PQRS":
            return make_key_event({"P": "f1", "Q": "f2", "R": "f3", "S": "f4"}[final], None, mods)
        if final == "~":
            code = pint(0, 0)
            if code == 200:
                return None  # bracketed paste start handled poorly; ignored
            if code == 201:
                return None
            name = NAV_CODES.get(code)
            if name: return make_key_event(name, None, mods)
            return None
        return None

def _decode_one(data):
    if not data: return None, 0
    b0 = data[0]
    if b0 < 0x80:
        return chr(b0), 1
    # utf8 multi-byte
    try:
        s = data.decode("utf-8")
        return s[0], len(s[0].encode("utf-8"))
    except UnicodeDecodeError:
        # try shorter slices
        for ln in range(2, min(5, len(data) + 1)):
            try:
                s = data[:ln].decode("utf-8")
                return s[0], ln
            except UnicodeDecodeError:
                continue
        return data[:1].decode("utf-8", "surrogateescape"), 1
