class CliError(Exception):
    pass

def _eprint(msg):
    sys.stderr.write(msg)

def _os_error_text(e):
    if getattr(e, "errno", None):
        return f"{os.strerror(e.errno)} (os error {e.errno})"
    return str(e)

FLAG_TOKENS = {"-h", "--help", "-V", "--version", "--force-focus", "--print-pwd-as-result", "--read-only", "--read0", "--write0", "-0", "--null"}
OPTION_TOKENS = {"-c", "--config", "-C", "--extra-config", "--on-load", "--vroot", "-m", "--pipe-msg-in", "-M", "--print-msg-in"}
RECOGNIZED = FLAG_TOKENS | OPTION_TOKENS | {"-", "--"}

def _resolve_check(path, cwd):
    if path == "":
        raise CliError("empty string passed")
    resolved = absolutize(path, cwd)
    if not os.path.exists(resolved):
        raise CliError(f"path doesn't exist: {resolved}")
    return resolved

def _bin_path(cwd):
    arg0 = sys.argv[0] if sys.argv else "xplr"
    if "/" in arg0:
        return absolutize(arg0, cwd)
    for entry in os.environ.get("PATH", "").split(":"):
        cand = os.path.join(entry, arg0) if entry else arg0
        if os.path.isfile(cand) and os.access(cand, os.X_OK):
            return absolutize(cand, cwd)
    return absolutize(arg0, cwd)

def parse_cli(argv, cwd, stdin_reader):
    cli = {
        "help": False, "version": False, "force_focus": False, "print_pwd_as_result": False,
        "read_only": False, "read0": False, "write0": False,
        "config": None, "extra_configs": [], "on_load": [], "vroot": None,
        "path": None, "selections": [], "pipe_mode": None, "pipe_template": None, "pipe_values": [],
    }
    i = 0; n = len(argv); end_opts = False
    def add_positional(raw):
        resolved = _resolve_check(raw, cwd)
        if cli["path"] is None: cli["path"] = resolved
        else: cli["selections"].append(resolved)
    def read_stdin_paths():
        data = stdin_reader()
        delim = "\0" if cli["read0"] else "\n"
        if data == "": return
        parts = data.split(delim)
        if data.endswith(delim): parts = parts[:-1]
        for part in parts:
            if part == "":
                raise CliError("empty string passed")
            add_positional(part)
    while i < n:
        arg = argv[i]
        if not end_opts and arg == "":
            raise CliError("empty string passed")
        if end_opts:
            add_positional(arg); i += 1; continue
        if arg == "--":
            end_opts = True; i += 1; continue
        if arg == "-":
            read_stdin_paths(); i += 1; continue
        if arg in ("-m", "--pipe-msg-in", "-M", "--print-msg-in"):
            if i + 1 >= n:
                raise CliError(f"usage: xplr {arg} FORMAT [ARGUMENT]...")
            cli["pipe_mode"] = "print" if arg in ("-M", "--print-msg-in") else "pipe"
            cli["pipe_template"] = argv[i+1]
            cli["pipe_values"] = argv[i+2:]
            i = n; break
        if arg in ("-c", "--config"):
            if i + 1 >= n:
                raise CliError(f"usage: xplr {arg} PATH")
            cli["config"] = _resolve_check(argv[i+1], cwd); i += 2; continue
        if arg == "--vroot":
            if i + 1 >= n:
                raise CliError("usage: xplr --vroot PATH")
            cli["vroot"] = _resolve_check(argv[i+1], cwd); i += 2; continue
        if arg in ("-C", "--extra-config"):
            i += 1
            while i < n:
                nxt = argv[i]
                if nxt in RECOGNIZED: break
                if nxt.startswith("-") and nxt != "": break
                cli["extra_configs"].append(_resolve_check(nxt, cwd)); i += 1
            continue
        if arg == "--on-load":
            i += 1
            while i < n:
                nxt = argv[i]
                if nxt in RECOGNIZED: break
                if nxt.startswith("-") and nxt != "": break
                try:
                    cli["on_load"].append(parse_message_lenient(nxt))
                except YamlSyntaxError as e:
                    raise CliError(e.display())
                except MessageError as e:
                    raise CliError(str(e))
                i += 1
            continue
        if arg in FLAG_TOKENS:
            if arg in ("-h", "--help"): cli["help"] = True
            elif arg in ("-V", "--version"): cli["version"] = True
            elif arg == "--force-focus": cli["force_focus"] = True
            elif arg == "--print-pwd-as-result": cli["print_pwd_as_result"] = True
            elif arg == "--read-only": cli["read_only"] = True
            elif arg == "--read0": cli["read0"] = True
            elif arg == "--write0": cli["write0"] = True
            elif arg in ("-0", "--null"): cli["read0"] = True; cli["write0"] = True
            i += 1; continue
        if arg.startswith("-"):
            raise CliError(f'invalid argument: "{arg}", try `-- "{arg}"` or `--help`')
        add_positional(arg); i += 1
    return cli

def handle_pipe_message(cli):
    try:
        msg = format_message(cli["pipe_template"], cli["pipe_values"])
    except JfError as e:
        _eprint(f"error: xplr -m: {e}\n"); return 1
    except MessageError as e:
        _eprint(f"error: {e}\n"); return 1
    out = msg_to_json(msg)
    if cli["pipe_mode"] == "print":
        sys.stdout.write(out); sys.stdout.flush(); return 0
    pipe = os.environ.get("XPLR_PIPE_MSG_IN")
    if pipe is None:
        sys.stdout.write(out + "\n"); sys.stdout.flush(); return 0
    try:
        with open(pipe, "rb") as f: first = f.read(1)
    except OSError as e:
        _eprint(f"error: {_os_error_text(e)}\n"); return 1
    if not first:
        _eprint("error: failed to detect delimmiter\n"); return 1
    try:
        with open(pipe, "ab") as f: f.write(out.encode("utf-8", "surrogateescape") + first)
    except OSError as e:
        _eprint(f"error: {_os_error_text(e)}\n"); return 1
    return 0

def _config_candidate(cli):
    if cli["config"]: return cli["config"]
    xdg = os.environ.get("XDG_CONFIG_HOME")
    home = os.environ.get("HOME") or os.path.expanduser("~")
    if xdg and os.path.isabs(xdg): base = xdg
    else: base = os.path.join(home, ".config")
    cand = os.path.join(base, "xplr", "init.lua")
    if os.path.exists(cand): return cand
    if os.path.exists("/etc/xplr/init.lua"): return "/etc/xplr/init.lua"
