    from app import App, FatalError, AppQuit
    try:
        app = App(cli, config, hooks, state, startup_logs)
    except FatalError as e:
        _eprint(f"error: {e}\n"); return 1
    except SystemExit as e:
        return int(e.code or 0)
    from terminal import Terminal
    try:
        term = Terminal()
    except OSError as e:
        _eprint(f"error: {_os_error_text(e)}\n"); return 1
    app.runner = term
    app.terminal_size = term.get_size()
    # start fifo from config
    queue = deque()
    start_fifo = config["general"].get("start_fifo")
    if start_fifo:
        from messages import Msg
        queue.append(Msg("StartFifo", start_fifo))
    for m in app.hooks.get("on_load") or []: queue.append(m)
    for m in cli["on_load"]: queue.append(m)
    term.enter(mouse=app.mouse_enabled)
    output = ""; code = 0
    try:
        if queue:
            app.process_queue(queue)
        while True:
            # sync dynamic mouse state / size
            app.terminal_size = term.get_size()
            from ui import Renderer, canvas_to_ansi
            renderer = Renderer(app, app.terminal_size[0], app.terminal_size[1])
            canvas = renderer.render()
            term.draw(canvas_to_ansi(canvas, renderer.cursor), mouse=app.mouse_enabled)
            events = term.read_events_blocking()
            for ev in events:
                if ev.get("code") == "resize":
                    continue
                if ev.get("code") == "eof":
                    continue
                q = deque()
                app.current_key = ev
                try:
                    msgs = app.handle_key_event(ev)
