def handle_pipe_message(cli):
    try:
        msg = format_message(cli["pipe_template"], cli["pipe_values"])
    except JfError as e:
        _eprint(f"error: xplr -m: {e}\n"); return 1
    except MessageError as e:
        _eprint(f"error: {e}\n"); return 1
    out = msg_to_json(msg)
    if cli["pipe_mode"] == "print":
        sys.stdout.write(out); sys.stdout.flush(); return 0
    pipe = os.environ.get("XPLR_PIPE_MSG_IN")
    if pipe is None:
        sys.stdout.write(out + "\n"); sys.stdout.flush(); return 0
    try:
        with open(pipe, "rb") as f: first = f.read(1)
    except OSError as e:
        _eprint(f"error: {_os_error_text(e)}\n"); return 1
    if not first:
        _eprint("error: failed to detect delimmiter\n"); return 1
    try:
        with open(pipe, "ab") as f: f.write(out.encode("utf-8", "surrogateescape") + first)
    except OSError as e:
        _eprint(f"error: {_os_error_text(e)}\n"); return 1
    return 0

def _config_candidate(cli):
    if cli["config"]: return cli["config"]
    xdg = os.environ.get("XDG_CONFIG_HOME")
    home = os.environ.get("HOME") or os.path.expanduser("~")
    if xdg and os.path.isabs(xdg): base = xdg
    else: base = os.path.join(home, ".config")
    cand = os.path.join(base, "xplr", "init.lua")
    if os.path.exists(cand): return cand
    if os.path.exists("/etc/xplr/init.lua"): return "/etc/xplr/init.lua"
    return None

def _lua_error_text_state(state, e):
    from app import App
    if isinstance(e, LuaSyntaxError): return "syntax error: " + e.text
    if isinstance(e, LuaError):
        msg = e.value if isinstance(e.value, str) else str(e)
        trace = getattr(e, "trace", None)
        return f"runtime error: {msg}\n{trace}" if trace else f"runtime error: {msg}"
    return str(e)

def load_configs(cli, state):
    from app import Log
    logs = []
    extracted = None
    hooks = configconv.empty_hooks()
    files = []
    cand = _config_candidate(cli)
    if cand: files.append(cand)
    files.extend(cli["extra_configs"])
    import copy as _copy
    from default_config import DEFAULT_CONFIG
    extracted = _copy.deepcopy(DEFAULT_CONFIG)
    for path in files:
        state.globals.rawset("version", None)
        error = None
        ret_first = None
        try:
            with open(path, "rb") as f: raw = f.read()
        except OSError as e:
            logs.append(Log("ERROR", _os_error_text(e))); continue
        code = raw.decode("utf-8", "surrogateescape")
        display = f'[string "{path}"]'
        try:
            vals = load_lua_chunk(state, code, display)
            ret_first = vals[0] if vals else None
        except LuaSyntaxError as e:
            logs.append(Log("ERROR", "syntax error: " + e.text)); continue
        except LuaError as e:
            logs.append(Log("ERROR", _lua_error_text_state(state, e))); continue
        # version
        version = state.globals.rawget("version")
        if not isinstance(version, str):
            logs.append(Log("ERROR", f"'version' must be defined globally in {path}")); continue
        if not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+([-.+][0-9A-Za-z.-]+)?", version):
            logs.append(Log("ERROR", "invalid digit found in string")); continue
        major, minor = int(version.split(".")[0]), int(version.split(".")[1])
        if major != 1 or minor > 1:
            logs.append(Log("ERROR", f"incompatible script version in: {path}. The script version is: {version}, the required version is: {VERSION}. Visit https://xplr.dev/en/upgrade-guide")); continue
        xplr = state.globals.rawget("xplr")
        try:
            if not isinstance(xplr, LuaTable): raise configconv.ConfigError("deserialize error: invalid type: unit value, expected table")
            new_config = configconv.conv_config(xplr.rawget("config"))
            new_hooks = configconv.conv_hooks(ret_first)
        except configconv.ConfigError as e:
            logs.append(Log("ERROR", str(e))); continue
        extracted = new_config
        for k in hooks: hooks[k].extend(new_hooks[k])
    return extracted, hooks, logs

def main(argv=None):
    if argv is None: argv = sys.argv[1:]
    cwd = os.getcwd()
    try:
        cli = parse_cli(argv, cwd, lambda: sys.stdin.buffer.read().decode("utf-8", "surrogateescape"))
    except CliError as e:
        _eprint(f"error: {e}\n"); return 1
    if cli["help"]:
        sys.stdout.write(HELP_TEXT); return 0
    if cli["version"]:
        sys.stdout.write(f"xplr {VERSION}\n"); return 0
    if cli["pipe_mode"]:
        return handle_pipe_message(cli)
    # vroot check
    if cli["vroot"]:
        from coreutil import normalize_abs, path_parent
        target = cli["path"] or cwd
        if os.path.isdir(target) and not cli["force_focus"]: effective = normalize_abs(target)
        else: effective = path_parent(target)
        vroot = cli["vroot"]
        if not (effective == vroot or effective.startswith(vroot + "/") or vroot == "/"):
            _eprint(f'error: "{effective}" is outside of virtual root "{vroot}"\n'); return 1
    cli["bin"] = _bin_path(cwd)
    cli["cwd"] = cwd
    # lua + config
    state = build_lua_state()
    try:
        config, hooks, startup_logs = load_configs(cli, state)
    except SystemExit as e:
        return int(e.code or 0)
    cli["session_path"] = os.path.join(tempfile.gettempdir(), "xplr", "session", str(os.getpid()))
    from app import App, FatalError, AppQuit
    try:
        app = App(cli, config, hooks, state, startup_logs)
    except FatalError as e:
        _eprint(f"error: {e}\n"); return 1
    except SystemExit as e:
        return int(e.code or 0)
    from terminal import Terminal
    try:
        term = Terminal()
    except OSError as e:
        _eprint(f"error: {_os_error_text(e)}\n"); return 1
    app.runner = term
    app.terminal_size = term.get_size()
    # start fifo from config
    queue = deque()
    start_fifo = config["general"].get("start_fifo")
    if start_fifo:
        from messages import Msg
        queue.append(Msg("StartFifo", start_fifo))
    for m in app.hooks.get("on_load") or []: queue.append(m)
    for m in cli["on_load"]: queue.append(m)
    term.enter(mouse=app.mouse_enabled)
    output = ""; code = 0
    try:
        if queue:
            app.process_queue(queue)
        while True:
            # sync dynamic mouse state / size
            app.terminal_size = term.get_size()
            from ui import Renderer, canvas_to_ansi
            renderer = Renderer(app, app.terminal_size[0], app.terminal_size[1])
            canvas = renderer.render()
            term.draw(canvas_to_ansi(canvas, renderer.cursor), mouse=app.mouse_enabled)
            events = term.read_events_blocking()
            for ev in events:
                if ev.get("code") == "resize":
                    continue
                if ev.get("code") == "eof":
                    continue
                q = deque()
                app.current_key = ev
                try:
                    msgs = app.handle_key_event(ev)
                    for m in msgs: q.append(m)
                    if q: app.process_queue(q)
                finally:
                    app.current_key = None
    except AppQuit as q:
        output = q.output; code = q.code
    except KeyboardInterrupt:
        code = 1
    finally:
        if app.fifo_file is not None:
            try: app.fifo_file.close()
            except Exception: pass
        try: os.removedirs(app.pipe_path)
        except OSError: pass
        term.exit()
    if output:
        try:
            sys.stdout.buffer.write(output.encode("utf-8", "surrogateescape")); sys.stdout.buffer.flush()
        except Exception:
            sys.stdout.write(output)
    return code

if __name__ == "__main__":
    sys.exit(main())
